# === Catálogo de módulos (sistema Multi-Proyecto Modular) ===================
# Cada plantilla puede encenderse independientemente en cualquiera de las 3
# categorías de informe (Diario/Semanal/Mensual) — un módulo NO vive bajo una
# única cadencia fija. El Coordinador decide, por informe, si el recuento de
# actividades de esa plantilla debe aparecer ahí (ver `_ensure_modulo_activo`
# para el gate de captura/menú — OR entre las 3 categorías — y
# `_modulos_categoria_para_export` para qué categoría manda al exportar). Si
# una clave no aparece aquí, se ignora al guardar `modulos` (evita que un
# payload arbitrario cree módulos "fantasma" que ninguna pantalla sabe
# renderizar).
MODULOS_KEYS = {
    "seguridad_higiene", "forestal_arbolado",
    "gestion_riesgos", "estudios_proyecto", "impacto_ambiental",
    "tabla_resumen", "estado_tiempo", "control_obra",
}
MODULOS_DIARIOS = MODULOS_KEYS
MODULOS_SEMANALES = MODULOS_KEYS
MODULOS_MENSUALES = MODULOS_KEYS
MODULOS_CATALOG = {
    "reportes_diarios": MODULOS_DIARIOS,
    "reportes_semanales": MODULOS_SEMANALES,
    "reportes_mensuales": MODULOS_MENSUALES,
}


def _sanitize_modulos(value: Optional[dict]) -> dict:
    """Normaliza el objeto `modulos`: sólo conserva claves conocidas por
    categoría (ver MODULOS_CATALOG) con valor bool; el resto (categorías o
    módulos desconocidos) se descarta en silencio. Los módulos no
    mencionados explícitamente en `value` quedan apagados por default —
    nunca se asume "encendido" para un módulo nuevo sin confirmación
    explícita del Coordinador."""
    out: dict = {}
    value = value or {}
    for categoria, claves_validas in MODULOS_CATALOG.items():
        cat_in = value.get(categoria) if isinstance(value, dict) else None
        cat_out = {}
        for clave in claves_validas:
            v = cat_in.get(clave) if isinstance(cat_in, dict) else None
            cat_out[clave] = bool(v) if isinstance(v, bool) else False
        out[categoria] = cat_out
    return out


def _sanitize_reference_files(items) -> list:
    """Valida y limpia la lista de archivos de referencia.
    Espera una lista de dicts con 'name' y 'url'.
    Descarta entradas vacías o malformadas. Máximo 50 elementos."""
    if not items or not isinstance(items, list):
        return []
    cleaned = []
    for it in items[:50]:
        if not isinstance(it, dict):
            continue
        name = (it.get("name") or "").strip()
        url = (it.get("url") or "").strip()
        if not name or not url:
            continue
        # Limitar tamaños para evitar payloads abusivos
        cleaned.append({"name": name[:200], "url": url[:1000]})
    return cleaned

