    # Coordenadas objetivo dictadas por el Coordinador desde oficina (sólo aplican
    # a nodos hoja con measurement_type == "coord_latlon"). El Especialista las
    # ve en modo solo-lectura al capturar.
    target_lat: Optional[float] = None
    target_lon: Optional[float] = None
    target_elev: Optional[float] = None
    # Ubicación GPS real del nodo (grados decimales WGS84), tomada con el
    # dispositivo. Independiente de target_* (que en la práctica guardan UTM).
    # Ambos o ninguno; ver `validar_gps_nodo`.
    gps_lat: Optional[float] = None
    gps_lon: Optional[float] = None
    # Estatus de acceso al predio y situación social/liberación física, capturados
    # a nivel de nodo (vigentes al momento de consulta, no por reporte/período).
    # Usados en la página de resumen por subtramo del export PDF/PPTX.
    acceso_predio: Optional[str] = None
    situacion_social: Optional[str] = None
    # Tipo de formato del resumen impreso por Subtramo (ver
    # `draw_subtramo_summary_page`/`_slide`): "estacion" (default histórico,
    # Acceso al Predio + Situación Social singular) o "intertramo" (Situación
    # Social plural + tabla "Actividad en Postes" con los hijos directos del
    # nodo). None = tratar como "estacion" (compatibilidad con nodos viejos).
    tipo_nodo: Optional[Literal["estacion", "intertramo"]] = None
    # Solo para hijos de un nodo tipo "intertramo" (un "Poste"): nombre de
    # lugar mostrado en la columna UBICACIÓN de la tabla Actividad en Postes.
    ubicacion: Optional[str] = None
    # Estatus por actividad de este Poste, columnas de la tabla Actividad en
    # Postes del Intertramo padre. None = celda en blanco (sin capturar).
    # "cambio_trayectoria": 4to estado de EXCEPCIÓN (módulo "Control de
    # Obra") — el poste cambió de posición planeada y necesita revisión;
    # cuenta como "sin avance" en el % pero se resalta aparte como alerta.
    estatus_pilas: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_cabezal: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_fuste: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_poste: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None


