# === Helpers ================================================================
def hash_pw(pw: str) -> str:
    return bcrypt.hashpw(pw.encode(), bcrypt.gensalt(rounds=10)).decode()


def verify_pw(pw: str, h: str) -> bool:
    try:
        return bcrypt.checkpw(pw.encode(), h.encode())
    except Exception:
        return False


def make_token(user_id: str) -> str:
    exp = datetime.now(timezone.utc) + timedelta(minutes=JWT_EXPIRE_MINUTES)
    return jwt.encode({"sub": user_id, "exp": exp}, JWT_SECRET, algorithm=JWT_ALGORITHM)


async def current_user(creds: Optional[HTTPAuthorizationCredentials] = Depends(bearer)) -> dict:
    if not creds:
        raise HTTPException(401, "Token requerido")
    try:
        payload = jwt.decode(creds.credentials, JWT_SECRET, algorithms=[JWT_ALGORITHM])
        uid = payload.get("sub")
    except jwt.PyJWTError:
        raise HTTPException(401, "Token inválido")
    u = await db.users.find_one({"id": uid})
    if not u or u.get("deleted_at"):
        raise HTTPException(401, "Usuario no existe")
    u.pop("_id", None)
    u.pop("password", None)
    return u


def require_role(*allowed_roles: str):
    async def dep(user: dict = Depends(current_user)) -> dict:
        if user["role"] not in allowed_roles:
            raise HTTPException(403, f"Rol no autorizado: {user['role']}")
        return user
    return dep


def user_to_out(u: dict) -> dict:
    return {
        "id": u["id"],
        "email": u["email"],
        "name": u["name"],
        "role": u["role"],
        "area": u.get("area"),
        "area_id": u.get("area_id"),
        "puesto": u.get("puesto"),
        "no_control": u.get("no_control"),
        "scope_node_id": u.get("scope_node_id"),
        "scope_node_ids": u.get("scope_node_ids") or [],
        "project_ids": u.get("project_ids") or [],
        "expo_push_tokens": u.get("expo_push_tokens") or [],
        "created_at": u.get("created_at", datetime.now(timezone.utc)),
    }


# === FECHAS DEL PROYECTO (X-04 / A-08 / K-05) ================================
# Única fuente de "hoy", inicio de día y semana. Todo se calcula en la zona
# horaria del proyecto (`zona_horaria`, por defecto America/Mexico_City), nunca
# en UTC ni en la hora del servidor. La semana va de lunes a domingo salvo que el
# proyecto configure otro `dia_inicio_semana`.
ZONA_POR_DEFECTO = "America/Mexico_City"
DIAS_SEMANA = {"LUNES": 0, "MARTES": 1, "MIERCOLES": 2, "JUEVES": 3, "VIERNES": 4, "SABADO": 5, "DOMINGO": 6}


def validar_zona_horaria(nombre: Optional[str]) -> Optional[str]:
    """Devuelve el nombre IANA si es válido; ValueError si no. Vacío -> None (usa el defecto)."""
    n = (nombre or "").strip()
    if not n:
        return None
    try:
        ZoneInfo(n)
    except Exception:
        raise ValueError(f"Zona horaria no válida: {n}")
    return n


def zona_proyecto(project: Optional[dict] = None):
    nombre = (project or {}).get("zona_horaria") or ZONA_POR_DEFECTO
    try:
        return ZoneInfo(nombre)
    except Exception:
        return MX_TZ


def hoy_proyecto(project: Optional[dict] = None, ahora_utc: Optional[datetime] = None) -> date:
    """Fecha de hoy EN LA ZONA DEL PROYECTO."""
    ahora = ahora_utc or datetime.now(timezone.utc)
    return ahora.astimezone(zona_proyecto(project)).date()


def offset_min_proyecto(project: Optional[dict] = None, ahora_utc: Optional[datetime] = None) -> int:
    """Desfase actual de la zona respecto a UTC, en minutos (CDMX = -360)."""
    ahora = ahora_utc or datetime.now(timezone.utc)
    off = ahora.astimezone(zona_proyecto(project)).utcoffset()
    return int(off.total_seconds() // 60) if off is not None else 0


def inicio_dia_utc(fecha: date, project: Optional[dict] = None) -> datetime:
    """00:00 del día `fecha` en la zona del proyecto, expresado en UTC."""
    local = datetime(fecha.year, fecha.month, fecha.day, tzinfo=zona_proyecto(project))
    return local.astimezone(timezone.utc)


def inicio_semana(hoy: date, dia_inicio: Optional[str] = "LUNES") -> date:
    objetivo = DIAS_SEMANA.get((dia_inicio or "LUNES").upper(), 0)
    return hoy - timedelta(days=(hoy.weekday() - objetivo) % 7)


def semana_de(hoy: date, dia_inicio: Optional[str] = "LUNES") -> Tuple[date, date]:
    """(primer día, último día) de la semana que contiene `hoy`."""
    ini = inicio_semana(hoy, dia_inicio)
    return ini, ini + timedelta(days=6)


async def hoy_de(pid: str) -> date:
    """`hoy_proyecto` a partir del id del proyecto (una consulta ligera)."""
    proj = await db.projects.find_one({"id": pid}, {"zona_horaria": 1})
    return hoy_proyecto(proj)


async def ensure_project_access(user: dict, project_id: str) -> dict:
    """Valida que el usuario tenga acceso a un proyecto; devuelve el proyecto.

    Excluye `general_data_images`/`constructora_logo`: son binarios pesados
    (hasta 30 imágenes de 5MB c/u) que solo hacen falta en el modal "Datos
    Generales" o en las exportaciones. Este helper se llama en ~90 endpoints
    del proyecto (la mayoría descarta el valor de retorno, solo lo usan para
    el chequeo de acceso), así que traer esos campos aquí hacía lento
    CUALQUIER endpoint de un proyecto con varias imágenes cargadas — no solo
    GET /projects/{pid}. Quien sí necesite las imágenes las pide aparte via
    GET /projects/{pid}/general-data-images.
    """
    p = await db.projects.find_one(
        {"id": project_id, "archived": {"$ne": True}},
        {"general_data_images": 0, "constructora_logo": 0},
    )
    if not p:
        raise HTTPException(404, "Proyecto no existe")
    if user["role"] in (ROLE_COORD, ROLE_JEFE):
        return p  # acceso global (Coordinador General y Jefe de Proyecto)
    if project_id not in (user.get("project_ids") or []):
        raise HTTPException(403, "Sin acceso a este proyecto")
    return p


async def build_node_path(node: dict) -> List[str]:
    """Devuelve la cadena de IDs desde raíz hasta self (incluido)."""
    path = [node["id"]]
    cur = node
    while cur.get("parent_id"):
        parent = await db.location_nodes.find_one({"id": cur["parent_id"]})
        if not parent:
            break
        path.insert(0, parent["id"])
        cur = parent
    return path


async def node_path_names(node_id: str) -> List[str]:
    node = await db.location_nodes.find_one({"id": node_id})
    if not node:
        return []
    ids = await build_node_path(node)
    names: List[str] = []
    for nid in ids:
        n = await db.location_nodes.find_one({"id": nid})
        if n:
            names.append(n["name"])
    return names


async def descendants_ids(root_id: str) -> List[str]:
    """Devuelve TODOS los descendientes (incluyendo root_id) de un nodo."""
    out = [root_id]
    queue = [root_id]
    while queue:
        pid = queue.pop(0)
        children = await db.location_nodes.find({"parent_id": pid}).to_list(length=10000)
        for c in children:
            out.append(c["id"])
            queue.append(c["id"])
    return out


# === Startup: wipe legacy ===================================================
@app.on_event("startup")
async def startup_event():
    # Eliminar colecciones legacy de la versión anterior
    existing = await db.list_collection_names()
    for c in COLLECTIONS_LEGACY:
        if c in existing:
            await db[c].drop()
            log.info(f"[wipe] Dropped legacy collection: {c}")
    # Indexes esenciales
    await db.users.create_index("email", unique=True)
    await db.users.create_index("id", unique=True)
    await db.projects.create_index("id", unique=True)
    await db.invitations.create_index("token", unique=True)
    await db.location_nodes.create_index([("project_id", 1), ("parent_id", 1)])
    await db.reports.create_index([("project_id", 1), ("created_at", -1)])
    # Soporta el MAX(ultima_lectura) agrupado por node_id que arma el árbol de
    # nodos (list_nodes) — antes escaneaba todo el historial de reportes del
    # proyecto sin índice en cada carga del hub.
    await db.reports.create_index([("project_id", 1), ("node_id", 1), ("ultima_lectura", 1)])
    await db.daily_goals.create_index("project_id")
    # TTL: "Metas del día" caducan solas a las 24h de creadas — antes se
    # quedaban visibles para siempre, contradiciendo su propio nombre.
    await db.daily_goals.create_index("created_at", expireAfterSeconds=86400)
    await db.actividades_curadas.create_index([("project_id", 1), ("area_id", 1)])
    await db.actividades_curadas.create_index("reporte_origen_id")
    await db.actividades_curadas.create_index("id")
    # [OFFLINE 2026-08-07] sparse=True: reportes sin client_id (clientes viejos)
    # no deben colisionar entre si en el índice único.
    await db.reports.create_index("client_id", unique=True, sparse=True)
    await db.announcements.create_index([("project_id", 1), ("pinned", -1), ("created_at", -1)])
    # TTL: Mongo purga automaticamente noticias vencidas (expires_at en el pasado).
    await db.announcements.create_index("expires_at", expireAfterSeconds=0)
    await db.minutas.create_index([("project_id", 1), ("created_at", -1)])
    await db.minutas.create_index([("project_id", 1), ("acuerdos.responsable_id", 1)])
    await db.minutas.create_index([("project_id", 1), ("involved_ids", 1)])
    await db.messages.create_index([("project_id", 1), ("created_at", -1)])
    await db.messages.create_index([("channel_id", 1), ("created_at", -1)])
    await db.events.create_index([("project_id", 1), ("start_at", 1)])
    await db.events.create_index([("project_id", 1), ("attendee_ids", 1)])
    # Consultada por el loop de recordatorios (_meeting_reminder_loop), que
    # escanea TODOS los proyectos por start_at — no puede aprovechar el
    # índice compuesto de arriba, que empieza por project_id.
    await db.events.create_index([("start_at", 1), ("reminder_sent", 1)])
    await db.channels.create_index([("project_id", 1), ("type", 1)])
    await db.channels.create_index([("project_id", 1), ("type", 1), ("area_id", 1)])
    await db.channels.create_index([("project_id", 1), ("type", 1), ("member_ids", 1)])
    # TTL: sesiones de importación de catálogo abandonadas (usuario subió un
    # archivo y nunca terminó el wizard) se purgan solas a las 24h — evita
    # que catalogo_import_sessions crezca indefinidamente con huérfanas.
    await db.catalogo_import_sessions.create_index("created_at", expireAfterSeconds=86400)
    # Mismo criterio para las sesiones de importación del Programa desglosado
    # (colección propia — el destino final de este wizard no es el mismo que
    # el del catálogo, ver sección "PROGRAMA DESGLOSADO" más abajo).
    await db.programa_import_sessions.create_index("created_at", expireAfterSeconds=86400)
    # Índice en `id` (UUID propio, no el `_id` de Mongo) para las colecciones
    # consultadas por id en el hot path de navegación (abrir nodo/área/canal/
    # evento/minuta/reporte individual, editar catálogo) — sin esto cada
    # find_one({"id": ...}) hacía COLLSCAN completo de la colección.
    # No se usa unique=True: no hay forma de verificar aquí en startup que
    # los datos existentes no tengan duplicados legacy, y una violación
    # tumbaría el arranque del server.
    await db.location_nodes.create_index("id")
    await db.reports.create_index("id")
    await db.areas.create_index("id")
    await db.channels.create_index("id")
    await db.events.create_index("id")
    await db.minutas.create_index("id")
    await db.partidas.create_index("id")
    await db.conceptos.create_index("id")
    await db.registros_avance.create_index("id")
    # Idempotencia de la cola offline de avances. Índice parcial: solo aplica a los
    # registros con client_id de texto (los viejos guardan null). Si ya hubiera
    # duplicados legados, no se tumba el arranque: queda la revisión por consulta.
    try:
        await db.registros_avance.create_index(
            "client_id", unique=True, partialFilterExpression={"client_id": {"$type": "string"}},
        )
    except Exception as e:
        log.warning(f"[avance] no se pudo crear el índice único de client_id: {e}")
    await db.catalogo_import_sessions.create_index("id")
    await db.programa_import_sessions.create_index("id")
    # Etapa EVM: mismo criterio de TTL 24h que catalogo/programa (sesiones
    # de importación abandonadas), colección propia para no interferir con
    # el importador legado mientras coexistan (ver Importador Maestro).
    await db.evm_import_sessions.create_index("created_at", expireAfterSeconds=86400)
    await db.evm_import_sessions.create_index("id")
    await db.gastos_reales.create_index("id")
    await db.gastos_reales.create_index([("project_id", 1), ("fecha", 1)])
    await db.programa_versiones.create_index("id")
    await db.programa_versiones.create_index([("project_id", 1), ("vigente", 1)])
    await db.programa_distribucion.create_index("id")
    await db.programa_distribucion.create_index([("programa_version_id", 1)])
    await db.report_templates.create_index("code", unique=True)
    await db.report_templates.create_index("id", unique=True)
    await db.forestal_registros.create_index("id", unique=True)
    await db.forestal_registros.create_index([("project_id", 1), ("created_at", -1)])
    await db.forestal_autorizado.create_index("id", unique=True)
    await db.forestal_autorizado.create_index([("project_id", 1), ("orden", 1)])
    await db.tabla_resumen_actividades.create_index("id", unique=True)
    await db.tabla_resumen_actividades.create_index([("project_id", 1), ("orden", 1)])
    await db.tabla_resumen_columnas.create_index("id", unique=True)
    await db.tabla_resumen_columnas.create_index([("project_id", 1), ("orden", 1)])
    await db.tabla_resumen_celdas.create_index("id", unique=True)
    await db.tabla_resumen_celdas.create_index(
        [("project_id", 1), ("actividad_id", 1), ("columna_id", 1)], unique=True,
    )
    await db.weather_logs.create_index("id", unique=True)
    await db.weather_logs.create_index([("project_id", 1), ("node_id", 1), ("fecha_cdmx", 1)], unique=True)
    await db.cimentacion_elementos.create_index("id", unique=True)
    await db.cimentacion_elementos.create_index([("project_id", 1), ("node_id", 1)])
    await db.perforadoras.create_index("id", unique=True)
    await db.perforadoras.create_index([("project_id", 1)])
    await db.seguridad_reportes.create_index("id", unique=True)
    await db.seguridad_reportes.create_index([("project_id", 1), ("created_at", -1)])
    await db.seguridad_checklist.create_index("id", unique=True)
    await db.seguridad_checklist.create_index([("project_id", 1), ("created_at", -1)])
    await db.riesgos_registros.create_index("id", unique=True)
    await db.riesgos_registros.create_index([("project_id", 1), ("created_at", -1)])
    await db.estudios_actividades.create_index("id", unique=True)
    await db.estudios_actividades.create_index([("project_id", 1), ("orden", 1)])
    await db.estudios_bitacora.create_index("id", unique=True)
    await db.estudios_bitacora.create_index([("project_id", 1), ("created_at", -1)])
    await db.ambiental_auditoria.create_index("id", unique=True)
    await db.ambiental_auditoria.create_index([("project_id", 1), ("created_at", -1)])
    # Presentación — seguimiento de estudios por disciplina: un valor
    # ACTUAL por (proyecto, estación|None=global, disciplina), nunca una
    # lista histórica — de ahí el índice único que habilita upsert real.
    await db.estudio_disciplina_avance.create_index("id", unique=True)
    await db.estudio_disciplina_avance.create_index(
        [("project_id", 1), ("node_id", 1), ("disciplina", 1)], unique=True,
    )
    await db.planos_avance.create_index("id", unique=True)
    await db.planos_avance.create_index([("project_id", 1), ("created_at", -1)])
    await db.presentaciones.create_index("id", unique=True)
    await db.presentaciones.create_index([("project_id", 1), ("fecha", -1)])
    await db.password_reset_requests.create_index("id", unique=True)
    await db.password_reset_requests.create_index([("status", 1), ("created_at", 1)])
    await db.password_reset_requests.create_index("user_id")
    await db.password_reset_tokens.create_index("token_hash", unique=True)
    await db.password_reset_tokens.create_index([("user_id", 1), ("created_at", 1)])

    # --- Seed de plantillas de reporte estructurado (idempotente por `code`) ---
    try:
        for tpl in SEED_REPORT_TEMPLATES:
            existing_tpl = await db.report_templates.find_one({"code": tpl["code"]})
            if existing_tpl:
                continue
            await db.report_templates.insert_one({"id": str(uuid.uuid4()), **tpl})
            log.info(f"[seed] Plantilla de reporte creada: {tpl['code']}")
    except Exception as e:
        log.warning(f"[seed] error sembrando report_templates: {e}")

    # --- Migración one-shot: reconcilia campos de plantillas de sistema que
    # cambiaron de definición (quitar "Elemento" duplicado, agregar opción
    # "N/A") — el seed de arriba es solo insert-si-falta-el-code, así que un
    # ambiente ya sembrado se quedaría con la definición vieja sin esto.
    try:
        _RECONCILE_TEMPLATE_CODES = {"calidad_colados", "calidad_acero", "calidad_revision_acero"}
        for tpl in SEED_REPORT_TEMPLATES:
            if tpl["code"] not in _RECONCILE_TEMPLATE_CODES:
                continue
            await db.report_templates.update_one(
                {"code": tpl["code"]},
                {"$set": {"fields": tpl["fields"], "name": tpl["name"], "category": tpl["category"]}},
            )
    except Exception as e:
        log.warning(f"[migrate] error reconciliando report_templates: {e}")

    # --- Migración one-shot: asegurar canal General + asignar channel_id a
    # mensajes legacy creados antes del refactor de canales.
    try:
        legacy_msgs = await db.messages.count_documents({"channel_id": {"$exists": False}})
        if legacy_msgs:
            log.info(f"[migrate] {legacy_msgs} mensajes legacy sin channel_id → asignando a General de cada proyecto")
            project_ids = await db.messages.distinct("project_id", {"channel_id": {"$exists": False}})
            for pid in project_ids:
                if not pid:
                    continue
                await _ensure_default_channels(pid)
                g = await db.channels.find_one({"project_id": pid, "type": "general"})
                if g:
                    await db.messages.update_many(
                        {"project_id": pid, "channel_id": {"$exists": False}},
                        {"$set": {"channel_id": g["id"]}},
                    )
            log.info("[migrate] mensajes legacy migrados al canal General")
    except Exception as e:
        log.warning(f"[migrate] error migrando mensajes legacy: {e}")

    # --- Migración one-shot: noticias creadas antes de la expiración de 24h
    # no tienen `expires_at`. Se les asigna created_at + 24h para que dejen
    # de acumularse indefinidamente (el índice TTL las purgará después).
    try:
        legacy_ann = await db.announcements.count_documents({"expires_at": {"$exists": False}})
        if legacy_ann:
            log.info(f"[migrate] {legacy_ann} noticias legacy sin expires_at → backfill")
            cursor = db.announcements.find({"expires_at": {"$exists": False}}, {"id": 1, "created_at": 1})
            async for doc in cursor:
                created = doc.get("created_at") or datetime.now(timezone.utc)
                if isinstance(created, str):
                    created = datetime.fromisoformat(created)
                await db.announcements.update_one(
                    {"id": doc["id"]},
                    {"$set": {"expires_at": created + timedelta(hours=ANNOUNCEMENT_TTL_HOURS)}},
                )
            log.info("[migrate] expires_at backfill de noticias legacy completado")
    except Exception as e:
        log.warning(f"[migrate] error en backfill de expires_at de noticias: {e}")

    # Loop en segundo plano: recordatorios push de reuniones (1h antes).
    asyncio.create_task(_meeting_reminder_loop())

    log.info("[startup] Dirac ready")


# === ROOT / HEALTH ==========================================================
@api.get("/")
async def root():
    return {"name": "Dirac", "status": "ok"}


@api.api_route("/health", methods=["GET", "HEAD"])
async def health():
    """Ping de la app (NetInfo), del banner "Sin conexión" y de los monitores.
    200 solo si Mongo responde; si no, 503 (la app no puede trabajar sin base)."""
    ts = datetime.now(timezone.utc).isoformat()
    try:
        await asyncio.wait_for(db.command("ping"), timeout=3)
    except Exception as e:  # noqa: BLE001 - cualquier fallo de la base = no saludable
        log.warning(f"[health] Mongo no responde: {e}")
        return JSONResponse(status_code=503, content={"ok": False, "db": False, "ts": ts})
    return {"ok": True, "db": True, "ts": ts}


