@api.get("/projects/{pid}")
async def get_project(pid: str, user: dict = Depends(current_user)):
    p = await ensure_project_access(user, pid)
    p.pop("_id", None)
    p.setdefault("reference_files", [])
    p.setdefault("contratistas_list", [])
    p.setdefault("contratos_list", [])
    p.setdefault("categorias_personal", [])
    p.setdefault("categorias_equipo", [])
    p.setdefault("objeto_contrato", None)
    p.setdefault("cliente_principal", None)
    p.setdefault("color_tema", "#003366")
    p.setdefault("color_institucional", "#003366")
    p.setdefault("report_text_color", "#0F172A")
    # `general_data_images` NO se incluye aquí a propósito (ver
    # ensure_project_access): puede pesar hasta 30 imágenes de 5MB. Solo se
    # manda el conteo (vía $size, sin transferir el array) para el badge de
    # la UI; el contenido real se pide bajo demanda en
    # GET /projects/{pid}/general-data-images cuando se abre ese modal.
    p["general_data_images"] = []
    count_doc = await db.projects.aggregate([
        {"$match": {"id": pid}},
        {"$project": {"_id": 0, "n": {"$size": {"$ifNull": ["$general_data_images", []]}}}},
    ]).to_list(length=1)
    p["general_data_images_count"] = count_doc[0]["n"] if count_doc else 0
    p.setdefault("minuta_code_prefix", None)
    p.setdefault("tipo_contrato", "PRECIOS_UNITARIOS")
    p.setdefault("modo_avance", "CANTIDAD")
    p.setdefault("nombres_niveles_partida", [])
    p.setdefault("nombre_nivel_concepto", "")
    p.setdefault("unidades_personalizadas", [])
    p.setdefault("etapas_poste", _ETAPAS_POSTE_DEFAULT)
    p.setdefault("titulo_modulo_catalogo", "")
    p.setdefault("cadencia_reporte", "MENSUAL")
    p.setdefault("dia_inicio_semana", "LUNES")
    p["zona_horaria"] = p.get("zona_horaria") or ZONA_POR_DEFECTO
    p.setdefault("separador_decimal", ".")
    p["hoy"] = hoy_proyecto(p).isoformat()
    p["tz_offset_min"] = offset_min_proyecto(p)
    p["modulos"] = _sanitize_modulos(p.get("modulos"))
    return p


@api.put("/projects/{pid}")
async def update_project(pid: str, body: ProjectPatch, user: dict = Depends(require_role(ROLE_COORD))):
    """PATCH parcial: sólo actualiza los campos enviados.

    Permite, por ejemplo, actualizar únicamente `objeto_contrato` o catálogos
    sin tener que reenviar name/constructora/contract_number.
    """
    existing = await db.projects.find_one({"id": pid})
    if not existing:
        raise HTTPException(404, "Proyecto no existe")

    upd: dict = {}
    if body.name is not None:
        n = body.name.strip()
        if n:
            upd["name"] = n
    if body.constructora is not None:
        upd["constructora"] = body.constructora.strip()
    if body.contract_number is not None:
        upd["contract_number"] = body.contract_number.strip()
    if body.objeto_contrato is not None:
        upd["objeto_contrato"] = body.objeto_contrato.strip() or None
    if body.cliente_principal is not None:
        upd["cliente_principal"] = body.cliente_principal.strip() or None
    if body.color_tema is not None:
        upd["color_tema"] = validar_color_hex(body.color_tema, "Color del título de portada") or "#003366"
    if body.color_institucional is not None:
        upd["color_institucional"] = validar_color_hex(body.color_institucional, "Color institucional") or "#003366"
    if body.report_text_color is not None:
        upd["report_text_color"] = validar_color_hex(body.report_text_color, "Color del texto de reportes") or "#0F172A"
    if body.start_date is not None:
        upd["start_date"] = body.start_date
    if body.end_date is not None:
        upd["end_date"] = body.end_date
    if body.description is not None:
        upd["description"] = body.description.strip() or None
    if body.reference_files is not None:
        upd["reference_files"] = _sanitize_reference_files(body.reference_files)
    if body.contratistas_list is not None:
        upd["contratistas_list"] = _sanitize_str_list(body.contratistas_list)
    if body.contratos_list is not None:
        upd["contratos_list"] = _sanitize_str_list(body.contratos_list)
    if body.categorias_personal is not None:
        upd["categorias_personal"] = _sanitize_str_list(body.categorias_personal)
    if body.categorias_equipo is not None:
        upd["categorias_equipo"] = _sanitize_str_list(body.categorias_equipo)
    if body.constructora_logo is not None:
        # Aceptamos cadena vacía para "limpiar" el logo
        upd["constructora_logo"] = body.constructora_logo or None
    if body.minuta_code_prefix is not None:
        upd["minuta_code_prefix"] = body.minuta_code_prefix.strip() or None

    # modo_avance y tipo_contrato: ejes independientes, cada uno con su
    # propia bandera de confirmación — cambiarlos con datos ya capturados
    # reinterpreta cómo se lee ese dato, así que NUNCA se convierte en
    # silencio (ver diagnóstico de Etapa 1).
    if body.modo_avance is not None and body.modo_avance != existing.get("modo_avance", "CANTIDAD"):
        tiene_avances = await db.registros_avance.find_one({"project_id": pid})
        if tiene_avances and not body.confirmar_cambio_modo_avance:
            raise HTTPException(
                400,
                "Este proyecto ya tiene registros de avance capturados. Cambiar "
                "modo_avance reinterpreta cómo se calcula el % de avance de cada "
                "concepto y partida — reenvía la solicitud con "
                "confirmar_cambio_modo_avance=true para confirmar el cambio.",
            )
        upd["modo_avance"] = body.modo_avance
    if body.tipo_contrato is not None and body.tipo_contrato != existing.get("tipo_contrato", "PRECIOS_UNITARIOS"):
        tiene_conceptos = await db.conceptos.find_one({"project_id": pid})
        if tiene_conceptos and not body.confirmar_cambio_tipo_contrato:
            raise HTTPException(
                400,
                "Este proyecto ya tiene conceptos capturados en su catálogo. "
                "Cambiar tipo_contrato reinterpreta cómo se leen cantidad y "
                "precio unitario — reenvía la solicitud con "
                "confirmar_cambio_tipo_contrato=true para confirmar el cambio.",
            )
        upd["tipo_contrato"] = body.tipo_contrato
    if body.nombres_niveles_partida is not None:
        upd["nombres_niveles_partida"] = _sanitize_str_list(body.nombres_niveles_partida)
    if body.nombre_nivel_concepto is not None:
        upd["nombre_nivel_concepto"] = body.nombre_nivel_concepto.strip()
    if body.unidades_personalizadas is not None:
        upd["unidades_personalizadas"] = _sanitize_str_list(body.unidades_personalizadas)
    if body.etapas_poste is not None:
        upd["etapas_poste"] = [e.model_dump() for e in body.etapas_poste]
    if body.titulo_modulo_catalogo is not None:
        upd["titulo_modulo_catalogo"] = body.titulo_modulo_catalogo.strip()
    if body.cadencia_reporte is not None:
        upd["cadencia_reporte"] = body.cadencia_reporte
    if body.dia_inicio_semana is not None:
        upd["dia_inicio_semana"] = body.dia_inicio_semana
    if body.zona_horaria is not None:
        upd["zona_horaria"] = _zona_o_400(body.zona_horaria)
    if body.separador_decimal is not None:
        upd["separador_decimal"] = body.separador_decimal

    if upd:
        await db.projects.update_one({"id": pid}, {"$set": upd})

    p = await db.projects.find_one({"id": pid})
    return _project_public(p)


def _project_public(p: dict) -> dict:
    """Serializa un doc de proyecto para exponer al frontend con defaults."""
    if not p:
        return p
    p = dict(p)  # copia superficial para no mutar el original
    p.pop("_id", None)
    p.setdefault("reference_files", [])
    p.setdefault("contratistas_list", [])
    p.setdefault("contratos_list", [])
    p.setdefault("categorias_personal", [])
    p.setdefault("categorias_equipo", [])
    p.setdefault("objeto_contrato", None)
    p.setdefault("cliente_principal", None)
    p.setdefault("color_tema", "#003366")
    p.setdefault("color_institucional", "#003366")
    p.setdefault("report_text_color", "#0F172A")
    p.setdefault("general_data_images", [])
    p.setdefault("template_pdf", None)
    p.setdefault("template_docx", None)
    p.setdefault("template_pptx", None)
    p.setdefault("template_map", None)
    p.setdefault("minuta_code_prefix", None)
    p.setdefault("tipo_contrato", "PRECIOS_UNITARIOS")
    p.setdefault("modo_avance", "CANTIDAD")
    p.setdefault("nombres_niveles_partida", [])
    p.setdefault("nombre_nivel_concepto", "")
    p.setdefault("unidades_personalizadas", [])
    p.setdefault("etapas_poste", _ETAPAS_POSTE_DEFAULT)
    p.setdefault("titulo_modulo_catalogo", "")
    p.setdefault("cadencia_reporte", "MENSUAL")
    p.setdefault("dia_inicio_semana", "LUNES")
    p["zona_horaria"] = p.get("zona_horaria") or ZONA_POR_DEFECTO
    p.setdefault("separador_decimal", ".")
    p["hoy"] = hoy_proyecto(p).isoformat()
    p["tz_offset_min"] = offset_min_proyecto(p)
    p["modulos"] = _sanitize_modulos(p.get("modulos"))
    return p


@api.put("/projects/{pid}/catalogos")
async def set_project_catalogos(
    pid: str,
    body: dict,
    user: dict = Depends(require_role(ROLE_COORD)),
):
    """Actualiza catálogos dinámicos del proyecto:
    contratistas_list, contratos_list, categorias_personal y categorias_equipo.
    Sólo Coordinador General puede modificarlos."""
    upd: dict = {}
    if isinstance(body.get("contratistas_list"), list):
        upd["contratistas_list"] = _sanitize_str_list(body.get("contratistas_list"))
    if isinstance(body.get("contratos_list"), list):
        upd["contratos_list"] = _sanitize_str_list(body.get("contratos_list"))
    if isinstance(body.get("categorias_personal"), list):
        upd["categorias_personal"] = _sanitize_str_list(body.get("categorias_personal"))
    if isinstance(body.get("categorias_equipo"), list):
        upd["categorias_equipo"] = _sanitize_str_list(body.get("categorias_equipo"))
    if not upd:
        raise HTTPException(400, "Nada para actualizar")
    r = await db.projects.update_one({"id": pid}, {"$set": upd})
    if r.matched_count == 0:
        raise HTTPException(404, "Proyecto no existe")
    p = await db.projects.find_one({"id": pid})
    return _project_public(p)


@api.put("/projects/{pid}/modulos")
async def set_project_modulos(
    pid: str,
    body: dict,
    user: dict = Depends(require_role(ROLE_COORD)),
):
    """Enciende/apaga módulos (plantillas) del proyecto, por categoría de
    informe — Diario/Semanal/Mensual (ver MODULOS_CATALOG). Un mismo módulo
    puede estar encendido en varias categorías a la vez. Sólo Coordinador
    General.

    Actualización PARCIAL por diseño: sólo se tocan las claves de módulo que
    vienen explícitamente en el body — las demás conservan su valor actual.
    Togglear "forestal_arbolado" nunca debe apagar de rebote
    "seguridad_higiene" sólo porque el cliente no lo mandó en el payload.
    """
    existing = await db.projects.find_one({"id": pid})
    if not existing:
        raise HTTPException(404, "Proyecto no existe")
    merged = _sanitize_modulos(existing.get("modulos"))
    for categoria, claves_validas in MODULOS_CATALOG.items():
        incoming = body.get(categoria) if isinstance(body, dict) else None
        if not isinstance(incoming, dict):
            continue
        for clave, valor in incoming.items():
            if clave in claves_validas and isinstance(valor, bool):
                merged[categoria][clave] = valor
    await db.projects.update_one({"id": pid}, {"$set": {"modulos": merged}})
    p = await db.projects.find_one({"id": pid})
    return _project_public(p)


@api.delete("/projects/{pid}")
async def archive_project(pid: str, user: dict = Depends(require_role(ROLE_COORD))):
    await db.projects.update_one({"id": pid}, {"$set": {"archived": True}})
    return {"ok": True, "archived": True}


