# === LOCATION NODES (Árbol Recursivo) =======================================
def _acceso_predio_efectivo(node: dict) -> bool:
    """Si nadie decidió explícitamente `acceso_predio_habilitado` para este
    nodo, el default histórico era "solo Subtramo" (depth==1) — antes
    estaba hardcodeado así en el frontend (AccesoPredioManager filtraba
    `depth === 1` a secas); ahora el Coordinador/Sub-Coordinador puede
    habilitarlo/deshabilitarlo nodo por nodo, a cualquier profundidad."""
    habilitado = node.get("acceso_predio_habilitado")
    return habilitado if habilitado is not None else (node.get("depth") == 1)


def _resolve_acceso_predio_node(subtramo_id: str, subtramo_node: dict, nodes_by_subtramo: dict) -> Optional[dict]:
    """Resuelve qué nodo representa el estatus de Acceso al Predio /
    Situación Social a IMPRIMIR para este Subtramo, respetando el toggle
    `acceso_predio_habilitado` (a cualquier profundidad, ver hub
    `AccesoPredioManager`). Antes el PDF/PPTX leían SIEMPRE el nodo Subtramo
    directo sin chequear si estaba habilitado — imprimían "Sin especificar"
    en TODOS los subtramos aunque en el hub solo estuvieran referenciadas/
    habilitadas unas partes del proyecto (logica rota).
    Prioridad: el propio Subtramo si está habilitado; si no, el primer nodo
    descendiente habilitado (p.ej. un Poste específico); si ninguno, None —
    la sección se omite por completo en la página impresa."""
    if _acceso_predio_efectivo(subtramo_node):
        return subtramo_node
    for n in nodes_by_subtramo.get(subtramo_id) or []:
        if n.get("id") == subtramo_id:
            continue
        if _acceso_predio_efectivo(n):
            return n
    return None


@api.get("/projects/{pid}/nodes")
async def list_nodes(pid: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    items = await db.location_nodes.find({"project_id": pid}).sort([("depth", 1), ("order", 1)]).to_list(length=10000)

    # --- FIX AMNESIA DE ESTADO: usar MAX(ultima_lectura) numérica, no SUM(avance) texto ---
    pipeline = [
        {"$match": {"project_id": pid, "ultima_lectura": {"$ne": None}}},
        {"$group": {"_id": "$node_id", "total_avance": {"$max": "$ultima_lectura"}}},
    ]
    aggr = await db.reports.aggregate(pipeline).to_list(length=10000)
    avances_dict = {doc["_id"]: float(doc.get("total_avance") or 0.0) for doc in aggr}
    # -------------------------------------------------------------------------------------

    # Filtrado por scope (Sub-coordinador AHORA tiene scope GLOBAL, igual que Coordinador).
    role = user.get("role")
    if role == ROLE_ESPECIALISTA and (user.get("scope_node_ids") or []):
        allowed_leaves = set(user.get("scope_node_ids") or [])
        # incluir ancestros para que el árbol sea navegable
        ancestors: set = set()
        # construir mapa id->parent
        all_nodes = await db.location_nodes.find({"project_id": pid}).to_list(length=10000)
        parent_of = {n["id"]: n.get("parent_id") for n in all_nodes}
        for leaf in allowed_leaves:
            cur = leaf
            while cur:
                ancestors.add(cur)
                cur = parent_of.get(cur)
        items = [it for it in items if it["id"] in ancestors]
        
    for it in items:
        it.pop("_id", None)
        # Inyectamos el acumulado al nodo
        it["avance_actual"] = avances_dict.get(it["id"], 0.0)
        it["acceso_predio_efectivo"] = _acceso_predio_efectivo(it)

    return items


@api.get("/projects/{pid}/nodes/tree")
async def get_tree(pid: str, user: dict = Depends(current_user)):
    """Devuelve el árbol completo como estructura jerárquica."""
    await ensure_project_access(user, pid)
    items = await db.location_nodes.find({"project_id": pid}).sort([("depth", 1), ("order", 1)]).to_list(length=10000)
    
    # --- FIX AMNESIA DE ESTADO: usar MAX(ultima_lectura) numérica, no SUM(avance) texto ---
    pipeline = [
        {"$match": {"project_id": pid, "ultima_lectura": {"$ne": None}}},
        {"$group": {"_id": "$node_id", "total_avance": {"$max": "$ultima_lectura"}}},
    ]
    aggr = await db.reports.aggregate(pipeline).to_list(length=10000)
    avances_dict = {doc["_id"]: float(doc.get("total_avance") or 0.0) for doc in aggr}
    # -------------------------------------------------------------------------------------

    # Filtrado por scope (Sub-coordinador AHORA tiene scope GLOBAL, igual que Coordinador).
    role = user.get("role")
    if role == ROLE_ESPECIALISTA and (user.get("scope_node_ids") or []):
        allowed_leaves = set(user.get("scope_node_ids") or [])
        ancestors: set = set()
        parent_of = {n["id"]: n.get("parent_id") for n in items}
        for leaf in allowed_leaves:
            cur = leaf
            while cur:
                ancestors.add(cur)
                cur = parent_of.get(cur)
        items = [it for it in items if it["id"] in ancestors]
        
    by_id = {}
    for it in items:
        it.pop("_id", None)
        # Inyectamos el acumulado al nodo antes de anidarlo
        it["avance_actual"] = avances_dict.get(it["id"], 0.0)
        it["children"] = []
        by_id[it["id"]] = it
        
    roots = []
    # Para sub-coord/especialista, "root" debe ser el primer nodo cuyo padre no está en el set filtrado
    for it in items:
        if it.get("parent_id") and it["parent_id"] in by_id:
            by_id[it["parent_id"]]["children"].append(it)
        else:
            roots.append(it)
    return roots


def validar_gps_nodo(lat: Optional[float], lon: Optional[float]) -> Tuple[Optional[float], Optional[float]]:
    """Valida la ubicación GPS de un nodo: ambos o ninguno, dentro de rango y finitos.
    Devuelve (lat, lon) o lanza ValueError con un mensaje legible en es-MX."""
    if lat is None and lon is None:
        return None, None
    if lat is None or lon is None:
        raise ValueError("La ubicación GPS necesita latitud y longitud juntas.")
    if not (math.isfinite(lat) and math.isfinite(lon)):
        raise ValueError("La ubicación GPS no es válida.")
    if not -90 <= lat <= 90:
        raise ValueError("La latitud debe estar entre -90 y 90 grados.")
    if not -180 <= lon <= 180:
        raise ValueError("La longitud debe estar entre -180 y 180 grados.")
    return float(lat), float(lon)


@api.post("/projects/{pid}/nodes")
async def create_node(pid: str, body: LocationNodeIn, user: dict = Depends(require_role(ROLE_COORD))):
    if body.project_id != pid:
        raise HTTPException(400, "project_id mismatch")
    try:
        gps_lat, gps_lon = validar_gps_nodo(body.gps_lat, body.gps_lon)
    except ValueError as e:
        raise HTTPException(400, str(e))
    await ensure_project_access(user, pid)
    parent = None
    depth = 0
    if body.parent_id:
        parent = await db.location_nodes.find_one({"id": body.parent_id, "project_id": pid})
        if not parent:
            raise HTTPException(404, "Nodo padre no existe")
        depth = parent["depth"] + 1
        # Si el padre era hoja, deja de serlo automáticamente.
        if parent.get("is_leaf"):
            await db.location_nodes.update_one(
                {"id": parent["id"]},
                {"$set": {"is_leaf": False, "measurement_type": None, "target_lat": None, "target_lon": None, "target_elev": None}},
            )
    if body.is_leaf and body.measurement_type not in MEASUREMENT_TYPES:
        raise HTTPException(400, "Nodos hoja requieren measurement_type válido")
    nid = str(uuid.uuid4())
    # Coordenadas objetivo: sólo aplican a hojas coord_latlon.
    is_coord_leaf = body.is_leaf and body.measurement_type == "coord_latlon"
    doc = {
        "id": nid,
        "project_id": pid,
        "parent_id": body.parent_id,
        "name": body.name.strip(),
        "depth": depth,
        "order": body.order,
        "is_leaf": body.is_leaf,
        "measurement_type": body.measurement_type if body.is_leaf else None,
        "target_lat": body.target_lat if is_coord_leaf else None,
        "target_lon": body.target_lon if is_coord_leaf else None,
        "target_elev": body.target_elev if is_coord_leaf else None,
        "gps_lat": gps_lat,
        "gps_lon": gps_lon,
        "acceso_predio": body.acceso_predio,
        "situacion_social": body.situacion_social,
        "tipo_nodo": body.tipo_nodo,
        "ubicacion": body.ubicacion,
        "estatus_pilas": body.estatus_pilas,
        "estatus_cabezal": body.estatus_cabezal,
        "estatus_fuste": body.estatus_fuste,
        "estatus_poste": body.estatus_poste,
        "created_at": datetime.now(timezone.utc),
    }
    await db.location_nodes.insert_one(doc)
    doc.pop("_id", None)
    return doc


class NodePatch(BaseModel):
    name: Optional[str] = None
    order: Optional[int] = None
    is_leaf: Optional[bool] = None
    measurement_type: Optional[Literal["coord_latlon", "cadenamiento", "eje", "nivel"]] = None
    target_lat: Optional[float] = None
    target_lon: Optional[float] = None
    target_elev: Optional[float] = None
    # Ubicación GPS real (ver LocationNodeIn). `quitar_gps=True` la borra (None = no tocar).
    gps_lat: Optional[float] = None
    gps_lon: Optional[float] = None
    quitar_gps: Optional[bool] = None
    acceso_predio: Optional[str] = None
    situacion_social: Optional[str] = None
    # None = no tocar (deja el default: antes fijo a "solo Subtramo,
    # depth==1"); True/False = decisión explícita de si ESTE nodo (a
    # cualquier profundidad) participa en Acceso al Predio.
    acceso_predio_habilitado: Optional[bool] = None
    # Ver mismos campos en LocationNodeIn — formato del resumen impreso
    # (Estación vs Intertramo) y datos de la tabla Actividad en Postes.
    tipo_nodo: Optional[Literal["estacion", "intertramo"]] = None
    ubicacion: Optional[str] = None
    estatus_pilas: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_cabezal: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_fuste: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_poste: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None


@api.patch("/nodes/{nid}")
async def update_node(nid: str, body: NodePatch, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB))):
    node = await db.location_nodes.find_one({"id": nid})
    if not node:
        raise HTTPException(404, "Nodo no existe")
    upd: dict = {}
    if body.name is not None:
        upd["name"] = body.name.strip()
    if body.order is not None:
        upd["order"] = body.order
    if body.is_leaf is not None:
        if body.is_leaf:
            # Para convertirse en hoja no debe tener hijos
            has_children = await db.location_nodes.find_one({"parent_id": nid})
            if has_children:
                raise HTTPException(400, "No se puede marcar como hoja: tiene hijos")
            if body.measurement_type not in MEASUREMENT_TYPES:
                raise HTTPException(400, "Hoja requiere measurement_type")
            upd["is_leaf"] = True
            upd["measurement_type"] = body.measurement_type
        else:
            upd["is_leaf"] = False
            upd["measurement_type"] = None
            upd["target_lat"] = None
            upd["target_lon"] = None
            upd["target_elev"] = None
    elif body.measurement_type is not None:
        if not node.get("is_leaf"):
            raise HTTPException(400, "measurement_type solo aplica a hojas")
        if body.measurement_type not in MEASUREMENT_TYPES:
            raise HTTPException(400, "measurement_type inválido")
        upd["measurement_type"] = body.measurement_type
        # Si cambia el tipo y deja de ser coord_latlon, limpia coords objetivo.
        if body.measurement_type != "coord_latlon":
            upd["target_lat"] = None
            upd["target_lon"] = None
            upd["target_elev"] = None
    # Coordenadas objetivo (sólo válidas en hojas coord_latlon — usar valor final).
    final_is_leaf = upd.get("is_leaf", node.get("is_leaf"))
    final_mtype = upd.get("measurement_type", node.get("measurement_type"))
    is_coord_leaf = bool(final_is_leaf and final_mtype == "coord_latlon")
    for fld, val in (("target_lat", body.target_lat), ("target_lon", body.target_lon), ("target_elev", body.target_elev)):
        if val is not None and is_coord_leaf:
            upd[fld] = val
    # Ubicación GPS: aplica a cualquier nodo y es independiente de target_*.
    if body.quitar_gps:
        upd["gps_lat"] = None
        upd["gps_lon"] = None
    elif body.gps_lat is not None or body.gps_lon is not None:
        try:
            upd["gps_lat"], upd["gps_lon"] = validar_gps_nodo(body.gps_lat, body.gps_lon)
        except ValueError as e:
            raise HTTPException(400, str(e))
    if body.acceso_predio is not None:
        upd["acceso_predio"] = body.acceso_predio.strip()
    if body.situacion_social is not None:
        upd["situacion_social"] = body.situacion_social.strip()
    if body.acceso_predio_habilitado is not None:
        upd["acceso_predio_habilitado"] = body.acceso_predio_habilitado
    if body.tipo_nodo is not None:
        upd["tipo_nodo"] = body.tipo_nodo
    if body.ubicacion is not None:
        upd["ubicacion"] = body.ubicacion.strip()
    if body.estatus_pilas is not None:
        upd["estatus_pilas"] = body.estatus_pilas
    if body.estatus_cabezal is not None:
        upd["estatus_cabezal"] = body.estatus_cabezal
    if body.estatus_fuste is not None:
        upd["estatus_fuste"] = body.estatus_fuste
    if body.estatus_poste is not None:
        upd["estatus_poste"] = body.estatus_poste
    if upd:
        await db.location_nodes.update_one({"id": nid}, {"$set": upd})
    out = await db.location_nodes.find_one({"id": nid})
    out.pop("_id", None)
    return out


# --- Estatus de Poste (Pilas/Cabezal/Fuste/Poste) — captura de campo ------
# `PATCH /nodes/{nid}` (arriba) exige Coordinador/Sub-Coordinador porque
# toca TODO el nodo (nombre, tipo, estructura). El módulo "Control de Obra"
# necesita que Especialista (presente en campo) también pueda ciclar el
# estatus de un poste sin poder tocar nada más del nodo — por eso este
# endpoint aparte, acotado a SOLO estos 4 campos, gateado por el módulo
# (mismo criterio que `upsert_weather_log`/`upsert_resource_log`).
class PosteEstatusPatch(BaseModel):
    estatus_pilas: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_cabezal: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_fuste: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None
    estatus_poste: Optional[Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]] = None


@api.patch("/nodes/{nid}/poste-estatus")
async def update_poste_estatus(nid: str, body: PosteEstatusPatch, user: dict = Depends(current_user)):
    _assert_write_allowed(user)
    node = await db.location_nodes.find_one({"id": nid})
    if not node:
        raise HTTPException(404, "Nodo no existe")
    project = await ensure_project_access(user, node["project_id"])
    _ensure_modulo_activo(project, "control_obra")
    upd: dict = {}
    for campo in ("estatus_pilas", "estatus_cabezal", "estatus_fuste", "estatus_poste"):
        val = getattr(body, campo)
        if val is not None:
            upd[campo] = val
    if upd:
        await db.location_nodes.update_one({"id": nid}, {"$set": upd})
    out = await db.location_nodes.find_one({"id": nid})
    out.pop("_id", None)
    return out


# --- Estatus por actividad de Poste (plantilla configurable, ver
# EtapaPosteElemento) — endpoint aparte de update_poste_estatus (arriba):
# ese sigue existiendo tal cual para Acceso al Predio y el resumen impreso,
# este es el detalle fino que consume el tab "Postes" de Control de Obra.
class PosteActividadEstatusPatch(BaseModel):
    actividad_key: str  # "Elemento::Actividad", debe existir en project.etapas_poste
    estatus: Literal["sin_iniciar", "en_proceso", "concluido", "cambio_trayectoria"]


@api.patch("/nodes/{nid}/poste-actividad-estatus")
async def update_poste_actividad_estatus(nid: str, body: PosteActividadEstatusPatch, user: dict = Depends(current_user)):
    _assert_write_allowed(user)
    node = await db.location_nodes.find_one({"id": nid})
    if not node:
        raise HTTPException(404, "Nodo no existe")
    project = await ensure_project_access(user, node["project_id"])
    _ensure_modulo_activo(project, "control_obra")

    etapas = project.get("etapas_poste") or _ETAPAS_POSTE_DEFAULT
    claves_validas = {f"{el['nombre']}::{act}" for el in etapas for act in el.get("actividades", [])}
    if body.actividad_key not in claves_validas:
        raise HTTPException(400, f"'{body.actividad_key}' no es una actividad configurada en la plantilla de este proyecto")

    # Dot-notation de Mongo para tocar SOLO esta clave del dict — nunca lee-
    # modifica-escribe el mapa completo, así que dos posteos concurrentes a
    # actividades distintas del mismo poste nunca se pisan entre sí.
    await db.location_nodes.update_one(
        {"id": nid},
        {"$set": {f"estatus_actividades.{body.actividad_key}": body.estatus}},
    )
    out = await db.location_nodes.find_one({"id": nid})
    out.pop("_id", None)
    return out


@api.delete("/nodes/{nid}")
async def delete_node(nid: str, user: dict = Depends(require_role(ROLE_COORD))):
    node = await db.location_nodes.find_one({"id": nid})
    if not node:
        raise HTTPException(404, "Nodo no existe")
    ids_to_delete = await descendants_ids(nid)
    await db.location_nodes.delete_many({"id": {"$in": ids_to_delete}})
    # NO borramos reportes huérfanos automáticamente (preservación). Marcar como huérfanos:
    await db.reports.update_many(
        {"node_id": {"$in": ids_to_delete}}, {"$set": {"node_orphan": True}}
    )
    return {"ok": True, "deleted_count": len(ids_to_delete)}


# === PORTADILLA POR NODO (cover_image) =====================================
# Se almacena como data URL base64 en el propio documento del nodo.
# Usado por el motor PDF para renderizar la "Portadilla de Nodo" dinámica:
#   fondo con color institucional + nombre del nodo (grande) + imagen incrustada.
_NODE_COVER_MIME = {"image/jpeg", "image/jpg", "image/png", "image/webp"}
_NODE_COVER_MAX_BYTES = 8 * 1024 * 1024  # 8 MB por portada


@api.post("/projects/{pid}/nodes/{nid}/cover")
async def upload_node_cover(
    pid: str,
    nid: str,
    file: UploadFile = File(...),
    user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB)),
):
    """Sube (o reemplaza) la portada institucional de un nodo.
    Acepta JPG/PNG/WebP hasta 8 MB. Devuelve el nodo actualizado."""
    node = await db.location_nodes.find_one({"id": nid, "project_id": pid})
    if not node:
        raise HTTPException(404, "Nodo no existe")
    content_type = (file.content_type or "").lower()
    if content_type and content_type not in _NODE_COVER_MIME:
        raise HTTPException(415, f"Formato no soportado: {content_type}. Usa JPG/PNG/WebP.")
    raw = await file.read(_NODE_COVER_MAX_BYTES + 1)
    if len(raw) > _NODE_COVER_MAX_BYTES:
        raise HTTPException(413, f"Imagen demasiado grande (máx {_NODE_COVER_MAX_BYTES // (1024*1024)} MB).")
    # Serializar como data URL base64
    import base64 as _b64
    mime = content_type or "image/jpeg"
    b64_str = _b64.b64encode(raw).decode("ascii")
    data_url = f"data:{mime};base64,{b64_str}"
    await db.location_nodes.update_one({"id": nid}, {"$set": {"cover_image": data_url}})
    updated = await db.location_nodes.find_one({"id": nid})
    updated.pop("_id", None)
    return updated


@api.delete("/projects/{pid}/nodes/{nid}/cover")
async def delete_node_cover(
    pid: str,
    nid: str,
    user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB)),
):
    """Elimina la portada institucional del nodo (vuelve a la portadilla genérica)."""
    node = await db.location_nodes.find_one({"id": nid, "project_id": pid})
    if not node:
        raise HTTPException(404, "Nodo no existe")
    await db.location_nodes.update_one({"id": nid}, {"$set": {"cover_image": None}})
    updated = await db.location_nodes.find_one({"id": nid})
    updated.pop("_id", None)
    return updated


# === PLANO DE AVANCE (marcadores de estado sobre un plano/blueprint) =======
# Cada plano vive como un documento con sus marcadores EMBEBIDOS (sin
# colección aparte ni historial — solo importa el estado vigente). Coordenadas
# de marcador en FRACCIONES 0-1 del ancho/alto de la imagen base, para que el
# overlay escale igual sin importar la resolución de pantalla.
_PLANO_MIME = {"image/jpeg", "image/jpg", "image/png", "image/webp"}
_PLANO_MAX_BYTES = 10 * 1024 * 1024  # 10 MB — planos escaneados a mayor resolución que fotos de campo

_PLANO_MARKER_ESTADO_COLOR = {
    "sin_iniciar": "#DC2626",
    "en_proceso": "#D97706",
    "terminado": "#16A34A",
}
# Campos del PATCH que SOLO Coordinador/Sub-Coordinador pueden tocar —
# reposicionar o renombrar un marcador es "definir estructura", no captura
# de campo. `estatus` es el único que Especialista también puede escribir.
_PLANO_MARKER_CAMPOS_ESTRUCTURA = ("label", "x", "y", "x2", "y2")


class PlanoMarkerIn(BaseModel):
    # "dado": rectángulo de cimentación (dado/zapata) — se valida igual que
    # "punto" (solo x/y, sin x2/y2), solo cambia cómo lo dibuja el overlay
    # (ver PlanoMarkerOverlay.tsx / _bake_plano_snapshot).
    tipo: Literal["punto", "segmento", "dado"]
    label: str
    x: float
    y: float
    x2: Optional[float] = None
    y2: Optional[float] = None
    estatus: Literal["sin_iniciar", "en_proceso", "terminado"] = "sin_iniciar"


class PlanoMarkerPatch(BaseModel):
    label: Optional[str] = None
    x: Optional[float] = None
    y: Optional[float] = None
    x2: Optional[float] = None
    y2: Optional[float] = None
    estatus: Optional[Literal["sin_iniciar", "en_proceso", "terminado"]] = None


class PlanoAvancePatch(BaseModel):
    nombre: Optional[str] = None


@api.post("/projects/{pid}/planos-avance")
async def upload_plano_avance(
    pid: str,
    nombre: str,
    file: UploadFile = File(...),
    user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB)),
):
    """Crea un Plano de Avance nuevo a partir de una imagen (JPG/PNG/WebP,
    máx 10 MB) — mismo patrón base64-data-URL de `upload_node_cover` arriba.
    `nombre` va como QUERY PARAM (no Form field): el helper de subida nativo
    del frontend (`nativeMultipartUpload`, api.ts) arma el multipart solo con
    `file` y no soporta campos de texto adicionales — evita tocar ese helper
    compartido por Node Cover y otras subidas."""
    nombre = nombre.strip()
    if not nombre:
        raise HTTPException(400, "Nombre del plano requerido")
    content_type = (file.content_type or "").lower()
    if content_type and content_type not in _PLANO_MIME:
        raise HTTPException(415, f"Formato no soportado: {content_type}. Usa JPG/PNG/WebP.")
    raw = await file.read(_PLANO_MAX_BYTES + 1)
    if len(raw) > _PLANO_MAX_BYTES:
        raise HTTPException(413, f"Imagen demasiado grande (máx {_PLANO_MAX_BYTES // (1024*1024)} MB).")
    import base64 as _b64
    mime = content_type or "image/jpeg"
    data_url = f"data:{mime};base64,{_b64.b64encode(raw).decode('ascii')}"
    now = datetime.now(timezone.utc)
    doc = {
        "id": str(uuid.uuid4()),
        "project_id": pid,
        "nombre": nombre,
        "imagen": data_url,
        "markers": [],
        "created_by": user["id"],
        "created_by_name": user["name"],
        "created_at": now,
        "updated_at": now,
    }
    await db.planos_avance.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.get("/projects/{pid}/planos-avance")
async def list_planos_avance(pid: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    # Excluye `imagen` (pesada, base64) del listado — la imagen completa
    # solo se sirve en el detalle, mismo criterio que ensure_project_access
    # excluye general_data_images de la carga por default.
    cursor = db.planos_avance.find({"project_id": pid}, {"imagen": 0}).sort("created_at", -1)
    items = await cursor.to_list(length=500)
    for it in items:
        it.pop("_id", None)
    return items


@api.get("/projects/{pid}/planos-avance/{plano_id}")
async def get_plano_avance(pid: str, plano_id: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    doc = await db.planos_avance.find_one({"id": plano_id, "project_id": pid})
    if not doc:
        raise HTTPException(404, "Plano no existe")
    doc.pop("_id", None)
    return doc


@api.patch("/projects/{pid}/planos-avance/{plano_id}")
async def update_plano_avance(
    pid: str, plano_id: str, body: PlanoAvancePatch, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB)),
):
    doc = await db.planos_avance.find_one({"id": plano_id, "project_id": pid})
    if not doc:
        raise HTTPException(404, "Plano no existe")
    upd: dict = {}
    if body.nombre is not None:
        v = body.nombre.strip()
        if not v:
            raise HTTPException(400, "Nombre del plano requerido")
        upd["nombre"] = v
    if upd:
        upd["updated_at"] = datetime.now(timezone.utc)
        await db.planos_avance.update_one({"id": plano_id}, {"$set": upd})
    out = await db.planos_avance.find_one({"id": plano_id})
    out.pop("_id", None)
    return out


@api.delete("/projects/{pid}/planos-avance/{plano_id}")
async def delete_plano_avance(pid: str, plano_id: str, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB))):
    await db.planos_avance.delete_one({"id": plano_id, "project_id": pid})
    return {"ok": True}


@api.post("/projects/{pid}/planos-avance/{plano_id}/markers")
async def create_plano_marker(
    pid: str, plano_id: str, body: PlanoMarkerIn, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB)),
):
    plano = await db.planos_avance.find_one({"id": plano_id, "project_id": pid})
    if not plano:
        raise HTTPException(404, "Plano no existe")
    label = body.label.strip()
    if not label:
        raise HTTPException(400, "Etiqueta del marcador requerida")
    if body.tipo == "segmento" and (body.x2 is None or body.y2 is None):
        raise HTTPException(400, "Marcador de segmento requiere x2/y2")
    now = datetime.now(timezone.utc)
    marker = {
        "id": str(uuid.uuid4()),
        "tipo": body.tipo,
        "label": label,
        "x": body.x, "y": body.y,
        "x2": body.x2, "y2": body.y2,
        "estatus": body.estatus,
        "updated_by": user["id"],
        "updated_by_name": user["name"],
        "updated_at": now,
    }
    await db.planos_avance.update_one({"id": plano_id}, {"$push": {"markers": marker}, "$set": {"updated_at": now}})
    return marker


@api.patch("/projects/{pid}/planos-avance/{plano_id}/markers/{marker_id}")
async def update_plano_marker(
    pid: str, plano_id: str, marker_id: str, body: PlanoMarkerPatch, user: dict = Depends(current_user),
):
    """Único endpoint para todo cambio de marcador — el rol requerido
    depende de QUÉ campos trae el body, no de la ruta: cualquier rol de
    escritura (Coord/Sub/Especialista) puede actualizar `estatus`, pero
    reposicionar/renombrar (label/x/y/x2/y2) es exclusivo de
    Coordinador/Sub-Coordinador — "definir el plano" vs. "reportar avance
    sobre él"."""
    _assert_write_allowed(user)
    await ensure_project_access(user, pid)
    tocando_estructura = any(
        getattr(body, campo) is not None for campo in _PLANO_MARKER_CAMPOS_ESTRUCTURA
    )
    if tocando_estructura and user["role"] not in (ROLE_COORD, ROLE_SUB):
        raise HTTPException(403, "Solo Coordinador/Sub-Coordinador puede reposicionar o renombrar marcadores")
    plano = await db.planos_avance.find_one({"id": plano_id, "project_id": pid})
    if not plano:
        raise HTTPException(404, "Plano no existe")
    markers = plano.get("markers") or []
    idx = next((i for i, m in enumerate(markers) if m["id"] == marker_id), None)
    if idx is None:
        raise HTTPException(404, "Marcador no existe")
    now = datetime.now(timezone.utc)
    marker = dict(markers[idx])
    if body.label is not None:
        v = body.label.strip()
        if not v:
            raise HTTPException(400, "Etiqueta del marcador requerida")
        marker["label"] = v
    for campo in ("x", "y", "x2", "y2"):
        val = getattr(body, campo)
        if val is not None:
            marker[campo] = val
    if body.estatus is not None:
        marker["estatus"] = body.estatus
    marker["updated_by"] = user["id"]
    marker["updated_by_name"] = user["name"]
    marker["updated_at"] = now
    await db.planos_avance.update_one(
        {"id": plano_id, "markers.id": marker_id},
        {"$set": {"markers.$": marker, "updated_at": now}},
    )
    return marker


@api.delete("/projects/{pid}/planos-avance/{plano_id}/markers/{marker_id}")
async def delete_plano_marker(
    pid: str, plano_id: str, marker_id: str, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB)),
):
    await db.planos_avance.update_one(
        {"id": plano_id, "project_id": pid},
        {"$pull": {"markers": {"id": marker_id}}, "$set": {"updated_at": datetime.now(timezone.utc)}},
    )
    return {"ok": True}


def _bake_plano_snapshot(plano: dict) -> bytes:
    """Hornea los marcadores vigentes sobre la imagen base del plano y
    devuelve PNG bytes — usado por el endpoint de snapshot y por la
    exportación PPTX de Presentación. La vista EN VIVO en la app usa un
    overlay SVG (ver PlanoMarkerOverlay.tsx); esto solo produce una imagen
    plana embebible en el reporte. Dibuja también la etiqueta de cada
    marcador (antes no llevaba ninguna) — mismo criterio de fuente con
    fallback que la marca de agua de fotos (ver más arriba en este archivo:
    DejaVuSans-Bold si está instalada, si no la fuente default de PIL)."""
    import base64 as _b64
    from PIL import Image as _PILImage, ImageDraw as _ImageDraw, ImageFont as _ImageFont

    raw = _b64.b64decode(_strip_b64_prefix(plano["imagen"]))
    img = _PILImage.open(io.BytesIO(raw)).convert("RGB")
    w, h = img.size
    draw = _ImageDraw.Draw(img)
    radius = max(8, int(min(w, h) * 0.014))
    line_width = max(4, int(min(w, h) * 0.01))
    try:
        font = _ImageFont.truetype("/usr/share/fonts/truetype/dejavu/DejaVuSans-Bold.ttf", max(12, int(radius * 1.3)))
    except Exception:
        font = _ImageFont.load_default()

    def _draw_label(cx: float, cy: float, text: str) -> None:
        if not text:
            return
        try:
            bbox = draw.textbbox((0, 0), text, font=font)
            tw, th = bbox[2] - bbox[0], bbox[3] - bbox[1]
        except Exception:
            tw, th = len(text) * 6, 12
        pad = 3
        box = [cx - tw / 2 - pad, cy - th / 2 - pad, cx + tw / 2 + pad, cy + th / 2 + pad]
        draw.rectangle(box, fill="#FFFFFF")  # img siempre es RGB (convert arriba) — sin canal alpha
        draw.text((cx - tw / 2, cy - th / 2), text, fill="#1A1A1A", font=font)

    for m in (plano.get("markers") or []):
        color = _PLANO_MARKER_ESTADO_COLOR.get(m.get("estatus"), "#94A3B8")
        tipo = m.get("tipo")
        label = (m.get("label") or "").strip()
        if tipo == "segmento" and m.get("x2") is not None and m.get("y2") is not None:
            x1, y1 = m["x"] * w, m["y"] * h
            x2, y2 = m["x2"] * w, m["y2"] * h
            draw.line([(x1, y1), (x2, y2)], fill=color, width=line_width)
            _draw_label((x1 + x2) / 2, (y1 + y2) / 2 - radius, label)
        elif tipo == "dado":
            cx, cy = m["x"] * w, m["y"] * h
            side = radius * 2.2
            draw.rectangle(
                [cx - side / 2, cy - side / 2, cx + side / 2, cy + side / 2],
                fill=color, outline="#FFFFFF", width=max(2, radius // 6),
            )
            _draw_label(cx, cy + side / 2 + radius * 0.9, label)
        else:
            cx, cy = m["x"] * w, m["y"] * h
            draw.ellipse(
                [cx - radius, cy - radius, cx + radius, cy + radius],
                fill=color, outline="#FFFFFF", width=max(2, radius // 6),
            )
            _draw_label(cx, cy + radius + radius * 0.9, label)
    out = io.BytesIO()
    img.save(out, format="PNG")
    return out.getvalue()


@api.get("/projects/{pid}/planos-avance/{plano_id}/snapshot.png")
async def plano_avance_snapshot(pid: str, plano_id: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    plano = await db.planos_avance.find_one({"id": plano_id, "project_id": pid})
    if not plano:
        raise HTTPException(404, "Plano no existe")
    png_bytes = _bake_plano_snapshot(plano)
    return StreamingResponse(io.BytesIO(png_bytes), media_type="image/png")


# === PRESENTACIÓN (Informe de Actividades semanal) =========================
# Documento con SECCIONES embebidas (mismo criterio que `markers` en
# planos_avance): una Presentación se lee/escribe siempre como un todo al
# armar el preview/export, así que embeber evita N+1 queries. Cada tipo de
# sección guarda solo lo que NO puede calcularse en vivo — croquis_estacion
# y avance_grafico, por ejemplo, solo guardan una referencia (node_id /
# plano_id): la imagen/datos se leen del nodo/plano VIGENTE al momento de
# previsualizar o exportar, nunca se duplican aquí. financiero,
# seguimiento_estudios, mapa_general y portada no guardan nada propio en
# absoluto — se calculan enteramente en vivo desde otras colecciones.
class InformacionParticularFotoIn(BaseModel):
    photo: str  # base64 data URL
    caption: str = ""
    destacado: bool = False
    destacado_label: Optional[str] = None  # texto libre del callout (ej. "Problemática social")


class InformacionParticularBloqueIn(BaseModel):
    titulo: str
    node_id: Optional[str] = None  # si se liga, jala acceso_predio/situacion_social del nodo en vivo
    actividades: List[str] = Field(default_factory=list)  # texto libre, independiente de EVM/actividades
    fotos: List[InformacionParticularFotoIn] = Field(default_factory=list)


class PresentacionSeccionIn(BaseModel):
    tipo: Literal[
        "portada", "mapa_general", "divisor", "financiero",
        "seguimiento_estudios", "croquis_estacion", "informacion_particular",
        "avance_grafico",
    ]
    orden: int = 0
    titulo: Optional[str] = None  # "divisor" (ej. "FINANCIERO"); libre, no atado a Área
    node_id: Optional[str] = None  # "croquis_estacion"
    plano_id: Optional[str] = None  # "avance_grafico"
    bloques: List[InformacionParticularBloqueIn] = Field(default_factory=list)  # "informacion_particular"


class PresentacionSeccionPatch(BaseModel):
    orden: Optional[int] = None
    titulo: Optional[str] = None
    node_id: Optional[str] = None
    plano_id: Optional[str] = None


class PresentacionIn(BaseModel):
    project_id: str
    fecha: str  # ISO date, mostrada en la Portada
    titulo: str = "INFORME DE ACTIVIDADES"
    # Periodo de la sección Financiero: el mismo catálogo que el tablero EVM (A-05).
    periodo_financiero: Literal["mes_actual", "ultimos_3_meses", "proyecto_completo"] = "mes_actual"


class PresentacionPatch(BaseModel):
    fecha: Optional[str] = None
    titulo: Optional[str] = None
    periodo_financiero: Optional[Literal["mes_actual", "ultimos_3_meses", "proyecto_completo"]] = None


@api.post("/projects/{pid}/presentaciones")
async def create_presentacion(pid: str, body: PresentacionIn, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB))):
    try:
        date.fromisoformat(body.fecha)
    except ValueError:
        raise HTTPException(400, "fecha debe ser YYYY-MM-DD")
    titulo = (body.titulo or "INFORME DE ACTIVIDADES").strip() or "INFORME DE ACTIVIDADES"
    now = datetime.now(timezone.utc)
    doc = {
        "id": str(uuid.uuid4()),
        "project_id": pid,
        "fecha": body.fecha,
        "titulo": titulo,
        "periodo_financiero": body.periodo_financiero,
        "secciones": [],
        "created_by": user["id"],
        "created_by_name": user["name"],
        "created_at": now,
        "updated_at": now,
    }
    await db.presentaciones.insert_one(doc)
    doc.pop("_id", None)
    return doc


@api.get("/projects/{pid}/presentaciones")
async def list_presentaciones(pid: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    # Excluye `secciones` del listado (puede incluir fotos base64 pesadas) —
    # el detalle completo solo se sirve en GET .../presentaciones/{id}.
    cursor = db.presentaciones.find({"project_id": pid}, {"secciones": 0}).sort("fecha", -1)
    items = await cursor.to_list(length=500)
    for it in items:
        it.pop("_id", None)
    return items


@api.get("/projects/{pid}/presentaciones/{pres_id}")
async def get_presentacion(pid: str, pres_id: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    doc = await db.presentaciones.find_one({"id": pres_id, "project_id": pid})
    if not doc:
        raise HTTPException(404, "Presentación no existe")
    doc.pop("_id", None)
    return doc


@api.patch("/projects/{pid}/presentaciones/{pres_id}")
async def update_presentacion(
    pid: str, pres_id: str, body: PresentacionPatch, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB)),
):
    doc = await db.presentaciones.find_one({"id": pres_id, "project_id": pid})
    if not doc:
        raise HTTPException(404, "Presentación no existe")
    upd: dict = {}
    if body.fecha is not None:
        try:
            date.fromisoformat(body.fecha)
        except ValueError:
            raise HTTPException(400, "fecha debe ser YYYY-MM-DD")
        upd["fecha"] = body.fecha
    if body.titulo is not None:
        v = body.titulo.strip()
        if not v:
            raise HTTPException(400, "Título requerido")
        upd["titulo"] = v
    if body.periodo_financiero is not None:
        upd["periodo_financiero"] = body.periodo_financiero
    if upd:
        upd["updated_at"] = datetime.now(timezone.utc)
        await db.presentaciones.update_one({"id": pres_id}, {"$set": upd})
    out = await db.presentaciones.find_one({"id": pres_id})
    out.pop("_id", None)
    return out


@api.delete("/projects/{pid}/presentaciones/{pres_id}")
async def delete_presentacion(pid: str, pres_id: str, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB))):
    await db.presentaciones.delete_one({"id": pres_id, "project_id": pid})
    return {"ok": True}


async def _validate_presentacion_seccion_refs(pid: str, body) -> None:
    """Valida que node_id/plano_id referenciados existan en este proyecto —
    son los mismos ids que se resuelven EN VIVO al armar preview/export, así
    que una referencia rota fallaría silenciosamente ahí si no se valida aquí."""
    node_id = getattr(body, "node_id", None)
    if node_id:
        node = await db.location_nodes.find_one({"id": node_id, "project_id": pid})
        if not node:
            raise HTTPException(404, "node_id no existe en este proyecto")
    plano_id = getattr(body, "plano_id", None)
    if plano_id:
        plano = await db.planos_avance.find_one({"id": plano_id, "project_id": pid})
        if not plano:
            raise HTTPException(404, "plano_id no existe en este proyecto")


@api.post("/projects/{pid}/presentaciones/{pres_id}/secciones")
async def create_presentacion_seccion(
    pid: str, pres_id: str, body: PresentacionSeccionIn, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB)),
):
    pres = await db.presentaciones.find_one({"id": pres_id, "project_id": pid})
    if not pres:
        raise HTTPException(404, "Presentación no existe")
    await _validate_presentacion_seccion_refs(pid, body)
    if body.tipo == "divisor" and not (body.titulo or "").strip():
        raise HTTPException(400, "Sección 'divisor' requiere titulo")
    if body.tipo == "croquis_estacion" and not body.node_id:
        raise HTTPException(400, "Sección 'croquis_estacion' requiere node_id")
    if body.tipo == "avance_grafico" and not body.plano_id:
        raise HTTPException(400, "Sección 'avance_grafico' requiere plano_id")
    now = datetime.now(timezone.utc)
    seccion = {
        "id": str(uuid.uuid4()),
        "tipo": body.tipo,
        "orden": body.orden,
        "titulo": (body.titulo or "").strip() or None,
        "node_id": body.node_id,
        "plano_id": body.plano_id,
        "bloques": [b.model_dump() for b in body.bloques] if body.tipo == "informacion_particular" else [],
    }
    await db.presentaciones.update_one(
        {"id": pres_id}, {"$push": {"secciones": seccion}, "$set": {"updated_at": now}},
    )
    return seccion


@api.patch("/projects/{pid}/presentaciones/{pres_id}/secciones/{sec_id}")
async def update_presentacion_seccion(
    pid: str, pres_id: str, sec_id: str, body: PresentacionSeccionPatch,
    user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB)),
):
    await _validate_presentacion_seccion_refs(pid, body)
    pres = await db.presentaciones.find_one({"id": pres_id, "project_id": pid})
    if not pres:
        raise HTTPException(404, "Presentación no existe")
    secciones = pres.get("secciones") or []
    idx = next((i for i, s in enumerate(secciones) if s["id"] == sec_id), None)
    if idx is None:
        raise HTTPException(404, "Sección no existe")
    seccion = dict(secciones[idx])
    if body.orden is not None:
        seccion["orden"] = body.orden
    if body.titulo is not None:
        seccion["titulo"] = body.titulo.strip() or None
    if body.node_id is not None:
        seccion["node_id"] = body.node_id
    if body.plano_id is not None:
        seccion["plano_id"] = body.plano_id
    now = datetime.now(timezone.utc)
    await db.presentaciones.update_one(
        {"id": pres_id, "secciones.id": sec_id},
        {"$set": {"secciones.$": seccion, "updated_at": now}},
    )
    return seccion


@api.delete("/projects/{pid}/presentaciones/{pres_id}/secciones/{sec_id}")
async def delete_presentacion_seccion(
    pid: str, pres_id: str, sec_id: str, user: dict = Depends(require_role(ROLE_COORD, ROLE_SUB)),
):
    await db.presentaciones.update_one(
        {"id": pres_id, "project_id": pid},
        {"$pull": {"secciones": {"id": sec_id}}, "$set": {"updated_at": datetime.now(timezone.utc)}},
    )
    return {"ok": True}


class InformacionParticularBloquesPatch(BaseModel):
    bloques: List[InformacionParticularBloqueIn] = Field(default_factory=list)


@api.patch("/projects/{pid}/presentaciones/{pres_id}/secciones/{sec_id}/informacion-particular")
async def update_informacion_particular(
    pid: str, pres_id: str, sec_id: str, body: InformacionParticularBloquesPatch, user: dict = Depends(current_user),
):
    """Reemplaza el arreglo `bloques` COMPLETO — captura de campo (texto de
    actividades y fotos), por eso usa el permiso amplio (`_assert_write_allowed`,
    Coord/Sub/Especialista) en vez de `require_role`, a diferencia de los
    endpoints de estructura del documento arriba (crear/borrar/reordenar
    secciones sí es exclusivo de Coord/Sub)."""
    _assert_write_allowed(user)
    await ensure_project_access(user, pid)
    pres = await db.presentaciones.find_one({"id": pres_id, "project_id": pid})
    if not pres:
        raise HTTPException(404, "Presentación no existe")
    secciones = pres.get("secciones") or []
    idx = next((i for i, s in enumerate(secciones) if s["id"] == sec_id), None)
    if idx is None:
        raise HTTPException(404, "Sección no existe")
    if secciones[idx]["tipo"] != "informacion_particular":
        raise HTTPException(400, "Esta sección no es de tipo informacion_particular")
    for b in body.bloques:
        if b.node_id:
            node = await db.location_nodes.find_one({"id": b.node_id, "project_id": pid})
            if not node:
                raise HTTPException(404, f"node_id '{b.node_id}' no existe en este proyecto")
    seccion = dict(secciones[idx])
    seccion["bloques"] = [b.model_dump() for b in body.bloques]
    now = datetime.now(timezone.utc)
    await db.presentaciones.update_one(
        {"id": pres_id, "secciones.id": sec_id},
        {"$set": {"secciones.$": seccion, "updated_at": now}},
    )
    return seccion


def _force_pptx_theme_font(prs, font_name: str = "Arial") -> None:
    """Fuerza majorFont/minorFont del tema de cada slide master a `font_name`.

    Ningún run del motor PPTX (`export_presentacion_pptx`/`export_reports_pptx`
    y sus closures `add_text`/etc.) fija `run.font.name` explícitamente — son
    decenas de `paragraph.add_run(...)` sin tocar la tipografía. Sin esta
    llamada, ese texto hereda el tema por default de PowerPoint (Calibri) o el
    de la plantilla subida por el Coordinador, mientras que el motor PDF usa
    Helvetica en todo el documento — de ahí que el PPTX se vea con una
    tipografía distinta al PDF pese a ser "el mismo" reporte. Arial es el
    sustituto más cercano a Helvetica realmente instalado en Windows/Office.
    Se llama UNA vez, justo después de resolver `prs` (venga de plantilla o
    en blanco) y antes de dibujar cualquier slide — así cualquier run sin
    `font.name` explícito hereda esto en vez del tema original."""
    try:
        from pptx.opc.constants import RELATIONSHIP_TYPE as _RT
        _A_NS = "http://schemas.openxmlformats.org/drawingml/2006/main"
        for _master in prs.slide_masters:
            _theme_el = _master.part.part_related_by(_RT.THEME)._element
            for _tag in ("majorFont", "minorFont"):
                _font_el = _theme_el.find(f".//{{{_A_NS}}}{_tag}")
                if _font_el is None:
                    continue
                _latin_el = _font_el.find(f"{{{_A_NS}}}latin")
                if _latin_el is not None:
                    _latin_el.set("typeface", font_name)
    except Exception:
        pass  # Nunca debe tronar un export por esto — degradar a tema original.


@api.get("/projects/{pid}/presentaciones/{pres_id}/export.pptx")
async def export_presentacion_pptx(pid: str, pres_id: str, user: dict = Depends(current_user)):
    """Exporta una Presentación como PPTX real, reusando el mismo patrón de
    "todo fondo proviene del membrete subido por el Coordinador" que
    `export_reports_pptx` (ver `_clone_slide`/`_clone_membrete` ahí) — estas
    closures se reimplementan aquí (no se pueden importar: son funciones
    anidadas de ese otro endpoint), pero el PATRÓN es idéntico a propósito.
    Sin plantilla subida, genera slides en blanco sin decoración."""
    await ensure_project_access(user, pid)
    proj = await db.projects.find_one({"id": pid})
    if not proj:
        raise HTTPException(404, "Proyecto no existe")
    pres = await db.presentaciones.find_one({"id": pres_id, "project_id": pid})
    if not pres:
        raise HTTPException(404, "Presentación no existe")

    secciones = sorted(pres.get("secciones") or [], key=lambda s: s.get("orden", 0))

    # --- Resolver datos EN VIVO de cada sección (I/O a Mongo, antes del hilo bloqueante) ---
    node_ids = {s["node_id"] for s in secciones if s.get("node_id")}
    for s in secciones:
        if s.get("tipo") == "informacion_particular":
            for b in (s.get("bloques") or []):
                if b.get("node_id"):
                    node_ids.add(b["node_id"])
    nodes_by_id: dict = {}
    if node_ids:
        async for n in db.location_nodes.find({"id": {"$in": list(node_ids)}, "project_id": pid}):
            nodes_by_id[n["id"]] = n

    plano_ids = {s["plano_id"] for s in secciones if s.get("tipo") == "avance_grafico" and s.get("plano_id")}
    planos_by_id: dict = {}
    if plano_ids:
        async for p in db.planos_avance.find({"id": {"$in": list(plano_ids)}, "project_id": pid}):
            planos_by_id[p["id"]] = p

    analisis: Optional[dict] = None
    presupuesto_total_str: Optional[str] = None
    periodo_financiero_txt: Optional[str] = None
    if any(s.get("tipo") == "financiero" for s in secciones):
        try:
            # Mismo servicio y mismo periodo que el tablero EVM (A-05): así ambos muestran
            # las mismas cifras, con EV contractual y EV total.
            fin = await datos_financieros_presentacion(pid, pres, proj)
            analisis = fin["cifras"]
            presupuesto_total_str = dec_to_str(analisis["bac"])
            periodo_financiero_txt = (
                f"Periodo: {_fmt_dia_corto_es(fin['start'])} al {_fmt_dia_corto_es(fin['end'])}"
            )
        except Exception:
            # No se traga en silencio: queda en el log y la slide dice que no hay datos.
            log.exception("Presentación %s: no se pudo calcular la sección Financiero", pres_id)
            analisis = None

    disciplina_rows: list = []
    if any(s.get("tipo") == "seguimiento_estudios" for s in secciones):
        disciplina_rows = await db.estudio_disciplina_avance.find({"project_id": pid}).to_list(length=1000)

    general_images: List[str] = []
    if any(s.get("tipo") == "mapa_general" for s in secciones):
        gproj = await db.projects.find_one({"id": pid}, {"general_data_images": 1})
        general_images = (gproj or {}).get("general_data_images") or []

    project_color = proj.get("color_institucional") or proj.get("color_tema") or "#1E40AF"

    def _build_presentacion_pptx_blocking() -> bytes:
        import base64 as _b64
        from copy import deepcopy as _deepcopy
        from pptx import Presentation
        from pptx.dml.color import RGBColor as _PRGBColor
        from pptx.enum.shapes import MSO_SHAPE as _MSO_SHAPE
        from pptx.enum.text import PP_ALIGN as _PP_ALIGN
        from pptx.oxml.ns import qn as _qn
        from pptx.util import Cm as _Cm, Pt as _Pt

        tpl_pptx = _get_project_template(proj, "pptx")
        tpl_cover_slide = None
        tpl_master_slide = None
        prs = None
        if tpl_pptx:
            try:
                src = Presentation(tpl_pptx)
                n_tpl = len(src.slides)
                if n_tpl > 0:
                    tpl_cover_slide = src.slides[0]
                    tpl_master_slide = src.slides[1] if n_tpl > 1 else src.slides[0]
                    prs = src
            except Exception:
                prs = None
        if prs is None:
            prs = Presentation()
            prs.slide_width = _Cm(29.7)
            prs.slide_height = _Cm(21.0)
        _force_pptx_theme_font(prs, "Arial")
        SW, SH = prs.slide_width, prs.slide_height
        MARGIN_X = _Cm(1.5)
        TOP_MARGIN = _Cm(2.2)
        BOTTOM_MARGIN = _Cm(1.2)
        content_w = SW - 2 * MARGIN_X
        blank = prs.slide_layouts[6] if len(prs.slide_layouts) > 6 else prs.slide_layouts[-1]
        n_seed_slides = len(prs.slides)  # slides ORIGINALES de la plantilla — se borran al final, ver abajo

        def _clone_slide(source_slide):
            """Clona una slide (portada o membrete) reparando rIds de imagen —
            mismo algoritmo que `_clone_slide` en `export_reports_pptx`
            (server.py), reimplementado aquí porque esa es una closure
            anidada no importable."""
            if source_slide is None:
                return prs.slides.add_slide(blank)
            try:
                _IMG_REL = "http://schemas.openxmlformats.org/officeDocument/2006/relationships/image"
                _EMBED = _qn("r:embed")
                _LINK = _qn("r:link")
                new_slide = prs.slides.add_slide(source_slide.slide_layout)
                for shp in list(new_slide.shapes):
                    try:
                        shp.element.getparent().remove(shp.element)
                    except Exception:
                        pass
                for shp in source_slide.shapes:
                    try:
                        new_el = _deepcopy(shp.element)
                        skip = False
                        for blip in new_el.iter(_qn("a:blip")):
                            for attr in (_EMBED, _LINK):
                                old_rid = blip.get(attr)
                                if not old_rid:
                                    continue
                                try:
                                    image_part = source_slide.part.related_part(old_rid)
                                    new_rid = new_slide.part.relate_to(image_part, _IMG_REL)
                                    blip.set(attr, new_rid)
                                except Exception:
                                    skip = True
                                    break
                            if skip:
                                break
                        if skip:
                            continue
                        new_slide.shapes._spTree.insert_element_before(new_el, "p:extLst")
                    except Exception:
                        continue
                return new_slide
            except Exception:
                return prs.slides.add_slide(blank)

        def _clone_membrete():
            return _clone_slide(tpl_master_slide)

        def _clone_cover_bg():
            return _clone_slide(tpl_cover_slide) if tpl_cover_slide else _clone_membrete()

        def add_text(slide, x, y, w, h, text, *, size=14, bold=False, color=(0x0F, 0x17, 0x2A), align=_PP_ALIGN.LEFT):
            tb = slide.shapes.add_textbox(x, y, w, h)
            tf = tb.text_frame
            tf.word_wrap = True
            p = tf.paragraphs[0]
            p.alignment = align
            run = p.add_run()
            run.text = str(text)
            run.font.size = _Pt(size)
            run.font.bold = bold
            run.font.color.rgb = _PRGBColor(*color)
            return tb

        def _rect(slide, x, y, w, h, fill_rgb=None):
            sh = slide.shapes.add_shape(_MSO_SHAPE.RECTANGLE, x, y, w, h)
            sh.shadow.inherit = False
            if fill_rgb is not None:
                sh.fill.solid()
                sh.fill.fore_color.rgb = _PRGBColor(*fill_rgb)
            else:
                sh.fill.background()
            sh.line.fill.background()
            return sh

        def _hex_to_rgb(hx: str):
            hx = (hx or "1E40AF").lstrip("#")
            return tuple(int(hx[i:i + 2], 16) for i in (0, 2, 4))

        def add_picture_b64(slide, b64_str, x, y, w, h):
            if not b64_str:
                return
            try:
                raw = _b64.b64decode(_strip_b64_prefix(b64_str))
                slide.shapes.add_picture(io.BytesIO(raw), x, y, width=w, height=h)
            except Exception:
                pass

        BRAND_RGB = _hex_to_rgb(_readable_dark_hex(project_color))
        BRAND_RAW_RGB = _hex_to_rgb(project_color)
        TEXT_RGB = (0x0F, 0x17, 0x2A)
        MUTED_RGB = (0x64, 0x74, 0x8B)
        WHITE_RGB = (0xFF, 0xFF, 0xFF)

        def slide_portada():
            slide = _clone_cover_bg()
            add_text(slide, MARGIN_X, SH / 2 - _Cm(1.4), content_w, _Cm(1.6), pres.get("titulo") or "INFORME DE ACTIVIDADES",
                     size=28, bold=True, color=BRAND_RGB, align=_PP_ALIGN.CENTER)
            add_text(slide, MARGIN_X, SH / 2 + _Cm(0.3), content_w, _Cm(0.8), pres.get("fecha") or "",
                     size=14, color=MUTED_RGB, align=_PP_ALIGN.CENTER)

        def slide_divisor(titulo):
            slide = _clone_membrete()
            add_text(slide, MARGIN_X, SH / 2 - _Cm(0.8), content_w, _Cm(1.6), (titulo or "").upper(),
                     size=26, bold=True, color=BRAND_RGB, align=_PP_ALIGN.CENTER)

        def slide_mapa_general():
            slide = _clone_membrete()
            if general_images:
                add_picture_b64(slide, general_images[0], MARGIN_X, TOP_MARGIN, content_w, SH - TOP_MARGIN - BOTTOM_MARGIN)
            else:
                add_text(slide, MARGIN_X, TOP_MARGIN, content_w, _Cm(1), "Sin imagen de mapa general configurada.",
                         size=13, color=MUTED_RGB, align=_PP_ALIGN.CENTER)

        def slide_financiero():
            slide = _clone_membrete()
            y = TOP_MARGIN
            add_text(slide, MARGIN_X, y, content_w, _Cm(0.9), "FINANCIERO", size=20, bold=True, color=BRAND_RGB, align=_PP_ALIGN.CENTER)
            y += _Cm(1.1)
            if not analisis:
                add_text(slide, MARGIN_X, y, content_w, _Cm(1), "Sin datos financieros (EVM) disponibles para este periodo.",
                         size=13, color=MUTED_RGB, align=_PP_ALIGN.CENTER)
                return
            if periodo_financiero_txt:
                add_text(slide, MARGIN_X, y, content_w, _Cm(0.7), periodo_financiero_txt,
                         size=11, color=MUTED_RGB, align=_PP_ALIGN.CENTER)
                y += _Cm(0.9)
            def _m(v):
                return f"${dec_to_str(v)}" if v is not None else "—"

            kpis = [
                ("Presupuesto (BAC)", f"${presupuesto_total_str}" if presupuesto_total_str else "—"),
                ("Valor Planeado (PV)", _m(analisis['pv'])),
                ("Valor Ganado contractual", _m(analisis['ev_contractual'])),
                ("Valor Ganado total (con excedentes)", _m(analisis['ev_total'])),
                ("Costo Real (AC)", _m(analisis['ac'])),
                ("SPI", dec_to_str(analisis['spi']) if analisis['spi'] is not None else "—"),
                ("CPI", dec_to_str(analisis['cpi']) if analisis['cpi'] is not None else "—"),
                ("Variación cronograma", _m(analisis['variacion_cronograma'])),
                ("Variación costo", _m(analisis['variacion_costo'])),
                ("Estimado al terminar (EAC)", _m(analisis['eac'])),
                ("Por gastar (ETC)", _m(analisis['etc'])),
                ("Variación al terminar (VAC)", _m(analisis['vac'])),
            ]
            cols = 4
            card_w = int((content_w - _Cm(0.4) * (cols - 1)) / cols)
            card_h = _Cm(2.6)
            for i, (label, value) in enumerate(kpis):
                col, row = i % cols, i // cols
                x = int(MARGIN_X + col * (card_w + _Cm(0.4)))
                yy = int(y + row * (card_h + _Cm(0.4)))
                _rect(slide, x, yy, card_w, card_h)
                add_text(slide, x + _Cm(0.15), yy + _Cm(0.15), card_w - _Cm(0.3), _Cm(0.7), label,
                         size=9, bold=True, color=MUTED_RGB, align=_PP_ALIGN.CENTER)
                add_text(slide, x + _Cm(0.15), yy + _Cm(0.9), card_w - _Cm(0.3), _Cm(1.2), value,
                         size=14, bold=True, color=TEXT_RGB, align=_PP_ALIGN.CENTER)
            if analisis.get("variacion_costo") is None:
                filas = (len(kpis) + cols - 1) // cols
                add_text(slide, MARGIN_X, int(y + filas * (card_h + _Cm(0.4))), content_w, _Cm(0.7),
                         "Sin gasto real capturado en el periodo: el CPI y la variación de costo no se calculan.",
                         size=10, color=MUTED_RGB, align=_PP_ALIGN.CENTER)

        def slide_seguimiento_estudios():
            slide = _clone_membrete()
            y = TOP_MARGIN
            add_text(slide, MARGIN_X, y, content_w, _Cm(0.9), "SEGUIMIENTO A ESTUDIOS Y ANÁLISIS",
                     size=18, bold=True, color=BRAND_RGB, align=_PP_ALIGN.CENTER)
            y = int(y + _Cm(1.0))
            por_disciplina = {r["disciplina"]: r for r in disciplina_rows if r.get("node_id") is None}
            n_rows = len(ESTUDIO_DISCIPLINA_AVANCE_KEYS)
            row_h = int((SH - BOTTOM_MARGIN - y) / n_rows)
            for i, k in enumerate(ESTUDIO_DISCIPLINA_AVANCE_KEYS):
                pct = (por_disciplina.get(k) or {}).get("porcentaje", 0) or 0
                yy = y + i * row_h
                add_text(slide, MARGIN_X, yy, _Cm(4.5), row_h, ESTUDIO_DISCIPLINA_AVANCE_LABEL[k], size=10, bold=True, color=TEXT_RGB)
                bar_x = int(MARGIN_X + _Cm(4.7))
                bar_w = int(content_w - _Cm(4.7) - _Cm(1.3))
                bar_y = int(yy + row_h * 0.3)
                bar_h = max(1, int(row_h * 0.4))
                _rect(slide, bar_x, bar_y, bar_w, bar_h, fill_rgb=(0xE2, 0xE8, 0xF0))
                fill_w = int(bar_w * (pct / 100.0))
                if fill_w > 0:
                    _rect(slide, bar_x, bar_y, fill_w, bar_h, fill_rgb=BRAND_RAW_RGB)
                add_text(slide, bar_x + bar_w + _Cm(0.1), yy, _Cm(1.2), row_h, f"{pct}%", size=10, bold=True, color=TEXT_RGB, align=_PP_ALIGN.RIGHT)

        def slide_croquis_estacion(node_id):
            slide = _clone_membrete()
            node = nodes_by_id.get(node_id) or {}
            add_picture_b64(slide, node.get("cover_image"), MARGIN_X, TOP_MARGIN, content_w, SH - TOP_MARGIN - BOTTOM_MARGIN)
            _rect(slide, MARGIN_X, SH - BOTTOM_MARGIN - _Cm(1.0), content_w, _Cm(1.0), fill_rgb=(0x0F, 0x17, 0x2A))
            add_text(slide, MARGIN_X + _Cm(0.2), SH - BOTTOM_MARGIN - _Cm(0.9), content_w - _Cm(0.4), _Cm(0.8),
                     node.get("name") or "Estación", size=16, bold=True, color=WHITE_RGB)

        def _foto_grid(slide, fotos, x, y, w, h, cols):
            if not fotos:
                return
            rows = math.ceil(len(fotos) / cols)
            gap = _Cm(0.2)
            cell_w = int((w - gap * (cols - 1)) / cols)
            cell_h = int((h - gap * (rows - 1)) / rows)
            for i, f in enumerate(fotos):
                col, row = i % cols, i // cols
                cx = int(x + col * (cell_w + gap))
                cy = int(y + row * (cell_h + gap))
                add_picture_b64(slide, f.get("photo"), cx, cy, cell_w, cell_h)
                if f.get("destacado"):
                    _rect(slide, cx, cy, cell_w, _Cm(0.5), fill_rgb=(0xFE, 0xF3, 0xC7))
                    add_text(slide, cx + _Cm(0.05), cy, cell_w - _Cm(0.1), _Cm(0.45),
                             f.get("destacado_label") or "Destacado", size=7, bold=True, color=(0x92, 0x40, 0x0E), align=_PP_ALIGN.CENTER)
                cap = f.get("caption") or ""
                if cap:
                    cap_y = int(cy + cell_h - _Cm(0.5))
                    _rect(slide, cx, cap_y, cell_w, _Cm(0.5), fill_rgb=(0x0F, 0x17, 0x2A))
                    add_text(slide, cx + _Cm(0.05), cap_y, cell_w - _Cm(0.1), _Cm(0.45), cap, size=7, color=WHITE_RGB, align=_PP_ALIGN.CENTER)

        def slide_informacion_particular(seccion):
            bloques = seccion.get("bloques") or []
            if not bloques:
                slide = _clone_membrete()
                add_text(slide, MARGIN_X, TOP_MARGIN, content_w, _Cm(1), "Sección sin contenido todavía.",
                         size=13, color=MUTED_RGB, align=_PP_ALIGN.CENTER)
                return
            for bloque in bloques:
                slide = _clone_membrete()
                y = TOP_MARGIN
                add_text(slide, MARGIN_X, y, content_w, _Cm(0.8), bloque.get("titulo") or "", size=18, bold=True, color=BRAND_RGB)
                y = int(y + _Cm(0.9))
                node = nodes_by_id.get(bloque.get("node_id")) if bloque.get("node_id") else None
                left_w = int(content_w * 0.42)
                yy = y
                if node and (node.get("acceso_predio") or node.get("situacion_social")):
                    add_text(slide, MARGIN_X, yy, left_w, _Cm(0.5), "ACCESO AL PREDIO", size=10, bold=True, color=BRAND_RGB)
                    yy = int(yy + _Cm(0.5))
                    _rect(slide, MARGIN_X, yy, left_w, _Cm(0.7), fill_rgb=(0x94, 0xA3, 0xB8))
                    add_text(slide, MARGIN_X, yy, left_w, _Cm(0.7), (node.get("acceso_predio") or "Sin especificar").upper(),
                             size=11, bold=True, color=WHITE_RGB, align=_PP_ALIGN.CENTER)
                    yy = int(yy + _Cm(0.9))
                    add_text(slide, MARGIN_X, yy, left_w, _Cm(0.5), "SITUACIÓN SOCIAL", size=10, bold=True, color=BRAND_RGB)
                    yy = int(yy + _Cm(0.5))
                    add_text(slide, MARGIN_X, yy, left_w, _Cm(2.0), node.get("situacion_social") or "Sin información registrada",
                             size=9, color=TEXT_RGB)
                    yy = int(yy + _Cm(2.1))
                add_text(slide, MARGIN_X, yy, left_w, _Cm(0.5), "ACTIVIDADES", size=10, bold=True, color=BRAND_RGB)
                yy = int(yy + _Cm(0.5))
                acts = bloque.get("actividades") or []
                acts_text = "\n".join(f"• {a}" for a in acts) if acts else "Sin actividades capturadas"
                add_text(slide, MARGIN_X, yy, left_w, int(SH - BOTTOM_MARGIN - yy), acts_text, size=9, color=TEXT_RGB)

                fotos = bloque.get("fotos") or []
                right_x = int(MARGIN_X + left_w + _Cm(0.4))
                right_w = int(content_w - left_w - _Cm(0.4))
                _foto_grid(slide, fotos, right_x, y, right_w, int(SH - BOTTOM_MARGIN - y), cols=3 if len(fotos) > 4 else 2)

        def slide_avance_grafico(plano_id):
            slide = _clone_membrete()
            plano = planos_by_id.get(plano_id)
            if not plano:
                add_text(slide, MARGIN_X, TOP_MARGIN, content_w, _Cm(1), "Plano no encontrado.",
                         size=13, color=MUTED_RGB, align=_PP_ALIGN.CENTER)
                return
            add_text(slide, MARGIN_X, TOP_MARGIN - _Cm(0.7), content_w, _Cm(0.6), plano.get("nombre") or "",
                     size=14, bold=True, color=BRAND_RGB)
            try:
                snap = _bake_plano_snapshot(plano)
                slide.shapes.add_picture(io.BytesIO(snap), MARGIN_X, TOP_MARGIN, width=content_w, height=int(SH - TOP_MARGIN - BOTTOM_MARGIN))
            except Exception:
                add_picture_b64(slide, plano.get("imagen"), MARGIN_X, TOP_MARGIN, content_w, int(SH - TOP_MARGIN - BOTTOM_MARGIN))

        for s in secciones:
            tipo = s.get("tipo")
            if tipo == "portada":
                slide_portada()
            elif tipo == "mapa_general":
                slide_mapa_general()
            elif tipo == "divisor":
                slide_divisor(s.get("titulo"))
            elif tipo == "financiero":
                slide_financiero()
            elif tipo == "seguimiento_estudios":
                slide_seguimiento_estudios()
            elif tipo == "croquis_estacion":
                slide_croquis_estacion(s.get("node_id"))
            elif tipo == "informacion_particular":
                slide_informacion_particular(s)
            elif tipo == "avance_grafico":
                slide_avance_grafico(s.get("plano_id"))

        # Borra las slides ORIGINALES de la plantilla (solo sirvieron de
        # semilla para clonar vía `_clone_slide` — nunca deben aparecer en
        # el documento final). Siempre índice 0: al removerlo, la siguiente
        # semilla ocupa esa posición.
        for _ in range(n_seed_slides):
            try:
                rId = prs.slides._sldIdLst[0].rId
                prs.part.drop_rel(rId)
                del prs.slides._sldIdLst[0]
            except Exception:
                break

        buf = io.BytesIO()
        prs.save(buf)
        return buf.getvalue()

    pptx_bytes = await asyncio.to_thread(_build_presentacion_pptx_blocking)
    safe_name = re.sub(r"[^A-Za-z0-9_-]+", "_", pres.get("titulo") or "presentacion")[:60] or "presentacion"
    fname = f"{safe_name}_{pres.get('fecha', '')}.pptx"
    return StreamingResponse(
        io.BytesIO(pptx_bytes),
        media_type="application/vnd.openxmlformats-officedocument.presentationml.presentation",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


# === BULK UPLOAD GENÉRICO DE NODOS DESDE EXCEL/CSV =========================
# Columnas reconocidas dinámicamente:
#   - Nombre del nodo: "nombre", "nodo", "nombre del nodo", "nombre del poste"
#     (case-insensitive, sin acentos). Si no se encuentra, se usa la 1ra columna.
#   - Padre (opcional, jerarquía): "padre", "nodo padre", "parent"
#   - Resto de columnas: se guardan tal cual dentro de `metadata` (dict).
#
# Reglas:
#   - Filas con nombre vacío se ignoran.
#   - Upsert por (project_id, name) case-insensitive. Si existe -> actualiza
#     metadata y parent_id; si no -> crea como nodo no-hoja.
#   - Las filas se procesan en orden: primero los nodos sin padre, después
#     los hijos (dos pasadas) para resolver referencias forward.

_NODE_NAME_CANDIDATES = {
    "nombre", "nodo", "nombre del nodo", "nombre del poste",
    "name", "node", "node name",
}
_NODE_PARENT_CANDIDATES = {
    "padre", "nodo padre", "parent", "padre id", "parent id",
}


def _normalize_col(s: str) -> str:
    """Normaliza un encabezado para comparación (lower, sin acentos, sin espacios extra)."""
    if not isinstance(s, str):
        return ""
    s = s.strip().lower()
    repl = {"á": "a", "é": "e", "í": "i", "ó": "o", "ú": "u", "ñ": "n"}
    for k, v in repl.items():
        s = s.replace(k, v)
    return s


def _coerce_cell(v):
    """Convierte celdas de pandas en algo serializable y limpio.
    Ignora NaN/None, recorta strings."""
    try:
        import math
        if v is None:
            return None
        if isinstance(v, float) and math.isnan(v):
            return None
    except Exception:
        pass
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v


@api.get("/projects/{pid}/nodes/bulk-upload/template")
async def bulk_upload_template(
    pid: str,
    user: dict = Depends(require_role(ROLE_COORD)),
):
    """Devuelve una plantilla .xlsx de ejemplo para carga masiva de nodos.

    Columnas:
      - Nombre: nombre del nodo (obligatorio)
      - Padre: nombre del nodo padre (opcional; deja vacío para nodos raíz)
      - Coordenada X, Coordenada Y, Elevación (TN), Dirección: ejemplos de metadatos.
    """
    await ensure_project_access(user, pid)
    try:
        import pandas as pd  # noqa: WPS433
    except Exception as e:  # pragma: no cover
        raise HTTPException(500, f"pandas no disponible: {e}")

    sample = [
        {
            "Nombre": "Tramo 1",
            "Padre": "",
            "Coordenada X": "",
            "Coordenada Y": "",
            "Elevación (TN)": "",
            "Dirección": "Tronco principal",
        },
        {
            "Nombre": "P-101",
            "Padre": "Tramo 1",
            "Coordenada X": 19.432608,
            "Coordenada Y": -99.133209,
            "Elevación (TN)": 2240.5,
            "Dirección": "Av. Reforma 100",
        },
        {
            "Nombre": "P-102",
            "Padre": "Tramo 1",
            "Coordenada X": 19.433100,
            "Coordenada Y": -99.134000,
            "Elevación (TN)": 2241.0,
            "Dirección": "Av. Reforma 120",
        },
        {
            "Nombre": "Tramo 2",
            "Padre": "",
            "Coordenada X": "",
            "Coordenada Y": "",
            "Elevación (TN)": "",
            "Dirección": "Ramal secundario",
        },
        {
            "Nombre": "P-201",
            "Padre": "Tramo 2",
            "Coordenada X": 19.440100,
            "Coordenada Y": -99.145000,
            "Elevación (TN)": 2245.2,
            "Dirección": "Calz. Tlalpan 500",
        },
    ]
    df = pd.DataFrame(sample)

    buf = io.BytesIO()
    with pd.ExcelWriter(buf, engine="openpyxl") as writer:
        df.to_excel(writer, sheet_name="Nodos", index=False)
        # Ajustar ancho de columnas para que sea legible
        ws = writer.sheets["Nodos"]
        widths = {"A": 22, "B": 22, "C": 16, "D": 16, "E": 18, "F": 32}
        for col, w in widths.items():
            ws.column_dimensions[col].width = w
    buf.seek(0)

    headers = {
        "Content-Disposition": 'attachment; filename="plantilla_nodos_dirac.xlsx"',
    }
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers=headers,
    )


@api.post("/projects/{pid}/nodes/bulk-upload")
async def bulk_upload_nodes(
    pid: str,
    file: UploadFile = File(...),
    user: dict = Depends(require_role(ROLE_COORD)),
):
    """Carga masiva genérica de nodos desde un archivo .xlsx o .csv.

    Devuelve resumen: {created, updated, skipped, errors, total}.
    """
    await ensure_project_access(user, pid)
    proj = await db.projects.find_one({"id": pid})
    if not proj:
        raise HTTPException(404, "Proyecto no existe")
    try:
        raw = await file.read()
    except Exception as e:
        raise HTTPException(400, f"No se pudo leer el archivo: {e}")
    if not raw:
        raise HTTPException(400, "Archivo vacío")
    return await _process_nodes_bulk_upload(pid, raw, file.filename or "")


async def _process_nodes_bulk_upload(pid: str, raw: bytes, filename: str) -> dict:
    """Núcleo reutilizable de la carga masiva de nodos.

    Recibe el contenido binario y el nombre original del archivo y devuelve el
    resumen `{total_rows, created, updated, skipped, errors, ...}`. Es invocado
    por:
      - POST /projects/{pid}/nodes/bulk-upload  (endpoint dedicado)
      - POST /projects/{pid}/upload-file        (router genérico)
    """
    fname = (filename or "").lower()
    try:
        import pandas as pd  # noqa: WPS433
    except Exception as e:  # pragma: no cover
        raise HTTPException(500, f"pandas no disponible: {e}")

    try:
        if fname.endswith(".csv"):
            df = pd.read_csv(io.BytesIO(raw), dtype=object, keep_default_na=True)
        elif fname.endswith(".xlsx") or fname.endswith(".xls"):
            df = pd.read_excel(io.BytesIO(raw), dtype=object, engine="openpyxl")
        else:
            # Intento auto: primero xlsx, después csv
            try:
                df = pd.read_excel(io.BytesIO(raw), dtype=object, engine="openpyxl")
            except Exception:
                df = pd.read_csv(io.BytesIO(raw), dtype=object, keep_default_na=True)
    except Exception as e:
        raise HTTPException(400, f"No se pudo parsear el archivo: {e}")

    if df is None or df.empty:
        raise HTTPException(400, "El archivo no contiene filas")

    # Identificar columna de nombre
    cols = list(df.columns)
    norm_to_orig = {_normalize_col(str(c)): c for c in cols}

    name_col = None
    for cand in _NODE_NAME_CANDIDATES:
        if cand in norm_to_orig:
            name_col = norm_to_orig[cand]
            break
    if name_col is None and cols:
        name_col = cols[0]  # fallback: primera columna

    parent_col = None
    for cand in _NODE_PARENT_CANDIDATES:
        if cand in norm_to_orig:
            parent_col = norm_to_orig[cand]
            break

    if name_col is None:
        raise HTTPException(400, "No se pudo identificar la columna de nombre")

    # Cargar nodos existentes del proyecto en memoria (map por nombre-lower)
    existing_docs = await db.location_nodes.find({"project_id": pid}).to_list(length=10000)
    by_name_lower: dict = {}
    for n in existing_docs:
        key = (n.get("name") or "").strip().lower()
        if key:
            by_name_lower[key] = n

    # Calcular siguiente "order" para raíces nuevas
    existing_roots = [n for n in existing_docs if not n.get("parent_id")]
    next_order = max([n.get("order", 0) for n in existing_roots], default=-1) + 1

    summary = {
        "total_rows": int(len(df)),
        "created": 0,
        "updated": 0,
        "skipped": 0,
        "errors": [],
        "name_column": str(name_col),
        "parent_column": str(parent_col) if parent_col else None,
        "metadata_columns": [str(c) for c in cols if c != name_col and c != parent_col],
    }

    # Procesamos en 2 pasadas para resolver referencias de padre forward.
    rows = df.to_dict(orient="records")

    async def upsert_row(row: dict, second_pass: bool = False):
        nonlocal next_order
        raw_name = _coerce_cell(row.get(name_col))
        if raw_name is None or str(raw_name).strip() == "":
            summary["skipped"] += 1
            return
        name = str(raw_name).strip()
        # Resolver padre por nombre (si la columna existe)
        parent_doc = None
        if parent_col:
            raw_parent = _coerce_cell(row.get(parent_col))
            if raw_parent:
                pname = str(raw_parent).strip().lower()
                parent_doc = by_name_lower.get(pname)
                if not parent_doc and not second_pass:
                    # Diferimos: el padre puede aparecer más adelante.
                    return "defer"
        # Construir metadata con resto de columnas
        metadata: dict = {}
        for c in cols:
            if c == name_col or c == parent_col:
                continue
            val = _coerce_cell(row.get(c))
            if val is None:
                continue
            # Convertir tipos no-JSON-serializables
            try:
                import numpy as np  # noqa: WPS433
                if isinstance(val, (np.integer,)):
                    val = int(val)
                elif isinstance(val, (np.floating,)):
                    val = float(val)
            except Exception:
                pass
            if isinstance(val, (datetime,)):
                val = val.isoformat()
            metadata[str(c)] = val

        key = name.lower()
        existing = by_name_lower.get(key)
        if existing:
            # Update: refrescamos metadata y parent_id (si vino padre)
            upd: dict = {"metadata": metadata}
            if parent_doc:
                upd["parent_id"] = parent_doc["id"]
                upd["depth"] = int(parent_doc.get("depth", 0)) + 1
            await db.location_nodes.update_one({"id": existing["id"]}, {"$set": upd})
            existing["metadata"] = metadata
            if parent_doc:
                existing["parent_id"] = parent_doc["id"]
                existing["depth"] = upd["depth"]
            summary["updated"] += 1
        else:
            nid = str(uuid.uuid4())
            parent_id = parent_doc["id"] if parent_doc else None
            depth = (int(parent_doc.get("depth", 0)) + 1) if parent_doc else 0
            order_val = 0 if parent_doc else next_order
            if not parent_doc:
                next_order += 1
            doc = {
                "id": nid,
                "project_id": pid,
                "parent_id": parent_id,
                "name": name,
                "depth": depth,
                "order": order_val,
                "is_leaf": False,
                "measurement_type": None,
                "target_lat": None,
                "target_lon": None,
                "target_elev": None,
                "meta": None,
                "metadata": metadata,
                "created_at": datetime.now(timezone.utc),
            }
            # Si tiene padre que era hoja, ya no lo es
            if parent_doc and parent_doc.get("is_leaf"):
                await db.location_nodes.update_one(
                    {"id": parent_doc["id"]},
                    {"$set": {
                        "is_leaf": False, "measurement_type": None,
                        "target_lat": None, "target_lon": None, "target_elev": None,
                    }},
                )
                parent_doc["is_leaf"] = False
            await db.location_nodes.insert_one(doc)
            doc_clean = {k: v for k, v in doc.items() if k != "_id"}
            by_name_lower[key] = doc_clean
            summary["created"] += 1
        return None

    # Pasada 1
    deferred: list = []
    for idx, row in enumerate(rows):
        try:
            r = await upsert_row(row, second_pass=False)
            if r == "defer":
                deferred.append((idx, row))
        except Exception as e:
            summary["errors"].append({"row": idx + 2, "error": str(e)})

    # Pasada 2 (resuelve padres que se crearon después)
    for idx, row in deferred:
        try:
            await upsert_row(row, second_pass=True)
        except Exception as e:
            summary["errors"].append({"row": idx + 2, "error": str(e)})

    return summary


# === UPLOAD GENÉRICO DE ARCHIVOS DEL PROYECTO ===============================
UPLOADS_DIR = Path(os.environ.get("UPLOADS_DIR", str(ROOT_DIR / "uploads")))
try:
    UPLOADS_DIR.mkdir(parents=True, exist_ok=True)
except Exception as _exc:  # pragma: no cover
    log.warning("[uploads] no se pudo crear %s: %s", UPLOADS_DIR, _exc)

# Conjuntos de tipos para enrutar la lógica.
_NODES_EXTS = {".xlsx", ".xls", ".csv"}
_NODES_MIMES = {
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    "application/vnd.ms-excel",
    "text/csv",
    "application/csv",
}
# PDF / Word / Excel (binarios que solo se guardan en disco).
_ALLOWED_DOC_MIMES = {
    "application/pdf",
    "application/msword",
    "application/vnd.openxmlformats-officedocument.wordprocessingml.document",
    "application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
    "application/vnd.ms-excel",
    "text/csv",
}
_MAX_FILE_BYTES = 20 * 1024 * 1024  # 20 MB (límite acordado para subidas en campo)


def _safe_filename(name: str) -> str:
    base = re.sub(r"[^A-Za-z0-9._-]+", "_", (name or "archivo")).strip("._")
    return base[:120] or "archivo"


@api.post("/projects/{pid}/upload-file")
async def upload_project_file(
    pid: str,
    file: UploadFile = File(...),
    user: dict = Depends(require_role(ROLE_COORD, ROLE_JEFE)),
):
    """
    Router de archivos del proyecto. Acepta multipart/form-data.

    - Si el archivo es Excel/CSV de coordenadas (xlsx, xls, csv) → ejecuta el
      pipeline de carga masiva de nodos y devuelve el resumen.
    - Si es PDF/Word u otro documento permitido → lo guarda en `uploads/{pid}/`
      y lo añade a `project.reference_files`. Devuelve el registro creado.

    Limite por archivo: 25 MB. Solo Coordinador / Jefe de Proyecto.
    """
    await ensure_project_access(user, pid)
    proj = await db.projects.find_one({"id": pid})
    if not proj:
        raise HTTPException(404, "Proyecto no existe")

    try:
        raw = await file.read()
    except Exception as e:
        raise HTTPException(400, f"No se pudo leer el archivo: {e}")
    if not raw:
        raise HTTPException(400, "Archivo vacío")
    if len(raw) > _MAX_FILE_BYTES:
        raise HTTPException(
            413,
            f"Archivo demasiado grande ({len(raw)//1024//1024} MB). Máx {_MAX_FILE_BYTES//1024//1024} MB.",
        )

    orig = file.filename or "archivo"
    ext = (Path(orig).suffix or "").lower()
    ctype = (file.content_type or "").lower().split(";", 1)[0].strip()

    is_nodes = ext in _NODES_EXTS or ctype in _NODES_MIMES
    if is_nodes:
        try:
            summary = await _process_nodes_bulk_upload(pid, raw, orig)
        except HTTPException:
            raise
        except Exception as exc:
            log.exception("[upload-file] bulk_upload falló: %s", exc)
            raise HTTPException(400, f"No se pudo procesar el archivo de nodos: {exc}")
        return {
            "type": "nodes_bulk",
            "filename": orig,
            "mime_type": ctype or "application/octet-stream",
            "size": len(raw),
            "summary": summary,
        }

    # Documento (PDF/Word/etc.) → persistir en disco.
    if ctype and ctype not in _ALLOWED_DOC_MIMES:
        # No bloqueamos por extensión si el MIME es genérico, pero sí lo registramos.
        log.info("[upload-file] MIME no-listado pero aceptado: %s (%s)", ctype, orig)

    safe_name = _safe_filename(orig)
    file_id = uuid.uuid4().hex
    proj_dir = UPLOADS_DIR / pid
    try:
        proj_dir.mkdir(parents=True, exist_ok=True)
        on_disk = proj_dir / f"{file_id}__{safe_name}"
        on_disk.write_bytes(raw)
    except Exception as exc:
        log.exception("[upload-file] no se pudo escribir en disco: %s", exc)
        raise HTTPException(500, f"No se pudo guardar el archivo: {exc}")

    record = {
        "file_id": file_id,
        "name": Path(orig).stem or orig,
        "original_name": orig,
        "mime_type": ctype or "application/octet-stream",
        "size": len(raw),
        "url": f"/api/projects/{pid}/files/{file_id}",
        "path": str(on_disk),
        "uploaded_by": user.get("id"),
        "uploaded_by_name": user.get("name"),
        "uploaded_at": datetime.now(timezone.utc).isoformat(),
    }

    await db.projects.update_one(
        {"id": pid},
        {"$push": {"reference_files": record}},
    )

    return {
        "type": "stored",
        "filename": orig,
        "mime_type": record["mime_type"],
        "size": record["size"],
        "file": record,
    }


@api.get("/projects/{pid}/files/{file_id}")
async def download_project_file(
    pid: str,
    file_id: str,
    user: dict = Depends(current_user),
):
    """Descarga un archivo previamente subido al proyecto.

    Requiere acceso al proyecto (rol/scope).
    """
    await ensure_project_access(user, pid)
    proj = await db.projects.find_one({"id": pid}, {"_id": 0, "reference_files": 1})
    if not proj:
        raise HTTPException(404, "Proyecto no existe")
    refs = (proj or {}).get("reference_files") or []
    rec = next((f for f in refs if (f or {}).get("file_id") == file_id), None)
    if not rec:
        raise HTTPException(404, "Archivo no encontrado")
    on_disk = Path(rec.get("path") or "")
    if not on_disk.exists():
        raise HTTPException(404, "Archivo no disponible en disco")
    return FileResponse(
        path=str(on_disk),
        media_type=rec.get("mime_type") or "application/octet-stream",
        filename=rec.get("original_name") or on_disk.name,
    )


@api.delete("/projects/{pid}/files/{file_id}")
async def delete_project_file(
    pid: str,
    file_id: str,
    user: dict = Depends(require_role(ROLE_COORD, ROLE_JEFE)),
):
    """Elimina un archivo adjunto del proyecto (registro + binario en disco)."""
    await ensure_project_access(user, pid)
    proj = await db.projects.find_one({"id": pid}, {"_id": 0, "reference_files": 1})
    if not proj:
        raise HTTPException(404, "Proyecto no existe")
    refs = (proj or {}).get("reference_files") or []
    rec = next((f for f in refs if (f or {}).get("file_id") == file_id), None)
    if not rec:
        raise HTTPException(404, "Archivo no encontrado")
    # Quitar de la BD primero (la verdad de origen).
    await db.projects.update_one(
        {"id": pid},
        {"$pull": {"reference_files": {"file_id": file_id}}},
    )
    # Best-effort: borrar binario.
    try:
        on_disk = Path(rec.get("path") or "")
        if on_disk.exists():
            on_disk.unlink()
    except Exception as exc:
        log.warning("[upload-file] no se pudo borrar binario: %s", exc)
    return {"ok": True, "file_id": file_id}


