@api.delete("/projects/{pid}/conceptos/import_evm/{import_id}")
async def import_evm_descartar_sesion(pid: str, import_id: str, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    await ensure_project_access(user, pid)
    await db.evm_import_sessions.delete_one({"id": import_id, "project_id": pid})
    return {"ok": True}


@api.post("/projects/{pid}/conceptos/import_evm/{import_id}/commit")
async def import_evm_commit(pid: str, import_id: str, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Paso 4: aplica el resultado ya validado — no recibe body, todo lo
    necesario ya quedó confirmado en la sesión de staging."""
    proyecto_import = await ensure_project_access(user, pid)
    session = await db.evm_import_sessions.find_one({"id": import_id, "project_id": pid})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    validated_rows = session.get("validated_rows")
    if validated_rows is None:
        raise HTTPException(400, "Todavía no se valida esta importación. Llama primero a /validate.")
    partida_id = session.get("validated_partida_id")
    if partida_id:
        partida = await db.partidas.find_one({"id": partida_id, "project_id": pid})
        if not partida:
            raise HTTPException(404, "La partida validada ya no existe en este proyecto")

    correcciones = session.get("correcciones") or {}
    duplicados_accion = session.get("duplicados_accion", "omitir")
    vista = _calcular_vista_filas_evm(validated_rows, correcciones, contexto=session.get("validated_contexto"))

    try:
        resultado = await _ejecutar_commit_evm_con_compensacion(
            db.conceptos, db.evm_import_sessions, _log_bitacora,
            pid, import_id, partida_id, vista, duplicados_accion, user, session.get("filename"),
            partidas_col=db.partidas, cadencia=cadencia_de_proyecto(proyecto_import),
        )
    finally:
        await db.evm_import_sessions.delete_one({"id": import_id})

    return resultado


# === Registro de avance =========================================================
@api.post("/avances", response_model=RegistroAvanceOut)
async def create_avance(body: RegistroAvanceIn, user: dict = Depends(current_user)):
    _assert_write_allowed(user)  # bloquea Jefe de Proyecto (solo lectura global)
    concepto = await db.conceptos.find_one({"id": body.concepto_id})
    if not concepto:
        raise HTTPException(404, "Concepto no existe")
    await ensure_project_access(user, concepto["project_id"])
    project = await db.projects.find_one({"id": concepto["project_id"]})
    modo_avance = (project or {}).get("modo_avance", "CANTIDAD")

    # Idempotencia offline: si ya existe un registro con el mismo client_id (de este
    # proyecto y de este usuario), se devuelve el existente en vez de duplicar. Va
    # ANTES de validar: un reintento de un ajuste ya guardado no debe fallar por
    # "dejaría el acumulado en negativo" con su propio efecto ya aplicado.
    if body.client_id:
        dup = await db.registros_avance.find_one({
            "client_id": body.client_id, "project_id": concepto["project_id"], "capturado_por": user["id"],
        })
        if dup:
            return await _registro_avance_out(dup)

    # TODO(migración estacion_id→nodo_id): resuelve el campo legado antes de
    # cualquier validación de nodo_id — ver el TODO completo en
    # RegistroAvanceIn.estacion_id. Retirar este bloque junto con ese campo.
    nodo_id_efectivo = body.nodo_id
    if body.estacion_id:
        if body.nodo_id and body.nodo_id != body.estacion_id:
            log.warning(
                f"[avance] payload con nodo_id y estacion_id legado distintos "
                f"(nodo_id={body.nodo_id!r}, estacion_id={body.estacion_id!r}) — gana nodo_id"
            )
        elif not body.nodo_id:
            nodo_id_efectivo = body.estacion_id

    # nodo_id: obligatorio SOLO en modo MATRIZ (ver ProjectOut.modo_avance).
    # En cualquier otro modo es opcional y nunca bloqueante — pero si viene,
    # tiene que ser un nodo real de este proyecto (mismo criterio que
    # scope_node_id en invitaciones).
    if modo_avance == "MATRIZ" and not nodo_id_efectivo:
        raise HTTPException(400, "Este proyecto captura avance en modo MATRIZ: nodo_id es obligatorio")
    if nodo_id_efectivo:
        nodo = await db.location_nodes.find_one({"id": nodo_id_efectivo, "project_id": concepto["project_id"]})
        if not nodo:
            raise HTTPException(404, "nodo_id inválido para este proyecto")

    # A-01: la cantidad debe ser > 0 (o un ajuste con motivo), numérica y no futura.
    # A-02: ya NO hay tope de 100% ni de volumen contratado — lo que excede se
    # permite y se hace visible como volumen excedente.
    try:
        cantidad_dec, fecha_norm, motivo_norm = validar_avance(
            tipo=body.tipo, cantidad=body.cantidad_ejecutada, fecha=body.fecha,
            motivo=body.motivo, hoy=hoy_proyecto(project), modo_avance=modo_avance,
        )
    except ValueError as e:
        raise HTTPException(400, str(e))

    # PRECIO_ALZADO (modo_avance=PORCENTAJE): el residente captura el PORCENTAJE al
    # que llegó el concepto. Un valor menor al anterior es un retroceso real de
    # obra: se PERMITE (nunca se rechaza), pero se marca para revisión.
    es_retroceso = False
    if modo_avance == "PORCENTAJE":
        anterior = to_decimal(await _concepto_ejecutado_acumulado(body.concepto_id, "PORCENTAJE"))
        es_retroceso = cantidad_dec < anterior
    elif body.tipo == "ajuste":
        acumulado = to_decimal(await _concepto_ejecutado_acumulado(body.concepto_id, modo_avance))
        if acumulado + cantidad_dec < 0:
            raise HTTPException(400, "El ajuste dejaría el acumulado del concepto en negativo.")

    # --- Congelación histórica EVM (aditivo) ----------------------------
    # El precio SIEMPRE se calcula en el servidor, nunca se acepta del
    # body — si viniera del cliente, un dispositivo (o una cola offline
    # vieja) podría inyectar un precio arbitrario. Si el concepto todavía
    # no tiene datos EVM (meta_cantidad/importe_total_editable), se congela
    # su precio_unitario estático de siempre — así el campo queda poblado
    # de manera uniforme para avances viejos y nuevos, sin bloquear la
    # captura de campo mientras el catálogo se termina de migrar.
    if _concepto_tiene_datos_evm(concepto):
        precio_congelado = compute_precio_unitario_dinamico(concepto["importe_total_editable"], concepto["meta_cantidad"])
    else:
        precio_congelado = to_decimal(concepto["precio_unitario"])
    importe_congelado = cantidad_dec * precio_congelado

    fuera_de_ventana = False
    if concepto.get("fecha_inicio") and concepto.get("fecha_fin"):
        try:
            fecha_avance = date.fromisoformat(fecha_norm)
            fuera_de_ventana = not (
                date.fromisoformat(concepto["fecha_inicio"]) <= fecha_avance <= date.fromisoformat(concepto["fecha_fin"])
            )
        except ValueError:
            pass  # fecha del avance no es YYYY-MM-DD parseable: no bloquea la captura, solo no se puede comparar

    aid = str(uuid.uuid4())
    doc = {
        "id": aid,
        "concepto_id": body.concepto_id,
        "project_id": concepto["project_id"],
        "fecha": fecha_norm,
        "cantidad_ejecutada": body.cantidad_ejecutada.strip(),
        "tipo": body.tipo,
        "motivo": motivo_norm,
        "nodo_id": nodo_id_efectivo,
        "reporte_id": body.reporte_id,
        "fotos": body.fotos,
        "photo_captions": body.photo_captions,
        "capturado_por": user["id"],
        "capturado_por_nombre": user.get("name"),
        "creado_en": datetime.now(timezone.utc),
        "sincronizado": True,
        "editado_en": None,
        "client_id": body.client_id,
        # Este endpoint es la captura normal de campo — origen SIEMPRE "APP",
        # nunca viene del body (la línea base se crea por su propio flujo,
        # todavía sin construir, ver _reemplazar_linea_base).
        "origen": "APP",
        "linea_base_batch_id": None,
        "es_retroceso": es_retroceso,
        "precio_unitario_congelado": dec_to_str(precio_congelado),
        "importe_ganado_congelado": dec_to_str(importe_congelado),
        "fuera_de_ventana": fuera_de_ventana,
    }
    try:
        await db.registros_avance.insert_one(doc)
    except DuplicateKeyError:
        # Dos envíos casi simultáneos con el mismo client_id (reintento de la cola
        # mientras el POST original seguía en vuelo): gana el primero.
        existente = await db.registros_avance.find_one({"client_id": body.client_id})
        if existente:
            return await _registro_avance_out(existente)
        raise
    if body.tipo == "ajuste":
        await _log_bitacora(
            concepto["project_id"], "ajuste_avance", "registro_avance", aid,
            "cantidad_ejecutada", None, f"{body.cantidad_ejecutada.strip()} · motivo: {motivo_norm}", user,
        )
    return await _registro_avance_out(doc)


def _validar_permiso_edicion_avance(avance_doc: dict, user: dict) -> None:
    """Un RegistroAvance con origen=LINEA_BASE está MIGRADO: no se corrige
    con la ventana normal de 24h/autor (ver update_avance) — solo
    Sub-Coordinador, sin excepción, y SIEMPRE queda bitácora (la escribe el
    caller tras pasar esta validación, no aquí — este helper solo decide si
    se permite, para poder probarlo sin tocar Mongo)."""
    if avance_doc.get("origen") == "LINEA_BASE" and user.get("role") != ROLE_SUB:
        raise HTTPException(
            403,
            "Este registro es parte de la línea base migrada del proyecto — "
            "solo el Sub-Coordinador puede corregirlo, y queda registrado en bitácora.",
        )


def _validar_ventana_edicion_avance(avance_doc: dict, user: dict) -> None:
    """Ventana normal de corrección/borrado (fuera de LINEA_BASE, ya cubierta
    por _validar_permiso_edicion_avance arriba): el autor original puede
    corregir o borrar su propio registro durante 24h; después de eso, o si
    el registro es de otro usuario, solo Sub-Coordinador puede autorizarlo.
    Compartida por update_avance y delete_avance para no duplicar la misma
    ventana en dos endpoints."""
    creado_en = avance_doc["creado_en"]
    creado_en = creado_en if creado_en.tzinfo else creado_en.replace(tzinfo=timezone.utc)
    dentro_de_ventana = (datetime.now(timezone.utc) - creado_en) <= timedelta(hours=24)
    es_autor = avance_doc["capturado_por"] == user["id"]
    if not ((es_autor and dentro_de_ventana) or user.get("role") == ROLE_SUB):
        raise HTTPException(403, "Fuera de la ventana de edición; requiere autorización de Sub-Coordinador")


@api.patch("/avances/{avance_id}", response_model=RegistroAvanceOut)
async def update_avance(avance_id: str, body: RegistroAvancePatch, user: dict = Depends(current_user)):
    _assert_write_allowed(user)
    avance = await db.registros_avance.find_one({"id": avance_id})
    if not avance:
        raise HTTPException(404, "Registro de avance no existe")
    await ensure_project_access(user, avance["project_id"])
    _validar_permiso_edicion_avance(avance, user)

    if avance.get("origen") != "LINEA_BASE":
        # Un registro de línea base ya pasó el chequeo más estricto de
        # _validar_permiso_edicion_avance arriba, así que no vuelve a
        # aplicar esta ventana.
        _validar_ventana_edicion_avance(avance, user)

    upd: dict = {"editado_en": datetime.now(timezone.utc)}
    if body.cantidad_ejecutada is not None:
        project = await db.projects.find_one({"id": avance["project_id"]})
        modo_edit = (project or {}).get("modo_avance", "CANTIDAD")
        tipo_reg = avance.get("tipo") or "normal"
        try:
            nueva_q, _f, _m = validar_avance(
                tipo=tipo_reg, cantidad=body.cantidad_ejecutada, fecha=hoy_proyecto(project).isoformat(),
                motivo=avance.get("motivo"), hoy=hoy_proyecto(project), modo_avance=modo_edit,
            )
        except ValueError as e:
            raise HTTPException(400, str(e))
        if tipo_reg == "ajuste" and modo_edit != "PORCENTAJE":
            acumulado = to_decimal(await _concepto_ejecutado_acumulado(avance["concepto_id"], modo_edit))
            if acumulado - to_decimal(avance["cantidad_ejecutada"]) + nueva_q < 0:
                raise HTTPException(400, "El ajuste dejaría el acumulado del concepto en negativo.")
        upd["cantidad_ejecutada"] = body.cantidad_ejecutada.strip()
        # El importe congelado se recalcula con el MISMO precio congelado: antes, editar la
        # cantidad dejaba el valor ganado con el importe anterior.
        if avance.get("precio_unitario_congelado") is not None:
            upd["importe_ganado_congelado"] = dec_to_str(nueva_q * to_decimal(avance["precio_unitario_congelado"]))
    if body.fotos is not None:
        upd["fotos"] = body.fotos
    if body.photo_captions is not None:
        upd["photo_captions"] = body.photo_captions
    await db.registros_avance.update_one({"id": avance_id}, {"$set": upd})
    if avance.get("origen") == "LINEA_BASE":
        await _log_bitacora(
            avance["project_id"], "correccion_linea_base", "registro_avance", avance_id,
            "cantidad_ejecutada", avance.get("cantidad_ejecutada"), body.cantidad_ejecutada, user,
        )
    if avance.get("tipo") == "ajuste" and body.cantidad_ejecutada is not None:
        await _log_bitacora(
            avance["project_id"], "ajuste_avance_editado", "registro_avance", avance_id,
            "cantidad_ejecutada", avance.get("cantidad_ejecutada"), body.cantidad_ejecutada.strip(), user,
        )
    updated = await db.registros_avance.find_one({"id": avance_id})
    return await _registro_avance_out(updated)


@api.delete("/avances/{avance_id}")
async def delete_avance(avance_id: str, user: dict = Depends(current_user)):
    """Borra un RegistroAvance — mismo permiso que corregirlo (ver
    update_avance/_validar_permiso_edicion_avance): existe sobre todo para
    poder limpiar filas mal capturadas o mal importadas (ver
    import_avances) sin tener que esperar a un Sub-Coordinador para cada
    una, dentro de la ventana normal de 24h/autor."""
    _assert_write_allowed(user)
    avance = await db.registros_avance.find_one({"id": avance_id})
    if not avance:
        raise HTTPException(404, "Registro de avance no existe")
    await ensure_project_access(user, avance["project_id"])
    _validar_permiso_edicion_avance(avance, user)
    if avance.get("origen") != "LINEA_BASE":
        _validar_ventana_edicion_avance(avance, user)

    await db.registros_avance.delete_one({"id": avance_id})
    if avance.get("origen") == "LINEA_BASE":
        await _log_bitacora(
            avance["project_id"], "borrado_linea_base", "registro_avance", avance_id,
            "cantidad_ejecutada", avance.get("cantidad_ejecutada"), None, user,
        )
    return {"ok": True}


@api.get("/projects/{pid}/avances", response_model=List[RegistroAvanceOut])
async def list_avances(
    pid: str,
    desde: Optional[str] = None,
    hasta: Optional[str] = None,
    partida_id: Optional[str] = None,
    concepto_id: Optional[str] = None,
    user: dict = Depends(current_user),
):
    """Para la pantalla 'Visualizar avance' (reporte por periodo)."""
    await ensure_project_access(user, pid)
    query: dict = {"project_id": pid}
    if desde or hasta:
        rango: dict = {}
        if desde:
            rango["$gte"] = desde
        if hasta:
            rango["$lte"] = hasta
        query["fecha"] = rango
    if concepto_id:
        query["concepto_id"] = concepto_id
    elif partida_id:
        partida_ids = await _partida_subtree_ids_en_proyecto(pid, partida_id)
        conceptos = await db.conceptos.find({"partida_id": {"$in": partida_ids}}).to_list(length=100000)
        query["concepto_id"] = {"$in": [c["id"] for c in conceptos]}
    docs = await db.registros_avance.find(query).sort("fecha", -1).to_list(length=100000)
    return [await _registro_avance_out(d) for d in docs]


class AvancesResumenOut(BaseModel):
    total_registros: int
    importe_total: str


@api.get("/projects/{pid}/avances/resumen", response_model=AvancesResumenOut)
async def avances_resumen(
    pid: str,
    desde: Optional[str] = None,
    hasta: Optional[str] = None,
    partida_id: Optional[str] = None,
    concepto_id: Optional[str] = None,
    user: dict = Depends(current_user),
):
    """Sumatoria de importe (cantidad_ejecutada x precio_unitario del concepto)
    para el periodo filtrado _ mismos filtros que list_avances. Se calcula
    aqui con Decimal (nunca float) para no duplicar aritmetica de dinero en
    el frontend (ver src/utils/money.ts, que prohibe parseFloat)."""
    await ensure_project_access(user, pid)
    query: dict = {"project_id": pid}
    if desde or hasta:
        rango: dict = {}
        if desde:
            rango["$gte"] = desde
        if hasta:
            rango["$lte"] = hasta
        query["fecha"] = rango
    if concepto_id:
        query["concepto_id"] = concepto_id
    elif partida_id:
        partida_ids = await _partida_subtree_ids_en_proyecto(pid, partida_id)
        conceptos = await db.conceptos.find({"partida_id": {"$in": partida_ids}}).to_list(length=100000)
        query["concepto_id"] = {"$in": [c["id"] for c in conceptos]}
    docs = await db.registros_avance.find(query).to_list(length=100000)
    concepto_ids = list({d["concepto_id"] for d in docs})
    conceptos_por_id_resumen: dict = {}
    if concepto_ids:
        cs = await db.conceptos.find({"id": {"$in": concepto_ids}}).to_list(length=len(concepto_ids))
        conceptos_por_id_resumen = {c["id"]: c for c in cs}
    total = Decimal("0")
    for d in docs:
        total += _registro_importe_efectivo(d, conceptos_por_id_resumen.get(d["concepto_id"]))
    return AvancesResumenOut(total_registros=len(docs), importe_total=dec_to_str(round_money(total)))


class RegistroAvanceImportErrorOut(BaseModel):
    fila: int
    motivo: str


class RegistroAvanceImportResultOut(BaseModel):
    total_filas: int
    creados: int
    # Filas creadas en modo PORCENTAJE cuyo valor fue MENOR que el último
    # conocido para ese concepto (dentro del archivo o ya en Mongo) — no se
    # rechazan (mismo criterio que create_avance: un retroceso real de obra
    # se permite), pero se cuentan aparte para que quien importó revise si
    # fue un error de captura o un retroceso real.
    retrocesos: int
    errores: List[RegistroAvanceImportErrorOut]
    errores_truncados: bool  # True si hubo más errores de los que se listan en `errores`


_REGISTRO_AVANCE_IMPORT_MAX_ERRORES = 200


@api.get("/projects/{pid}/avances/import/plantilla.xlsx")
async def avances_import_plantilla(pid: str, user: dict = Depends(current_user)):
    """Plantilla descargable para el importador masivo de Registro de Avance
    (EV) — columnas Clave/Fecha/Cantidad ejecutada, una fila de ejemplo y una
    hoja de instrucciones (mismo criterio que /gastos_reales/import/plantilla.xlsx).
    A diferencia de esa, esta plantilla SÍ es por proyecto: el significado de
    "Cantidad ejecutada" depende de project.modo_avance (ver create_avance:
    incremental en CANTIDAD, % acumulado en PORCENTAJE), así que el ejemplo y
    las instrucciones cambian según el modo configurado."""
    await ensure_project_access(user, pid)
    project = await db.projects.find_one({"id": pid})
    if not project:
        raise HTTPException(404, "Proyecto no existe")
    modo_avance = project.get("modo_avance", "CANTIDAD")

    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment
    from openpyxl.utils import get_column_letter

    wb = Workbook()
    ws = wb.active
    ws.title = "Registro de avance"

    headers = ["Clave", "Fecha", "Cantidad ejecutada"]
    for col, h in enumerate(headers, start=1):
        cell = ws.cell(row=1, column=col, value=h)
        cell.font = Font(bold=True, color="FFFFFF")
        cell.fill = PatternFill("solid", fgColor="1E3A8A")
        cell.alignment = Alignment(horizontal="center")

    ejemplo_cantidad = "45" if modo_avance == "PORCENTAJE" else "120.50"
    ejemplo = ["C-001", date(2026, 2, 15), ejemplo_cantidad]
    for col, v in enumerate(ejemplo, start=1):
        cell = ws.cell(row=2, column=col, value=v)
        if col == 2:
            cell.number_format = "DD/MM/YYYY"

    for i, w in enumerate([14, 14, 20], start=1):
        ws.column_dimensions[get_column_letter(i)].width = w
    ws.freeze_panes = "A2"

    ws2 = wb.create_sheet("Instrucciones")
    if modo_avance == "PORCENTAJE":
        instrucciones = [
            "Cómo llenar esta plantilla para el importador masivo de Registro de Avance (EV)",
            "",
            "Este proyecto captura avance en modo PORCENTAJE (precio alzado):",
            "1. Clave: la clave de un concepto que YA EXISTA en el catálogo de este proyecto (ej. C-001). "
            "Si la clave no existe, esa fila se reporta como error y no se importa — el resto del archivo sí se procesa.",
            "2. Fecha: fecha en que se reportó ese avance. DEBE ser una celda con formato de FECHA de Excel, "
            "como en la fila de ejemplo — si Excel la trae como texto no se va a leer.",
            "3. Cantidad ejecutada: el PORCENTAJE ACUMULADO al que llegó el concepto en esa fecha (0 a 100), "
            "NO un incremento. Ej. si el concepto va al 45%, se pone 45 — no importa cuánto se puso el mes anterior. "
            "Para cada concepto, la fila con la fecha MÁS RECIENTE es la que manda.",
            "4. Un valor menor al de una fila anterior del mismo concepto se acepta igual (nunca se rechaza un "
            "retroceso real de obra), pero queda marcado para revisión.",
            "",
            "No hay límite práctico de filas — está pensado para cargar de golpe meses o años de avance histórico.",
            "No borres la fila de encabezado (fila 1). La fila 2 es solo un ejemplo — bórrala antes de importar.",
        ]
    else:
        modo_txt = "MATRIZ (por nodo/estación)" if modo_avance == "MATRIZ" else "CANTIDAD"
        instrucciones = [
            "Cómo llenar esta plantilla para el importador masivo de Registro de Avance (EV)",
            "",
            f"Este proyecto captura avance en modo {modo_txt}:",
            "1. Clave: la clave de un concepto que YA EXISTA en el catálogo de este proyecto (ej. C-001). "
            "Si la clave no existe, esa fila se reporta como error y no se importa — el resto del archivo sí se procesa.",
            "2. Fecha: fecha en que se ejecutó ese avance. DEBE ser una celda con formato de FECHA de Excel, "
            "como en la fila de ejemplo — si Excel la trae como texto no se va a leer.",
            "3. Cantidad ejecutada: la cantidad física ejecutada ESE día para ese concepto (incremental — "
            "si el mismo concepto tiene varias fechas, se SUMAN, igual que capturar varios días desde la app).",
            "",
            "No hay límite práctico de filas — está pensado para cargar de golpe meses o años de avance histórico.",
            "No borres la fila de encabezado (fila 1). La fila 2 es solo un ejemplo — bórrala antes de importar.",
        ]
        if modo_avance == "MATRIZ":
            instrucciones.append(
                "ADVERTENCIA: este proyecto captura avance en modo MATRIZ (requiere nodo/estación por registro). "
                "El importador masivo todavía NO soporta este modo — el archivo se rechazará. Usa la captura manual "
                "por nodo desde la app."
            )
    for i, txt in enumerate(instrucciones, start=1):
        c = ws2.cell(row=i, column=1, value=txt)
        if i == 1:
            c.font = Font(bold=True, size=13, color="1E3A8A")
    ws2.column_dimensions["A"].width = 110

    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": 'attachment; filename="plantilla_registro_avance.xlsx"'},
    )


@api.post("/projects/{pid}/avances/import", response_model=RegistroAvanceImportResultOut)
async def import_avances(
    pid: str, file: UploadFile = File(...), user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD)),
):
    """Importador masivo de Registro de Avance (EV) — mismo patrón que
    import_gastos_reales: plantilla FIJA (Clave/Fecha/Cantidad ejecutada, ver
    /projects/{pid}/avances/import/plantilla.xlsx), sin wizard de mapeo/
    staging, se valida y comitea en un solo request; las filas con error no
    se insertan y se reportan para corregirlas y volver a subir solo esas.

    A diferencia de Gasto Real, la interpretación de "Cantidad ejecutada"
    depende de project.modo_avance (ver create_avance): incremental (se suma)
    en CANTIDAD, % acumulado-al-momento (la fecha más reciente manda) en
    PORCENTAJE — replicando exactamente la misma lógica de congelación de
    precio/importe y de detección de retroceso que la captura individual
    desde la app, para que un importe de EV cargado por Excel valga lo mismo
    que uno capturado a mano. MATRIZ no se soporta (cada registro necesitaría
    un nodo_id que esta plantilla no captura) — se rechaza con un mensaje
    claro en vez de inventar un nodo o dejarlo en null en silencio."""
    await ensure_project_access(user, pid)
    project = await db.projects.find_one({"id": pid})
    if not project:
        raise HTTPException(404, "Proyecto no existe")
    modo_avance = project.get("modo_avance", "CANTIDAD")
    if modo_avance == "MATRIZ":
        raise HTTPException(
            400,
            "Este proyecto captura avance en modo MATRIZ (por nodo/estación) — el importador masivo no soporta "
            "este modo todavía porque cada registro necesita un nodo, que esta plantilla no captura. Usa la "
            "captura manual por nodo desde la app.",
        )

    content = await file.read()
    sheets = _read_workbook_sheets(file.filename or "archivo.xlsx", content)
    if not sheets:
        raise HTTPException(400, "El archivo no tiene hojas legibles")
    rows = next(iter(sheets.values()))
    if len(rows) < 2:
        raise HTTPException(400, "El archivo no tiene filas de datos (solo encabezado, o está vacío)")

    headers = [str(c).strip() if c is not None else "" for c in rows[0]]
    normalized = [_normalize_text(h) for h in headers]

    def find_col(*keywords: str) -> Optional[int]:
        for idx, h in enumerate(normalized):
            if any(kw in h for kw in keywords):
                return idx
        return None

    idx_clave = find_col("clave", "concepto")
    idx_fecha = find_col("fecha")
    idx_cantidad = find_col("cantidad", "ejecutada")
    if idx_clave is None or idx_fecha is None or idx_cantidad is None:
        raise HTTPException(
            400,
            "El archivo debe tener columnas Clave, Fecha y Cantidad ejecutada. "
            f"Descarga la plantilla en /projects/{pid}/avances/import/plantilla.xlsx.",
        )

    data_rows = rows[1:]
    cantidades_raw = [r[idx_cantidad] if idx_cantidad < len(r) else None for r in data_rows]
    convencion = detectar_convencion(cantidades_raw)

    conceptos = await db.conceptos.find({"project_id": pid}).to_list(length=100000)
    conceptos_por_clave = {c["clave"]: c for c in conceptos}

    # Estado "más reciente conocido" por concepto en modo PORCENTAJE, para
    # marcar es_retroceso fila a fila igual que create_avance marcaría cada
    # captura individual llegando en este mismo orden — arranca desde lo que
    # ya hubiera en Mongo antes de este import.
    ultimo_valor: dict = {}
    if modo_avance == "PORCENTAJE":
        concepto_ids_en_archivo = set()
        for row in data_rows:
            clave_raw = row[idx_clave] if idx_clave < len(row) else None
            if clave_raw not in (None, ""):
                c = conceptos_por_clave.get(str(clave_raw).strip())
                if c:
                    concepto_ids_en_archivo.add(c["id"])
        for cid in concepto_ids_en_archivo:
            ultimo_valor[cid] = to_decimal(await _concepto_ejecutado_acumulado(cid, "PORCENTAJE"))

    docs: List[dict] = []
    errores: List[dict] = []
    retrocesos = 0
    ahora = datetime.now(timezone.utc)
    hoy_import = hoy_proyecto(project)
    for i, row in enumerate(data_rows):
        fila_num = i + 2  # +1 por encabezado (fila 1), +1 porque Excel es 1-based
        clave_raw = row[idx_clave] if idx_clave < len(row) else None
        if clave_raw in (None, ""):
            continue  # fila vacía/de relleno, se ignora silenciosamente

        clave = str(clave_raw).strip()
        concepto = conceptos_por_clave.get(clave)
        if not concepto:
            errores.append({"fila": fila_num, "motivo": f"No existe ningún concepto con clave '{clave}' en este proyecto"})
            continue

        fecha_raw = row[idx_fecha] if idx_fecha < len(row) else None
        fecha_iso = _fecha_excel_a_iso(fecha_raw)
        if fecha_iso is None:
            errores.append({"fila": fila_num, "motivo": f"Fecha inválida o no es una celda de fecha de Excel: {fecha_raw!r}"})
            continue

        cantidad_raw = row[idx_cantidad] if idx_cantidad < len(row) else None
        try:
            cantidad = _parse_celda_numerica(cantidad_raw, convencion)
        except (CeldaErrorExcelError, NumeroAmbiguoError, ValueError) as e:
            errores.append({"fila": fila_num, "motivo": str(e)})
            continue

        try:
            _q, fecha_iso, _m = validar_avance(
                tipo="normal", cantidad=cantidad, fecha=fecha_iso, motivo=None,
                hoy=hoy_import, modo_avance=modo_avance,
            )
        except ValueError as e:
            errores.append({"fila": fila_num, "motivo": str(e)})
            continue

        es_retroceso = False
        if modo_avance == "PORCENTAJE":
            anterior = ultimo_valor.get(concepto["id"], to_decimal("0"))
            es_retroceso = cantidad < anterior
            if es_retroceso:
                retrocesos += 1
            ultimo_valor[concepto["id"]] = cantidad

        if _concepto_tiene_datos_evm(concepto):
            precio_congelado = compute_precio_unitario_dinamico(concepto["importe_total_editable"], concepto["meta_cantidad"])
        else:
            precio_congelado = to_decimal(concepto["precio_unitario"])
        importe_congelado = cantidad * precio_congelado

        fuera_de_ventana = False
        if concepto.get("fecha_inicio") and concepto.get("fecha_fin"):
            fecha_avance_d = date.fromisoformat(fecha_iso)
            fuera_de_ventana = not (
                date.fromisoformat(concepto["fecha_inicio"]) <= fecha_avance_d <= date.fromisoformat(concepto["fecha_fin"])
            )

        docs.append({
            "id": str(uuid.uuid4()), "concepto_id": concepto["id"], "project_id": pid, "fecha": fecha_iso,
            "cantidad_ejecutada": dec_to_str(cantidad), "nodo_id": None, "reporte_id": None,
            "fotos": [], "photo_captions": [], "capturado_por": user["id"], "capturado_por_nombre": user.get("name"),
            "creado_en": ahora, "sincronizado": True, "editado_en": None, "client_id": None,
            "origen": "APP", "linea_base_batch_id": None, "es_retroceso": es_retroceso,
            "precio_unitario_congelado": dec_to_str(precio_congelado),
            "importe_ganado_congelado": dec_to_str(importe_congelado),
            "fuera_de_ventana": fuera_de_ventana,
        })

    if docs:
        await db.registros_avance.insert_many(docs)

    truncados = len(errores) > _REGISTRO_AVANCE_IMPORT_MAX_ERRORES
    return RegistroAvanceImportResultOut(
        total_filas=len(data_rows), creados=len(docs), retrocesos=retrocesos,
        errores=[RegistroAvanceImportErrorOut(**e) for e in errores[:_REGISTRO_AVANCE_IMPORT_MAX_ERRORES]],
        errores_truncados=truncados,
    )


# === A-01 Validación de avances · A-02 Volumen excedente y sobrecosto ==========
# Decisión de negocio: en obra es normal ejecutar más volumen o gastar más de lo
# presupuestado, así que NO se bloquea. Se permite, se separa (volumen excedente,
# EV contractual vs EV total) y se hace visible (Lista por excepción, EAC/ETC/VAC).
# Lo que sí se rechaza: cantidades <= 0, texto y fechas futuras. Una corrección se
# captura como "ajuste" con motivo obligatorio y queda en la bitácora.
MOTIVO_AJUSTE_MIN_CARACTERES = 5
ESTATUS_AUTORIZACION = ("pendiente_autorizacion", "autorizado", "rechazado")
EstatusAutorizacion = Literal["pendiente_autorizacion", "autorizado", "rechazado"]


def validar_avance(
    *, tipo: str, cantidad: Any, fecha: str, motivo: Optional[str], hoy: date, modo_avance: str,
) -> Tuple[Decimal, str, Optional[str]]:
    """Valida un avance ANTES de guardarlo. Devuelve (cantidad, fecha, motivo limpio).
    Lanza ValueError con un mensaje legible en es-MX (el handler lo vuelve 400)."""
    try:
        q = to_decimal(cantidad if cantidad is not None else "")
    except (ValueError, TypeError, InvalidOperation):
        raise ValueError("La cantidad debe ser un número.")
    if not q.is_finite():
        raise ValueError("La cantidad debe ser un número.")
    try:
        f = date.fromisoformat((fecha or "").strip())
    except ValueError:
        raise ValueError("La fecha debe tener el formato AAAA-MM-DD.")
    if f > hoy:
        raise ValueError("La fecha del avance no puede ser futura.")
    motivo_limpio = (motivo or "").strip() or None
    if tipo == "ajuste":
        if modo_avance == "PORCENTAJE":
            raise ValueError(
                "En proyectos que capturan porcentaje no se usan ajustes: captura el porcentaje correcto."
            )
        if q == 0:
            raise ValueError("El ajuste no puede ser cero.")
        if not motivo_limpio or len(motivo_limpio) < MOTIVO_AJUSTE_MIN_CARACTERES:
            raise ValueError(
                f"El motivo del ajuste es obligatorio (mínimo {MOTIVO_AJUSTE_MIN_CARACTERES} caracteres)."
            )
    else:
        if q <= 0:
            raise ValueError(
                "La cantidad debe ser mayor que cero. Para corregir un registro captura un ajuste con su motivo."
            )
        motivo_limpio = None
    return q, f.isoformat(), motivo_limpio


def cantidad_contratada(concepto: dict) -> Decimal:
    """Volumen contratado del concepto: la meta si ya tiene datos EVM, si no la cantidad."""
    if _concepto_tiene_datos_evm(concepto):
        return to_decimal(concepto["meta_cantidad"])
    return to_decimal(concepto.get("cantidad") or "0")


def _orden_avance(a: dict):
    creado = a.get("creado_en")
    if isinstance(creado, datetime):
        creado = creado.replace(tzinfo=None)
    return (a.get("fecha") or "", creado or datetime.min)


def repartir_avances(avances: List[dict], contratada: Decimal) -> Dict[str, Tuple[Decimal, Decimal]]:
    """Reproduce los avances de UN concepto en orden cronológico y separa cada uno en
    (cantidad dentro de lo contratado, cantidad excedente). Se calcula al leer, no se
    guarda: así nunca se desincroniza si se corrige o se borra un avance."""
    acum = Decimal("0")
    salida: Dict[str, Tuple[Decimal, Decimal]] = {}
    tope = max(contratada, Decimal("0"))
    for a in sorted(avances, key=_orden_avance):
        q = to_decimal(a["cantidad_ejecutada"])
        nuevo = acum + q
        dentro_antes = min(max(acum, Decimal("0")), tope)
        dentro_despues = min(max(nuevo, Decimal("0")), tope)
        dentro = dentro_despues - dentro_antes
        salida[a["id"]] = (dentro, q - dentro)
        acum = nuevo
    return salida


def excedente_de_concepto(ejecutado: Decimal, contratada: Decimal) -> Decimal:
    """Volumen excedente = lo ejecutado por encima de lo contratado (nunca negativo)."""
    return max(ejecutado - max(contratada, Decimal("0")), Decimal("0"))


def ev_de_registro(a: dict, dentro: Decimal) -> Tuple[Decimal, Decimal]:
    """(EV contractual, EV total) de un registro, con su importe congelado."""
    if a.get("importe_ganado_congelado") is None:
        return Decimal("0"), Decimal("0")
    total = to_decimal(a["importe_ganado_congelado"])
    q = to_decimal(a["cantidad_ejecutada"])
    if q == 0:
        return Decimal("0"), total
    return total * dentro / q, total


def calcular_ev(
    avances: List[dict], conceptos_por_id: Dict[str, dict], modo_avance: str,
    desde: Optional[str] = None, hasta: Optional[str] = None,
) -> Tuple[Decimal, Decimal]:
    """(EV contractual, EV total) de los avances con fecha en [desde, hasta].
    El reparto se hace sobre TODO el historial del concepto (no solo la ventana), porque
    un avance es excedente según lo que ya se llevaba acumulado. En modo PORCENTAJE el
    avance reportado es un estado, no un incremento: no se separa (contractual = total)."""
    por_concepto: Dict[str, List[dict]] = {}
    for a in avances:
        por_concepto.setdefault(a["concepto_id"], []).append(a)
    ev_contractual = Decimal("0")
    ev_total = Decimal("0")
    for cid, lista in por_concepto.items():
        reparto = None
        if modo_avance != "PORCENTAJE" and cid in conceptos_por_id:
            reparto = repartir_avances(lista, cantidad_contratada(conceptos_por_id[cid]))
        for a in lista:
            f = a.get("fecha") or ""
            if (desde and f < desde) or (hasta and f > hasta):
                continue
            if reparto is None:
                if a.get("importe_ganado_congelado") is not None:
                    v = to_decimal(a["importe_ganado_congelado"])
                    ev_contractual += v
                    ev_total += v
                continue
            c, t = ev_de_registro(a, reparto[a["id"]][0])
            ev_contractual += c
            ev_total += t
    return ev_contractual, ev_total


def calcular_pronostico(bac: Decimal, ev_acum: Decimal, ac_acum: Decimal) -> Optional[Dict[str, Decimal]]:
    """EAC = BAC ÷ CPI · ETC = EAC − AC · VAC = BAC − EAC, con CPI = EV total ÷ AC.
    None mientras no se pueda calcular (sin gasto real, o sin valor ganado)."""
    if ac_acum <= 0 or ev_acum <= 0:
        return None
    cpi = ev_acum / ac_acum
    eac = bac / cpi
    return {"eac": eac, "etc": eac - ac_acum, "vac": bac - eac}


class ExcedenteOut(BaseModel):
    concepto_id: str
    clave: str
    descripcion: str
    unidad: str
    extraordinario: bool = False
    cantidad_contratada: str
    cantidad_ejecutada: str
    cantidad_excedente: str
    importe_excedente: str
    estatus: str
    referencia: Optional[str] = None
    comentario: Optional[str] = None
    autorizado_por_nombre: Optional[str] = None
    actualizado_en: Optional[datetime] = None


class ExcedentePatch(BaseModel):
    estatus: EstatusAutorizacion
    referencia: Optional[str] = None  # convenio modificatorio u orden de cambio
    comentario: Optional[str] = None


async def _excedentes_del_proyecto(pid: str, project: dict) -> List[ExcedenteOut]:
    modo = (project or {}).get("modo_avance", "CANTIDAD")
    conceptos = await db.conceptos.find({"project_id": pid, "activo": True}).to_list(length=100000)
    avances_por_concepto: Dict[str, List[dict]] = {}
    async for a in db.registros_avance.find({"project_id": pid}):
        avances_por_concepto.setdefault(a["concepto_id"], []).append(a)
    docs_estatus = {d["concepto_id"]: d async for d in db.excedentes_concepto.find({"project_id": pid})}
    salida: List[ExcedenteOut] = []
    for c in conceptos:
        ejecutado = _acumulado_desde_avances(avances_por_concepto.get(c["id"], []), modo)
        importe = _concepto_importe_efectivo(c)
        if modo == "PORCENTAJE":
            exc = max(to_decimal(ejecutado) - Decimal("100"), Decimal("0"))
            imp = importe * exc / Decimal("100")
            contratada = Decimal("100")
        else:
            contratada = cantidad_contratada(c)
            exc = excedente_de_concepto(to_decimal(ejecutado), contratada)
            imp = exc * _concepto_precio_efectivo(c)
        if exc <= 0:
            continue
        ed = docs_estatus.get(c["id"]) or {}
        salida.append(ExcedenteOut(
            concepto_id=c["id"], clave=c["clave"], descripcion=c["descripcion"], unidad=c.get("unidad", ""),
            extraordinario=bool(c.get("extraordinario", False)),
            cantidad_contratada=dec_to_str(contratada), cantidad_ejecutada=ejecutado,
            cantidad_excedente=dec_to_str(exc), importe_excedente=dec_to_str(round_money(imp)),
            estatus=ed.get("estatus") or "pendiente_autorizacion",
            referencia=ed.get("referencia"), comentario=ed.get("comentario"),
            autorizado_por_nombre=ed.get("autorizado_por_nombre"), actualizado_en=ed.get("actualizado_en"),
        ))
    return sort_by_clave(salida, clave_getter=lambda e: e.clave)


@api.get("/projects/{pid}/excedentes", response_model=List[ExcedenteOut])
async def list_excedentes(pid: str, user: dict = Depends(current_user)):
    """Volumen excedente por concepto (ejecutado > contratado) con su estatus de
    autorización. Es informativo: nunca bloquea la captura de avances."""
    project = await ensure_project_access(user, pid)
    return await _excedentes_del_proyecto(pid, project)


@api.patch("/projects/{pid}/excedentes/{concepto_id}", response_model=ExcedenteOut)
async def set_excedente_estatus(
    pid: str, concepto_id: str, body: ExcedentePatch, user: dict = Depends(require_role(ROLE_COORD)),
):
    """Solo el Coordinador General autoriza o rechaza un volumen excedente (vía
    convenio modificatorio u orden de cambio, cuya referencia es obligatoria al
    autorizar). Queda en la bitácora."""
    project = await ensure_project_access(user, pid)
    excedentes = {e.concepto_id: e for e in await _excedentes_del_proyecto(pid, project)}
    actual = excedentes.get(concepto_id)
    if not actual:
        raise HTTPException(404, "Este concepto no tiene volumen excedente")
    referencia = (body.referencia or "").strip() or None
    if body.estatus == "autorizado" and not referencia:
        raise HTTPException(400, "Para autorizar indica el convenio modificatorio u orden de cambio.")
    ahora = datetime.now(timezone.utc)
    await db.excedentes_concepto.update_one(
        {"project_id": pid, "concepto_id": concepto_id},
        {"$set": {
            "estatus": body.estatus, "referencia": referencia,
            "comentario": (body.comentario or "").strip() or None,
            "autorizado_por": user["id"], "autorizado_por_nombre": user.get("name"), "actualizado_en": ahora,
        }, "$setOnInsert": {"id": str(uuid.uuid4())}},
        upsert=True,
    )
    await _log_bitacora(pid, "excedente_estatus", "concepto", concepto_id, "estatus", actual.estatus, body.estatus, user)
    nuevo = {e.concepto_id: e for e in await _excedentes_del_proyecto(pid, project)}
    return nuevo[concepto_id]


class PuExtraordinarioPatch(BaseModel):
    pu_estatus: EstatusAutorizacion
    referencia: Optional[str] = None
    precio_unitario: Optional[str] = None  # al autorizar se puede fijar el P.U. definitivo

    @field_validator("precio_unitario")
    @classmethod
    def _v_pu(cls, v):
        if v is not None and to_decimal(v) <= 0:
            raise ValueError("El precio unitario debe ser mayor que cero")
        return v


@api.patch("/conceptos/{concepto_id}/pu_estatus", response_model=ConceptoOut)
async def set_pu_extraordinario(
    concepto_id: str, body: PuExtraordinarioPatch, user: dict = Depends(require_role(ROLE_COORD)),
):
    """Autoriza o rechaza el P.U. de un concepto EXTRAORDINARIO (trabajo que no está
    en el catálogo). Solo el Coordinador General; la referencia es obligatoria al autorizar."""
    concepto = await db.conceptos.find_one({"id": concepto_id})
    if not concepto:
        raise HTTPException(404, "Concepto no existe")
    await ensure_project_access(user, concepto["project_id"])
    if not concepto.get("extraordinario"):
        raise HTTPException(400, "Solo los conceptos extraordinarios tienen P.U. por autorizar")
    referencia = (body.referencia or "").strip() or None
    if body.pu_estatus == "autorizado" and not referencia:
        raise HTTPException(400, "Para autorizar indica el convenio modificatorio u orden de cambio.")
    upd: dict = {"pu_estatus": body.pu_estatus, "pu_referencia": referencia}
    if body.precio_unitario is not None:
        upd["precio_unitario"] = body.precio_unitario
    await db.conceptos.update_one({"id": concepto_id}, {"$set": upd})
    await _log_bitacora(
        concepto["project_id"], "pu_extraordinario", "concepto", concepto_id,
        "pu_estatus", concepto.get("pu_estatus"), body.pu_estatus, user,
    )
    return await _concepto_out(await db.conceptos.find_one({"id": concepto_id}))


# === C-01 MIGRACIÓN: reubicar conceptos según el prefijo de su clave ===========
# Los catálogos ya importados quedaron PLANOS (todos los conceptos en una partida) porque
# el importador descartaba las filas de partida. Esta migración crea los nodos que faltan
# (nombre = la clave, marcados "nombre pendiente" para renombrarlos: el nombre original
# no se puede recuperar) y mueve cada concepto a su partida por prefijo de clave.
#
# Reglas de seguridad (proyectos reales):
#   · Solo el Coordinador General, UN proyecto a la vez, con vista previa y confirm=true.
#   · Los proyectos "Cablebús Línea 4" quedan EXCLUIDOS: la API se niega a tocarlos.
#   · Idempotente (correrla otra vez no cambia nada) y REVERSIBLE (se guarda el
#     partida_id original de cada concepto). Nunca se borra nada: las partidas creadas se
#     dan de baja (activo=false) al revertir.
def es_proyecto_excluido(nombre: str) -> bool:
    n = _normalize_text(nombre or "")
    return "cablebus" in n or re.search(r"\blinea\s*4\b", n) is not None


def planificar_reubicacion(partidas: List[dict], conceptos: List[dict]) -> Dict[str, Any]:
    """Plan puro (sin DB): nodos por crear y conceptos por mover. Ver el bloque de arriba."""
    por_clave: Dict[str, str] = {p["clave"]: p["id"] for p in partidas if p.get("activo", True) and p.get("clave")}
    creadas: Dict[str, dict] = {}
    orden: List[str] = []
    movimientos: List[dict] = []
    for c in sorted(conceptos, key=lambda x: clave_sort_key(x.get("clave") or "")):
        clave = c.get("clave") or ""
        if "." not in clave or not c.get("activo", True):
            continue
        cadena = list(reversed(ancestros_de_clave(clave)))  # raíz -> hoja: ["1", "1.1"]
        idx = -1
        for i, a in enumerate(cadena):
            if a in por_clave or a in creadas:
                idx = i
        if idx >= 0:
            a = cadena[idx]
            ref = ("id", por_clave[a]) if a in por_clave else ("nuevo", a)
        else:
            ref = ("id", c["partida_id"])  # sin ancestro conocido: se cuelga donde ya estaba
        for a in cadena[idx + 1:]:
            creadas[a] = {"clave": a, "padre": ref}
            orden.append(a)
            ref = ("nuevo", a)
        if ref == ("id", c["partida_id"]):
            continue  # ya está en su lugar (idempotencia)
        movimientos.append({
            "concepto_id": c["id"], "clave": clave, "desde": c["partida_id"], "hacia": ref,
        })
    return {"nodos_a_crear": [creadas[a] for a in orden], "movimientos": movimientos}


async def _plan_reubicacion_de_proyecto(pid: str) -> Dict[str, Any]:
    partidas = await db.partidas.find({"project_id": pid, "activo": True}).to_list(length=100000)
    conceptos = await db.conceptos.find({"project_id": pid, "activo": True}).to_list(length=1000000)
    return planificar_reubicacion(partidas, conceptos)


async def _proyecto_migrable_o_error(pid: str, user: dict) -> dict:
    proyecto = await ensure_project_access(user, pid)
    if es_proyecto_excluido(proyecto.get("name", "")):
        raise HTTPException(403, "Este proyecto está excluido de la migración (Cablebús Línea 4).")
    return proyecto


async def aplicar_reubicacion(pid: str, plan: Dict[str, Any], user: dict) -> Optional[str]:
    """Ejecuta el plan. Registra cada paso ANTES de escribirlo; si algo falla revierte lo hecho."""
    if not plan["nodos_a_crear"] and not plan["movimientos"]:
        return None
    mig_id = str(uuid.uuid4())
    await db.migraciones_catalogo.insert_one({
        "id": mig_id, "project_id": pid, "tipo": "catalogo_jerarquia", "estado": "aplicando",
        "iniciada_en": datetime.now(timezone.utc), "por": user["id"], "por_nombre": user.get("name"),
        "partidas_creadas": [], "movimientos": [],
    })
    ids_nuevos: Dict[str, str] = {}
    try:
        for orden, nodo in enumerate(plan["nodos_a_crear"]):
            tipo_padre, valor = nodo["padre"]
            padre_id = valor if tipo_padre == "id" else ids_nuevos[valor]
            nuevo_id = str(uuid.uuid4())
            await db.migraciones_catalogo.update_one({"id": mig_id}, {"$push": {"partidas_creadas": nuevo_id}})
            await db.partidas.insert_one({
                "id": nuevo_id, "project_id": pid, "clave": nodo["clave"], "nombre": nodo["clave"],
                "nombre_pendiente": True, "orden": orden, "activo": True, "partida_padre_id": padre_id,
                "peso_manual": None, "created_at": datetime.now(timezone.utc), "created_by": user["id"],
                "migracion_id": mig_id,
            })
            ids_nuevos[nodo["clave"]] = nuevo_id
        for mov in plan["movimientos"]:
            tipo_dest, valor = mov["hacia"]
            destino_id = valor if tipo_dest == "id" else ids_nuevos[valor]
            await db.migraciones_catalogo.update_one(
                {"id": mig_id},
                {"$push": {"movimientos": {"concepto_id": mov["concepto_id"], "desde": mov["desde"], "hacia": destino_id}}},
            )
            await db.conceptos.update_one({"id": mov["concepto_id"]}, {"$set": {"partida_id": destino_id}})
    except Exception as e:  # noqa: BLE001
        log.error("[migracion_catalogo] falló, revirtiendo %s: %s", mig_id, e)
        await revertir_migracion(mig_id, user)
        raise HTTPException(500, f"La migración falló y se revirtió automáticamente: {e}")
    await db.migraciones_catalogo.update_one(
        {"id": mig_id}, {"$set": {"estado": "aplicada", "aplicada_en": datetime.now(timezone.utc)}},
    )
    await _log_bitacora(
        pid, "migracion_catalogo", "proyecto", pid, None, None,
        f"{len(plan['nodos_a_crear'])} partidas creadas, {len(plan['movimientos'])} conceptos reubicados (migración {mig_id})", user,
    )
    return mig_id


async def revertir_migracion(mig_id: str, user: dict) -> Dict[str, int]:
    """Devuelve cada concepto a su partida original y da de baja (activo=false) las partidas creadas.
    Un concepto que alguien ya movió después no se toca. Idempotente."""
    mig = await db.migraciones_catalogo.find_one({"id": mig_id})
    if not mig:
        raise HTTPException(404, "Migración no existe")
    restaurados = 0
    for mov in reversed(mig.get("movimientos") or []):
        c = await db.conceptos.find_one({"id": mov["concepto_id"]})
        if c and c.get("partida_id") == mov["hacia"]:
            await db.conceptos.update_one({"id": mov["concepto_id"]}, {"$set": {"partida_id": mov["desde"]}})
            restaurados += 1
    dadas_de_baja = 0
    for pid_nueva in mig.get("partidas_creadas") or []:
        restantes = await db.conceptos.count_documents({"partida_id": pid_nueva, "activo": True})
        if restantes == 0:
            await db.partidas.update_one({"id": pid_nueva}, {"$set": {"activo": False}})
            dadas_de_baja += 1
    await db.migraciones_catalogo.update_one(
        {"id": mig_id},
        {"$set": {"estado": "revertida", "revertida_en": datetime.now(timezone.utc), "revertida_por": user["id"]}},
    )
    return {"conceptos_restaurados": restaurados, "partidas_dadas_de_baja": dadas_de_baja}


class MigracionConfirmIn(BaseModel):
    confirm: bool = False
    migracion_id: Optional[str] = None


@api.get("/admin/migraciones/catalogo-jerarquia")
async def listar_migracion_catalogo(user: dict = Depends(require_role(ROLE_COORD))):
    """Proyectos con cuántas partidas se crearían y cuántos conceptos se moverían. Solo lectura."""
    salida = []
    async for p in db.projects.find({"archived": {"$ne": True}}, {"id": 1, "name": 1}):
        excluido = es_proyecto_excluido(p.get("name", ""))
        item = {
            "project_id": p["id"], "nombre": p.get("name", ""), "excluido": excluido,
            "partidas_a_crear": 0, "conceptos_a_mover": 0, "ultima_migracion": None,
        }
        if not excluido:
            plan = await _plan_reubicacion_de_proyecto(p["id"])
            item["partidas_a_crear"] = len(plan["nodos_a_crear"])
            item["conceptos_a_mover"] = len(plan["movimientos"])
        ult = await db.migraciones_catalogo.find(
            {"project_id": p["id"], "tipo": "catalogo_jerarquia"}, {"_id": 0, "id": 1, "estado": 1, "aplicada_en": 1, "revertida_en": 1},
        ).sort("iniciada_en", -1).to_list(length=1)
        item["ultima_migracion"] = ult[0] if ult else None
        salida.append(item)
    salida.sort(key=lambda x: (x["excluido"], x["nombre"].lower()))
    return salida


@api.get("/admin/migraciones/catalogo-jerarquia/{pid}/vista-previa")
async def vista_previa_migracion_catalogo(pid: str, user: dict = Depends(require_role(ROLE_COORD))):
    """Qué haría la migración en este proyecto (no escribe nada)."""
    await _proyecto_migrable_o_error(pid, user)
    plan = await _plan_reubicacion_de_proyecto(pid)
    return {
        "project_id": pid,
        "partidas_a_crear": [{"clave": n["clave"], "padre": n["padre"][1] if n["padre"][0] == "nuevo" else None} for n in plan["nodos_a_crear"]],
        "conceptos_a_mover": len(plan["movimientos"]),
        "muestra_movimientos": [
            {"clave": m["clave"], "hacia": m["hacia"][1] if m["hacia"][0] == "nuevo" else "(partida existente)"}
            for m in plan["movimientos"][:200]
        ],
        "nota": "Las partidas nuevas se llaman igual que su clave y quedan marcadas «nombre pendiente» para que las renombres.",
    }


@api.post("/admin/migraciones/catalogo-jerarquia/{pid}/aplicar")
async def aplicar_migracion_catalogo(pid: str, body: MigracionConfirmIn, user: dict = Depends(require_role(ROLE_COORD))):
    if not body.confirm:
        raise HTTPException(400, "Falta confirmar la migración de este proyecto (confirm=true).")
    await _proyecto_migrable_o_error(pid, user)
    plan = await _plan_reubicacion_de_proyecto(pid)
    mig_id = await aplicar_reubicacion(pid, plan, user)
    return {
        "ok": True, "migracion_id": mig_id, "sin_cambios": mig_id is None,
        "partidas_creadas": len(plan["nodos_a_crear"]), "conceptos_reubicados": len(plan["movimientos"]),
    }


@api.post("/admin/migraciones/catalogo-jerarquia/{pid}/revertir")
async def revertir_migracion_catalogo(pid: str, body: MigracionConfirmIn, user: dict = Depends(require_role(ROLE_COORD))):
    if not body.confirm:
        raise HTTPException(400, "Falta confirmar la reversa (confirm=true).")
    await _proyecto_migrable_o_error(pid, user)
    filtro: Dict[str, Any] = {"project_id": pid, "tipo": "catalogo_jerarquia", "estado": "aplicada"}
    if body.migracion_id:
        filtro["id"] = body.migracion_id
    ult = await db.migraciones_catalogo.find(filtro).sort("iniciada_en", -1).to_list(length=1)
    if not ult:
        raise HTTPException(404, "No hay una migración aplicada para revertir en este proyecto.")
    r = await revertir_migracion(ult[0]["id"], user)
    return {"ok": True, "migracion_id": ult[0]["id"], **r}


# === Etapa EVM: Análisis de Periodos (Valor Ganado) ==========================
def _fechas_programa_concepto(concepto: dict) -> Optional["tuple[date, date]"]:
    """(inicio, fin) del programa lineal de un concepto, o None si no tiene datos EVM,
    le faltan fechas, son ilegibles o el fin es anterior al inicio (rango invertido:
    no aporta PV ni curva; el Importador Maestro y el PATCH ya lo rechazan al capturar)."""
    if not _concepto_tiene_datos_evm(concepto) or not concepto.get("fecha_inicio") or not concepto.get("fecha_fin"):
        return None
    try:
        c_ini = date.fromisoformat(concepto["fecha_inicio"])
        c_fin = date.fromisoformat(concepto["fecha_fin"])
    except (TypeError, ValueError):
        return None
    if c_fin < c_ini:
        return None
    return c_ini, c_fin


def _prorrateo_concepto_en_ventana(concepto: dict, ventana_ini: date, ventana_fin: date) -> Decimal:
    """PV que aporta UN concepto a la ventana consultada.

    Fracción de días EXACTA con Decimal (nunca float): un concepto puede
    durar varios años, y el margen de error de un float sí se nota al sumar
    miles de conceptos. Devuelve 0 si el concepto no tiene datos EVM
    todavía (ver _concepto_tiene_datos_evm) o no intersecta la ventana —
    nunca lanza, un concepto sin migrar simplemente no aporta PV."""
    fechas = _fechas_programa_concepto(concepto)
    if fechas is None:
        return Decimal("0")
    c_ini, c_fin = fechas

    overlap_ini = max(c_ini, ventana_ini)
    overlap_fin = min(c_fin, ventana_fin)
    if overlap_ini > overlap_fin:
        return Decimal("0")

    dias_en_ventana = (overlap_fin - overlap_ini).days + 1  # inclusivo
    dias_totales = (c_fin - c_ini).days + 1
    fraccion = Decimal(dias_en_ventana) / Decimal(dias_totales)
    return fraccion * to_decimal(concepto["importe_total_editable"])
    # No se redondea aquí — el redondeo a 2 decimales se hace UNA sola vez,
    # sobre el total ya sumado, en el endpoint. Redondear por concepto y
    # luego sumar miles de redondeos es justo el tipo de acumulación de
    # error que to_decimal/round_money existen para evitar.


def _rango_meses(c_ini: date, c_fin: date) -> List["tuple[date, date]"]:
    """[(inicio_mes, fin_mes), ...] recortados a [c_ini, c_fin] — un par por
    cada mes calendario que el concepto toca, el primero y el último
    recortados a las fechas reales del concepto (no al 1 y al 30/31)."""
    meses = []
    cursor = date(c_ini.year, c_ini.month, 1)
    while cursor <= c_fin:
        if cursor.month == 12:
            siguiente = date(cursor.year + 1, 1, 1)
        else:
            siguiente = date(cursor.year, cursor.month + 1, 1)
        mes_ini = max(cursor, c_ini)
        mes_fin = min(siguiente - timedelta(days=1), c_fin)
        meses.append((mes_ini, mes_fin))
        cursor = siguiente
    return meses


def _curva_mensual_concepto(concepto: dict) -> List[dict]:
    """Reparte importe_total_editable en un valor por mes calendario dentro
    de [fecha_inicio, fecha_fin] — para la Curva S del dashboard (Tarea 4).

    A diferencia de _prorrateo_concepto_en_ventana (una sola fracción sobre
    una ventana), aquí SÍ hay que garantizar que la suma de todos los meses
    sea EXACTAMENTE importe_total_editable: cualquier residuo de la
    división se asigna al ÚLTIMO mes, nunca se pierde ni se reparte
    disperso (reparto de centavos estándar)."""
    fechas = _fechas_programa_concepto(concepto)
    if fechas is None:
        return []
    c_ini, c_fin = fechas
    dias_totales = (c_fin - c_ini).days + 1
    importe = to_decimal(concepto["importe_total_editable"])

    meses = _rango_meses(c_ini, c_fin)
    resultado = []
    acumulado = Decimal("0")
    for i, (mes_ini, mes_fin) in enumerate(meses):
        if i == len(meses) - 1:
            valor_mes = importe - acumulado  # último mes se lleva el residuo exacto
        else:
            dias_mes = (mes_fin - mes_ini).days + 1
            valor_mes = importe * Decimal(dias_mes) / Decimal(dias_totales)
            acumulado += valor_mes
        resultado.append({"mes": mes_ini.strftime("%Y-%m"), "valor": dec_to_str(valor_mes)})
    return resultado


# --- A-06: curva planeada del Programa desglosado (versión vigente) ---------
# Si un concepto tiene distribución mensual en la versión VIGENTE del programa, esa
# curva es su plan (PV y Curva S); si no, se prorratea linealmente entre fecha_inicio
# y fecha_fin como antes. Un concepto sin ninguna de las dos no tiene programa.
def _meses_de_distribucion(dist: Optional[dict]) -> List["tuple[date, date, Decimal]"]:
    salida = []
    for m in (dist or {}).get("meses") or []:
        try:
            ini = date.fromisoformat(m.get("fecha_inicio") or "")
            fin = date.fromisoformat(m.get("fecha_fin") or "")
        except (TypeError, ValueError):
            continue
        if fin < ini:
            continue
        salida.append((ini, fin, to_decimal(m.get("importe") or "0")))
    return salida


def _prorrateo_distribucion_en_ventana(dist: Optional[dict], ventana_ini: date, ventana_fin: date) -> Decimal:
    total = Decimal("0")
    for ini, fin, importe in _meses_de_distribucion(dist):
        ov_ini, ov_fin = max(ini, ventana_ini), min(fin, ventana_fin)
        if ov_ini > ov_fin:
            continue
        total += importe * Decimal((ov_fin - ov_ini).days + 1) / Decimal((fin - ini).days + 1)
    return total


def _curva_mensual_distribucion(dist: Optional[dict]) -> List[dict]:
    """Valor planeado por mes calendario de una distribución (cada columna del programa
    puede cruzar meses: se reparte por días y el residuo exacto va al último tramo)."""
    por_mes: Dict[str, Decimal] = {}
    for ini, fin, importe in _meses_de_distribucion(dist):
        dias_totales = (fin - ini).days + 1
        tramos = _rango_meses(ini, fin)
        acumulado = Decimal("0")
        for i, (t_ini, t_fin) in enumerate(tramos):
            if i == len(tramos) - 1:
                valor = importe - acumulado
            else:
                valor = importe * Decimal((t_fin - t_ini).days + 1) / Decimal(dias_totales)
                acumulado += valor
            clave = t_ini.strftime("%Y-%m")
            por_mes[clave] = por_mes.get(clave, Decimal("0")) + valor
    return [{"mes": m, "valor": dec_to_str(v)} for m, v in sorted(por_mes.items())]


def _pv_de_concepto(concepto: dict, dist: Optional[dict], ventana_ini: date, ventana_fin: date) -> Decimal:
    if _meses_de_distribucion(dist):
        return _prorrateo_distribucion_en_ventana(dist, ventana_ini, ventana_fin)
    return _prorrateo_concepto_en_ventana(concepto, ventana_ini, ventana_fin)


def _curva_planeada_concepto(concepto: dict, dist: Optional[dict]) -> List[dict]:
    if _meses_de_distribucion(dist):
        return _curva_mensual_distribucion(dist)
    return _curva_mensual_concepto(concepto)


def _concepto_tiene_programa(concepto: dict, dist: Optional[dict]) -> bool:
    return bool(_meses_de_distribucion(dist)) or _fechas_programa_concepto(concepto) is not None


async def _distribuciones_vigentes(pid: str) -> Dict[str, dict]:
    """concepto_id -> distribución de la versión VIGENTE del programa (vacío si no hay)."""
    versiones = await db.programa_versiones.find({"project_id": pid, "vigente": True}).to_list(length=100)
    if not versiones:
        return {}
    docs = await db.programa_distribucion.find(
        {"programa_version_id": {"$in": [v["id"] for v in versiones]}}
    ).to_list(length=100000)
    return {d["concepto_id"]: d for d in docs if d.get("concepto_id")}


class AnalisisPeriodoOut(BaseModel):
    project_id: str
    start: str
    end: str
    pv: str  # Valor Planeado
    ev: str  # Valor Ganado TOTAL (alias de ev_total: compatibilidad con clientes viejos)
    ac: str  # Costo Real
    spi: Optional[str] = None  # EV contractual / PV — Schedule Performance Index
    cpi: Optional[str] = None  # EV total / AC — Cost Performance Index
    variacion_cronograma: str  # EV contractual - PV
    variacion_costo: Optional[str] = None  # EV total - AC (None mientras AC = 0: A-04)
    # --- A-02: dos cifras de valor ganado + pronóstico de costo -----------
    ev_contractual: str = "0.00"  # topado al volumen contratado
    ev_total: str = "0.00"        # incluye el volumen excedente
    bac: str = "0.00"             # presupuesto contratado
    ev_acumulado: str = "0.00"    # EV total del proyecto a la fecha de corte
    ac_acumulado: str = "0.00"    # AC del proyecto a la fecha de corte
    eac: Optional[str] = None     # BAC / CPI  (None mientras AC = 0)
    etc: Optional[str] = None     # EAC - AC
    vac: Optional[str] = None     # BAC - EAC (negativo = sobrecosto proyectado)
    # A-06: conceptos activos sin fechas ni distribución en el programa (no aportan PV).
    conceptos_sin_programa: int = 0


async def calcular_analisis_evm(pid: str, start: str, end: str, project: Optional[dict] = None) -> Dict[str, Any]:
    """ÚNICO servicio de análisis EVM. Lo usan el tablero (`analisis_periodo`) y la
    Presentación (sección Financiero), así ambos muestran lo mismo para el mismo periodo.
    Devuelve Decimales sin redondear; quien lo muestra redondea."""
    ventana_ini, ventana_fin = date.fromisoformat(start), date.fromisoformat(end)
    if ventana_fin < ventana_ini:
        raise ValueError("end no puede ser anterior a start")
    if project is None:
        project = await db.projects.find_one({"id": pid}) or {}
    modo = project.get("modo_avance", "CANTIDAD")
    conceptos = await db.conceptos.find({"project_id": pid, "activo": True}).to_list(length=100000)
    conceptos_por_id = {c["id"]: c for c in conceptos}
    distribuciones = await _distribuciones_vigentes(pid)
    pv = sum(
        (_pv_de_concepto(c, distribuciones.get(c["id"]), ventana_ini, ventana_fin) for c in conceptos),
        start=Decimal("0"),
    )
    sin_programa = sum(1 for c in conceptos if not _concepto_tiene_programa(c, distribuciones.get(c["id"])))
    avances = await db.registros_avance.find({"project_id": pid}).to_list(length=1000000)
    ev_contractual, ev_total = calcular_ev(avances, conceptos_por_id, modo, start, end)
    _, ev_acum = calcular_ev(avances, conceptos_por_id, modo, None, end)
    ac = Decimal("0")
    ac_acum = Decimal("0")
    async for g in db.gastos_reales.find({"project_id": pid, "fecha": {"$lte": end}}):
        m = to_decimal(g["monto"])
        ac_acum += m
        if g["fecha"] >= start:
            ac += m
    bac = sum((_concepto_importe_efectivo(c) for c in conceptos), start=Decimal("0"))
    cuatro = Decimal("0.0001")
    spi = (ev_contractual / pv).quantize(cuatro, rounding=ROUND_HALF_UP) if pv != 0 else None
    cpi = (ev_total / ac).quantize(cuatro, rounding=ROUND_HALF_UP) if ac != 0 else None
    return {
        "pv": pv, "ev_contractual": ev_contractual, "ev_total": ev_total, "ac": ac,
        "spi": spi, "cpi": cpi,
        "variacion_cronograma": ev_contractual - pv,
        # A-04: sin gasto real en el periodo el CV no significa nada (saldría el EV completo).
        "variacion_costo": (ev_total - ac) if ac != 0 else None,
        "bac": bac, "ev_acumulado": ev_acum, "ac_acumulado": ac_acum,
        "pronostico": calcular_pronostico(bac, ev_acum, ac_acum),
        "conceptos_sin_programa": sin_programa,
    }


# --- A-05: periodos del análisis financiero (tablero EVM y Presentación) --------------
PERIODOS_FINANCIEROS = ("mes_actual", "ultimos_3_meses", "proyecto_completo")
PERIODO_FINANCIERO_DEFECTO = "mes_actual"


def resolver_rango_periodo(periodo: Optional[str], hasta: date, primer_mes: Optional[str] = None) -> Tuple[str, str]:
    """ÚNICA función que traduce un periodo financiero a (inicio, fin) ISO. La usan el tablero
    EVM (con `hasta` = hoy en la zona del proyecto) y la Presentación (con `hasta` = su fecha),
    así ambos miden exactamente la misma ventana.

    - mes_actual: del día 1 del mes de `hasta` a `hasta`.
    - ultimos_3_meses: del día 1 de hace 3 meses a `hasta`.
    - proyecto_completo: del primer mes con datos ("YYYY-MM") a `hasta`; sin datos, del 1 de enero.
    """
    periodo = periodo or PERIODO_FINANCIERO_DEFECTO
    if periodo not in PERIODOS_FINANCIEROS:
        raise ValueError(f"periodo debe ser uno de: {', '.join(PERIODOS_FINANCIEROS)}")
    if periodo == "mes_actual":
        inicio = hasta.replace(day=1)
    elif periodo == "ultimos_3_meses":
        mes_abs = hasta.year * 12 + (hasta.month - 1) - 3
        inicio = date(mes_abs // 12, mes_abs % 12 + 1, 1)
    else:
        inicio = date.fromisoformat(f"{primer_mes}-01") if primer_mes else date(hasta.year, 1, 1)
    if inicio > hasta:  # proyecto que arranca después de la fecha de corte
        inicio = hasta
    return inicio.isoformat(), hasta.isoformat()


async def rango_financiero(pid: str, periodo: Optional[str], hasta: date) -> Tuple[str, str]:
    """`resolver_rango_periodo` con el primer mes con datos del proyecto cuando hace falta."""
    primer_mes = None
    if (periodo or PERIODO_FINANCIERO_DEFECTO) == "proyecto_completo":
        planeado, ganado, real = await _curva_s_por_mes(pid)
        meses = sorted(set(planeado) | set(ganado) | set(real))
        primer_mes = meses[0] if meses else None
    return resolver_rango_periodo(periodo, hasta, primer_mes)


def cifras_analisis(r: Dict[str, Any]) -> Dict[str, Any]:
    """Cifras del análisis EVM ya redondeadas (Decimal; None si no aplica). Única traducción
    de `calcular_analisis_evm` a lo que se muestra: el tablero (JSON) y la Presentación
    (PPTX / vista previa) parten de aquí, así no pueden diferir."""
    pron = r["pronostico"]
    return {
        "pv": round_money(r["pv"]), "ev": round_money(r["ev_total"]),
        "ev_contractual": round_money(r["ev_contractual"]), "ev_total": round_money(r["ev_total"]),
        "ac": round_money(r["ac"]), "spi": r["spi"], "cpi": r["cpi"],
        "variacion_cronograma": round_money(r["variacion_cronograma"]),
        "variacion_costo": round_money(r["variacion_costo"]) if r["variacion_costo"] is not None else None,
        "bac": round_money(r["bac"]),
        "ev_acumulado": round_money(r["ev_acumulado"]), "ac_acumulado": round_money(r["ac_acumulado"]),
        "eac": round_money(pron["eac"]) if pron else None,
        "etc": round_money(pron["etc"]) if pron else None,
        "vac": round_money(pron["vac"]) if pron else None,
        "conceptos_sin_programa": r["conceptos_sin_programa"],
    }


async def datos_financieros_presentacion(pid: str, pres: dict, project: Optional[dict] = None) -> Dict[str, Any]:
    """Sección Financiero de una Presentación: mismo servicio (`calcular_analisis_evm`) y mismo
    periodo que el tablero. Devuelve {periodo, start, end, cifras}. Lanza si no se puede calcular."""
    if project is None:
        project = await db.projects.find_one({"id": pid}) or {}
    periodo = pres.get("periodo_financiero") or PERIODO_FINANCIERO_DEFECTO
    if periodo not in PERIODOS_FINANCIEROS:
        periodo = PERIODO_FINANCIERO_DEFECTO
    start, end = await rango_financiero(pid, periodo, date.fromisoformat(pres["fecha"]))
    r = await calcular_analisis_evm(pid, start, end, project)
    return {"periodo": periodo, "start": start, "end": end, "cifras": cifras_analisis(r)}


class ExcepcionEvmOut(BaseModel):
    concepto_id: str
    clave: str
    descripcion: str
    tipo: Literal[
        "fuera_de_ventana", "atrasado", "excedente_volumen", "sobrecosto",
        "ajuste_negativo", "acuerdo_vencido", "sin_avance_en_ventana",
    ]
    detalle: str
    # A-02/A-03: excedentes, sobrecosto, ajustes negativos, acuerdos vencidos y conceptos
    # sin avance son alertas INFORMATIVAS (nunca bloquean); llevan cantidad e importe
    # cuando aplican.
    severidad: Literal["alerta", "informativa"] = "alerta"
    cantidad: Optional[str] = None
    importe: Optional[str] = None
    # Solo `acuerdo_vencido`: días de atraso y responsable del acuerdo.
    dias_atraso: Optional[int] = None
    responsable: Optional[str] = None


class CurvaSOut(BaseModel):
    meses: List[str]
    planeado_acumulado: List[str]
    ganado_acumulado: List[str]
    real_acumulado: List[str]


@api.get("/projects/{pid}/analisis_periodo", response_model=AnalisisPeriodoOut)
async def analisis_periodo(
    pid: str,
    start: Optional[str] = None,
    end: Optional[str] = None,
    periodo: Optional[str] = None,
    fecha: Optional[str] = None,
    user: dict = Depends(current_user),
):
    """Motor EVM: PV analítico (nunca se guarda un prorrateo día por día en
    Mongo, ver _prorrateo_concepto_en_ventana), EV desde lo ya CONGELADO en
    cada RegistroAvance (nunca se recalcula con el precio de hoy — ver
    create_avance), AC desde gastos_reales (captura manual de
    administración).

    La ventana se da como `start`+`end`, o como `periodo` (mes_actual | ultimos_3_meses |
    proyecto_completo) con `fecha` de corte opcional (por defecto, hoy en la zona del proyecto):
    es el mismo cálculo de rango que usa la Presentación (A-05)."""
    project = await ensure_project_access(user, pid)
    try:
        if periodo:
            hasta = date.fromisoformat(fecha) if fecha else hoy_proyecto(project)
            start, end = await rango_financiero(pid, periodo, hasta)
        elif start and end:
            date.fromisoformat(start), date.fromisoformat(end)
        else:
            raise HTTPException(400, "Indica start y end, o un periodo")
    except ValueError as e:
        raise HTTPException(400, str(e) if "periodo" in str(e) else "start/end/fecha deben ser YYYY-MM-DD")
    try:
        r = await calcular_analisis_evm(pid, start, end, project)
    except ValueError:
        raise HTTPException(400, "end no puede ser anterior a start")
    c = cifras_analisis(r)

    def _s(v):
        return dec_to_str(v) if v is not None else None

    return AnalisisPeriodoOut(
        project_id=pid, start=start, end=end,
        pv=_s(c["pv"]), ev=_s(c["ev"]), ac=_s(c["ac"]),
        spi=_s(c["spi"]), cpi=_s(c["cpi"]),
        variacion_cronograma=_s(c["variacion_cronograma"]),
        variacion_costo=_s(c["variacion_costo"]),
        ev_contractual=_s(c["ev_contractual"]), ev_total=_s(c["ev_total"]),
        bac=_s(c["bac"]),
        ev_acumulado=_s(c["ev_acumulado"]), ac_acumulado=_s(c["ac_acumulado"]),
        eac=_s(c["eac"]), etc=_s(c["etc"]), vac=_s(c["vac"]),
        conceptos_sin_programa=c["conceptos_sin_programa"],
    )


@api.get("/projects/{pid}/analisis_periodo/presupuesto_total")
async def analisis_periodo_presupuesto_total(pid: str, user: dict = Depends(current_user)):
    """Presupuesto total del proyecto (suma del importe efectivo de todos
    los conceptos activos) — NO depende de start/end como AnalisisPeriodoOut,
    por eso vive en su propio endpoint en vez de sumarse a ese modelo.
    Usa `_concepto_importe_efectivo` (fuente única de verdad para dinero de
    un Concepto, ver nota junto a esa función) para que conceptos legado
    (cantidad×precio_unitario) y conceptos EVM (importe_total_editable)
    sumen correctamente por igual — sumar importe_total_editable a secas
    dejaría en $0 cualquier concepto que no haya migrado a Etapa EVM."""
    await ensure_project_access(user, pid)
    conceptos = await db.conceptos.find({"project_id": pid, "activo": True}).to_list(length=100000)
    total = sum((_concepto_importe_efectivo(c) for c in conceptos), start=Decimal("0"))
    return {"project_id": pid, "presupuesto_total": dec_to_str(round_money(total))}


async def _curva_s_por_mes(pid: str) -> Tuple[Dict[str, Decimal], Dict[str, Decimal], Dict[str, Decimal]]:
    """Valor planeado, ganado y real de cada mes ("YYYY-MM") del proyecto. Lo usan la Curva S
    y el periodo "proyecto completo" (que arranca en el primer mes con datos)."""
    conceptos = await db.conceptos.find({"project_id": pid, "activo": True}).to_list(length=100000)

    distribuciones = await _distribuciones_vigentes(pid)
    planeado_por_mes: Dict[str, Decimal] = {}
    for c in conceptos:
        for punto in _curva_planeada_concepto(c, distribuciones.get(c["id"])):
            planeado_por_mes[punto["mes"]] = planeado_por_mes.get(punto["mes"], Decimal("0")) + to_decimal(punto["valor"])

    ganado_por_mes: Dict[str, Decimal] = {}
    async for a in db.registros_avance.find({"project_id": pid}):
        if a.get("importe_ganado_congelado") is None or not a.get("fecha"):
            continue
        mes = a["fecha"][:7]  # "YYYY-MM-DD" -> "YYYY-MM"
        ganado_por_mes[mes] = ganado_por_mes.get(mes, Decimal("0")) + to_decimal(a["importe_ganado_congelado"])

    real_por_mes: Dict[str, Decimal] = {}
    async for g in db.gastos_reales.find({"project_id": pid}):
        mes = g["fecha"][:7]
        real_por_mes[mes] = real_por_mes.get(mes, Decimal("0")) + to_decimal(g["monto"])
    return planeado_por_mes, ganado_por_mes, real_por_mes


@api.get("/projects/{pid}/analisis_periodo/curva_s", response_model=CurvaSOut)
async def analisis_periodo_curva_s(pid: str, user: dict = Depends(current_user)):
    """Curva S completa del proyecto (todos los meses que tocan sus
    conceptos EVM), para el gráfico de 3 líneas del dashboard — no depende
    de start/end porque la curva se ve completa, la ventana de
    start/end es solo para las tarjetas de analisis_periodo."""
    await ensure_project_access(user, pid)
    planeado_por_mes, ganado_por_mes, real_por_mes = await _curva_s_por_mes(pid)

    todos_los_meses = sorted(set(planeado_por_mes) | set(ganado_por_mes) | set(real_por_mes))
    planeado_acum, ganado_acum, real_acum = Decimal("0"), Decimal("0"), Decimal("0")
    planeado_serie, ganado_serie, real_serie = [], [], []
    for mes in todos_los_meses:
        planeado_acum += planeado_por_mes.get(mes, Decimal("0"))
        ganado_acum += ganado_por_mes.get(mes, Decimal("0"))
        real_acum += real_por_mes.get(mes, Decimal("0"))
        planeado_serie.append(dec_to_str(round_money(planeado_acum)))
        ganado_serie.append(dec_to_str(round_money(ganado_acum)))
        real_serie.append(dec_to_str(round_money(real_acum)))

    return CurvaSOut(meses=todos_los_meses, planeado_acumulado=planeado_serie, ganado_acumulado=ganado_serie, real_acumulado=real_serie)


# --- A-03: excepciones informativas nuevas (funciones puras, sin DB) --------
# Precedencia entre `atrasado` y `sin_avance_en_ventana`: `atrasado` (fecha_fin ya pasó y
# no se alcanzó la meta) gana; un concepto que ya salió como atrasado NO se repite como
# "sin avance en su ventana", aunque la distribución mensual del programa se extienda
# más allá de su fecha_fin.
def _ventana_programa_concepto(concepto: dict, dist: Optional[dict]) -> Optional["tuple[date, date]"]:
    """Ventana (inicio, fin) del programa de un concepto: de la distribución mensual vigente
    si la tiene (primer día del primer mes al último del último), si no fecha_inicio/fecha_fin."""
    meses = _meses_de_distribucion(dist)
    if meses:
        return min(m[0] for m in meses), max(m[1] for m in meses)
    return _fechas_programa_concepto(concepto)


def excepciones_ajustes_negativos(conceptos_por_id: Dict[str, dict], registros: List[dict]) -> List[ExcepcionEvmOut]:
    """Un renglón por concepto con ajustes NEGATIVOS (correcciones que restan avance): cuántos,
    cuánto restan (cantidad) y su valor (cantidad × precio efectivo). Informativo."""
    por_concepto: Dict[str, List[dict]] = {}
    for a in registros:
        if a.get("tipo") != "ajuste" or a.get("concepto_id") not in conceptos_por_id:
            continue
        try:
            if to_decimal(a.get("cantidad_ejecutada") or "0") >= 0:
                continue
        except (ValueError, TypeError, InvalidOperation):
            continue
        por_concepto.setdefault(a["concepto_id"], []).append(a)
    salida: List[ExcepcionEvmOut] = []
    for cid, lista in por_concepto.items():
        c = conceptos_por_id[cid]
        resta = -sum((to_decimal(a["cantidad_ejecutada"]) for a in lista), start=Decimal("0"))
        importe = resta * _concepto_precio_efectivo(c)
        ultimo = max(lista, key=lambda a: (a.get("fecha") or "", a.get("creado_en") or datetime.min))
        motivo = (ultimo.get("motivo") or "").strip()
        n = len(lista)
        detalle = (
            f"{n} ajuste{'s' if n != 1 else ''} negativo{'s' if n != 1 else ''}: restan "
            f"{dec_to_str(resta)} {c.get('unidad', '')} (${dec_to_str(round_money(importe))})."
        ).replace("  ", " ")
        if motivo:
            detalle += f" Último motivo: {motivo}"
        salida.append(ExcepcionEvmOut(
            concepto_id=cid, clave=c["clave"], descripcion=c["descripcion"], tipo="ajuste_negativo",
            severidad="informativa", cantidad=dec_to_str(resta), importe=dec_to_str(round_money(importe)),
            detalle=detalle,
        ))
    return salida


def excepciones_acuerdos_vencidos(minutas: List[dict], hoy: date) -> List[ExcepcionEvmOut]:
    """Acuerdos de minutas NO cumplidos cuya fecha límite ya pasó (estrictamente anterior a
    `hoy` del proyecto: el día límite todavía no está vencido). Del más atrasado al menos."""
    filas: List[tuple] = []
    for m in minutas:
        for a in (m.get("acuerdos") or []):
            if a.get("estado"):
                continue
            try:
                limite = date.fromisoformat(str(a.get("fecha_limite") or "")[:10])
            except ValueError:
                continue
            if limite >= hoy:
                continue
            filas.append(((hoy - limite).days, limite, m, a))
    filas.sort(key=lambda f: (-f[0], str(f[2].get("titulo") or "")))
    salida: List[ExcepcionEvmOut] = []
    for dias, limite, m, a in filas:
        responsable = (a.get("responsable_name") or "").strip() or None
        titulo = (m.get("titulo") or "").strip()
        detalle = f"Vencido hace {dias} día{'s' if dias != 1 else ''} (límite {limite.isoformat()})."
        if responsable:
            detalle += f" Responsable: {responsable}."
        if titulo:
            detalle += f" Minuta: {titulo}."
        salida.append(ExcepcionEvmOut(
            concepto_id="", clave="", descripcion=((a.get("descripcion") or "").strip() or "(sin descripción)")[:160],
            tipo="acuerdo_vencido", severidad="informativa", detalle=detalle,
            dias_atraso=dias, responsable=responsable,
        ))
    return salida


def excepciones_sin_avance_en_ventana(
    conceptos: List[dict], distribuciones: Dict[str, dict], avances_por_concepto: Dict[str, List[dict]],
    hoy: date, excluir_ids: set,
) -> List[ExcepcionEvmOut]:
    """Conceptos cuya ventana del programa incluye HOY, ya empezaron y no tienen NINGÚN avance
    (cantidad > 0) dentro de esa ventana. `importe` = valor planeado que debió ejecutarse a la fecha."""
    salida: List[ExcepcionEvmOut] = []
    for c in conceptos:
        if c["id"] in excluir_ids:
            continue
        dist = distribuciones.get(c["id"])
        ventana = _ventana_programa_concepto(c, dist)
        if ventana is None:
            continue
        ini, fin = ventana
        if not (ini <= hoy <= fin):
            continue
        hay_avance = False
        for a in avances_por_concepto.get(c["id"], []):
            try:
                if not (ini.isoformat() <= str(a.get("fecha") or "") <= fin.isoformat()):
                    continue
                if to_decimal(a.get("cantidad_ejecutada") or "0") > 0:
                    hay_avance = True
                    break
            except (ValueError, TypeError, InvalidOperation):
                continue
        if hay_avance:
            continue
        dias = (hoy - ini).days
        planeado = _pv_de_concepto(c, dist, ini, hoy)
        detalle = (
            f"Su ventana del programa ({ini.isoformat()} — {fin.isoformat()}) ya empezó hace "
            f"{dias} día{'s' if dias != 1 else ''} y no tiene ningún avance capturado."
        )
        salida.append(ExcepcionEvmOut(
            concepto_id=c["id"], clave=c["clave"], descripcion=c["descripcion"], tipo="sin_avance_en_ventana",
            severidad="informativa", detalle=detalle,
            importe=dec_to_str(round_money(planeado)) if planeado > 0 else None,
        ))
    return salida


def _bac_y_ac(conceptos: List[dict], gastos: List[dict]) -> "tuple[Decimal, Decimal]":
    """(presupuesto contratado, costo real acumulado): base del sobrecosto y del control de costos."""
    bac = sum((_concepto_importe_efectivo(c) for c in conceptos), start=Decimal("0"))
    ac = sum((to_decimal(g["monto"]) for g in gastos), start=Decimal("0"))
    return bac, ac


_ORDEN_TIPO_EXCEPCION = {
    "atrasado": 0, "sin_avance_en_ventana": 1, "acuerdo_vencido": 2, "ajuste_negativo": 3,
    "excedente_volumen": 4, "sobrecosto": 5, "fuera_de_ventana": 6,
}


async def calcular_excepciones_evm(pid: str, project: Optional[dict]) -> List[ExcepcionEvmOut]:
    """Lista por excepción del proyecto. Servicio ÚNICO: lo usan el endpoint del tablero y el
    Resumen con IA. Nunca bloquea nada — es solo para revisión (ver el endpoint)."""
    project = project or {}
    modo_avance = project.get("modo_avance", "CANTIDAD")
    conceptos = await db.conceptos.find({"project_id": pid, "activo": True}).to_list(length=100000)
    conceptos_por_id = {c["id"]: c for c in conceptos}
    hoy = hoy_proyecto(project)

    registros = await db.registros_avance.find({"project_id": pid}).to_list(length=1000000)
    avances_por_concepto: Dict[str, List[dict]] = {}
    for a in registros:
        avances_por_concepto.setdefault(a["concepto_id"], []).append(a)

    excepciones: List[ExcepcionEvmOut] = []

    concepto_ids_fuera_de_ventana: set = {a["concepto_id"] for a in registros if a.get("fuera_de_ventana")}
    for cid in concepto_ids_fuera_de_ventana:
        c = conceptos_por_id.get(cid)
        if not c:
            continue
        excepciones.append(ExcepcionEvmOut(
            concepto_id=cid, clave=c["clave"], descripcion=c["descripcion"],
            tipo="fuera_de_ventana",
            detalle=f"Tiene avances capturados fuera de su ventana {c.get('fecha_inicio')} — {c.get('fecha_fin')}",
        ))

    # A-02: volumen excedente (ejecutado > contratado): informativo, con cantidad e importe.
    etiqueta_estatus = {"pendiente_autorizacion": "pendiente de autorización", "autorizado": "autorizado", "rechazado": "rechazado"}
    for e in await _excedentes_del_proyecto(pid, project or {}):
        excepciones.append(ExcepcionEvmOut(
            concepto_id=e.concepto_id, clave=e.clave, descripcion=e.descripcion,
            tipo="excedente_volumen", severidad="informativa",
            cantidad=e.cantidad_excedente, importe=e.importe_excedente,
            detalle=(
                f"Ejecutado {e.cantidad_ejecutada} de {e.cantidad_contratada} contratados: excede "
                f"{e.cantidad_excedente} {e.unidad} (${e.importe_excedente}). Estatus: {etiqueta_estatus.get(e.estatus, e.estatus)}."
            ),
        ))

    # A-02: sobrecosto (costo real acumulado > presupuesto contratado): informativo.
    gastos = await db.gastos_reales.find({"project_id": pid}).to_list(length=1000000)
    bac, ac_total = _bac_y_ac(conceptos, gastos)
    if bac > 0 and ac_total > bac:
        excepciones.append(ExcepcionEvmOut(
            concepto_id="", clave="", descripcion="Proyecto completo",
            tipo="sobrecosto", severidad="informativa", importe=dec_to_str(round_money(ac_total - bac)),
            detalle=f"El costo real (${dec_to_str(round_money(ac_total))}) supera el presupuesto (${dec_to_str(round_money(bac))}).",
        ))

    # El chequeo de "atrasado" es sobre cantidad física — en modo PORCENTAJE el
    # "ejecutado" ya es un 0-100 (estado reportado), no una cantidad comparable con la meta.
    ids_atrasados: set = set()
    if modo_avance != "PORCENTAJE":
        for c in conceptos:
            if not _concepto_tiene_datos_evm(c):
                continue
            ejecutado = to_decimal(_acumulado_desde_avances(avances_por_concepto.get(c["id"], []), modo_avance))
            meta = to_decimal(c["meta_cantidad"])
            if c.get("fecha_fin") and date.fromisoformat(c["fecha_fin"]) < hoy and ejecutado < meta:
                ids_atrasados.add(c["id"])
                excepciones.append(ExcepcionEvmOut(
                    concepto_id=c["id"], clave=c["clave"], descripcion=c["descripcion"],
                    tipo="atrasado",
                    detalle=f"Debía terminar el {c['fecha_fin']} y lleva {dec_to_str(ejecutado)} de {dec_to_str(meta)} {c.get('unidad', 'UNIVERSAL')}",
                ))

    # A-03: ajustes negativos, acuerdos de minutas vencidos y conceptos sin avance en su
    # ventana del programa (todas informativas; `atrasado` tiene precedencia sobre esta última).
    excepciones.extend(excepciones_ajustes_negativos(conceptos_por_id, registros))
    minutas = await db.minutas.find({"project_id": pid}).to_list(length=5000)
    excepciones.extend(excepciones_acuerdos_vencidos(minutas, hoy))
    excepciones.extend(excepciones_sin_avance_en_ventana(
        conceptos, await _distribuciones_vigentes(pid), avances_por_concepto, hoy, ids_atrasados,
    ))

    # Sin esto, el orden salía de iterar un `set` (no determinístico) y
    # luego los conceptos en el orden que Mongo los devolviera — se veía
    # desordenado en cada refresh. Se agrupa por tipo (ver _ORDEN_TIPO_EXCEPCION: atrasado
    # primero, es el más accionable; fuera_de_ventana al final, es solo informativo) y
    # dentro de cada grupo por clave, con el mismo comparador numérico jerárquico que usa
    # el resto del catálogo (ver sort_by_clave) para que "C-2" no quede después de "C-10".
    # El sort es estable: los acuerdos vencidos (sin clave) conservan su orden por atraso.
    return sorted(
        sort_by_clave(excepciones, clave_getter=lambda e: e.clave),
        key=lambda e: _ORDEN_TIPO_EXCEPCION[e.tipo],
    )


@api.get("/projects/{pid}/analisis_periodo/excepciones", response_model=List[ExcepcionEvmOut])
async def analisis_periodo_excepciones(pid: str, user: dict = Depends(current_user)):
    """Lista por excepción del dashboard (Tarea 4): conceptos con avances fuera de su
    ventana fecha_inicio/fecha_fin, cuya fecha_fin YA PASÓ sin alcanzar la meta ("atrasado"),
    con volumen excedente o sobrecosto (A-02) y, desde A-03, con ajustes negativos, acuerdos
    de minutas vencidos y conceptos sin avance dentro de su ventana del programa. Un concepto
    sin UN SOLO avance nunca puede tener "avances fuera de ventana" (no hay avances que
    revisar), por eso existen los chequeos de atraso y de ventana sin avance. Nunca bloquea
    nada — es solo para revisión."""
    project = await ensure_project_access(user, pid)
    return await calcular_excepciones_evm(pid, project)


class ActividadEvmOut(BaseModel):
    concepto_id: str
    clave: str
    descripcion: str
    fecha_inicio: str
    fecha_fin: str
    meta_cantidad: str
    ejecutado: str
    unidad: str
    porcentaje_avance: str  # 0-100


class ActividadesEvmOut(BaseModel):
    pendientes: List[ActividadEvmOut]  # fecha_fin ya pasó y no se completó (mismo criterio que la excepción "atrasado")
    actuales: List[ActividadEvmOut]    # hoy cae dentro de fecha_inicio..fecha_fin
    por_venir: List[ActividadEvmOut]   # fecha_inicio todavía no llega


@api.get("/projects/{pid}/analisis_periodo/actividades", response_model=ActividadesEvmOut)
async def analisis_periodo_actividades(pid: str, user: dict = Depends(current_user)):
    """3 categorías de control del dashboard (Tarea 5): actividades
    PENDIENTES (ya venció su fecha_fin y no alcanzó la meta), ACTUALES (hoy
    cae dentro de su ventana) y POR VENIR (su ventana todavía no empieza —
    para dar visibilidad de lo que sigue, no solo de lo que ya se atrasó).

    Solo conceptos con datos EVM (fecha_inicio/fecha_fin, ver
    _concepto_tiene_datos_evm): un concepto sin fechas no se puede ubicar en
    el tiempo, así que no cae en ninguna categoría. Un concepto ya
    completado a tiempo (fecha_fin pasada Y ejecutado >= meta) tampoco cae
    en ninguna — ya no requiere seguimiento."""
    await ensure_project_access(user, pid)
    project = await db.projects.find_one({"id": pid})
    modo_avance = (project or {}).get("modo_avance", "CANTIDAD")
    hoy = hoy_proyecto(project)
    conceptos = await db.conceptos.find({"project_id": pid, "activo": True}).to_list(length=100000)

    pendientes: List[ActividadEvmOut] = []
    actuales: List[ActividadEvmOut] = []
    por_venir: List[ActividadEvmOut] = []

    for c in conceptos:
        if not _concepto_tiene_datos_evm(c) or not c.get("fecha_inicio") or not c.get("fecha_fin"):
            continue
        fecha_inicio_d = date.fromisoformat(c["fecha_inicio"])
        fecha_fin_d = date.fromisoformat(c["fecha_fin"])
        ejecutado = to_decimal(await _concepto_ejecutado_acumulado(c["id"], modo_avance))
        meta = to_decimal(c["meta_cantidad"])
        pct = (ejecutado / meta * to_decimal("100")) if meta != 0 else to_decimal("0")
        item = ActividadEvmOut(
            concepto_id=c["id"], clave=c["clave"], descripcion=c["descripcion"],
            fecha_inicio=c["fecha_inicio"], fecha_fin=c["fecha_fin"],
            meta_cantidad=dec_to_str(meta), ejecutado=dec_to_str(ejecutado),
            unidad=c.get("unidad", "UNIVERSAL"),
            porcentaje_avance=dec_to_str(round_money(pct)),
        )
        if fecha_fin_d < hoy and ejecutado < meta:
            pendientes.append(item)
        elif fecha_inicio_d <= hoy <= fecha_fin_d:
            actuales.append(item)
        elif fecha_inicio_d > hoy:
            por_venir.append(item)

    pendientes.sort(key=lambda a: a.fecha_fin)
    actuales.sort(key=lambda a: a.fecha_fin)
    por_venir.sort(key=lambda a: a.fecha_inicio)
    return ActividadesEvmOut(pendientes=pendientes, actuales=actuales, por_venir=por_venir)


class GastoRealIn(BaseModel):
    fecha: str  # "YYYY-MM-DD"
    monto: str
    concepto_texto: str  # descripción libre ("Nómina semana 12", "Factura #445")
    # Liga opcional (en captura manual) a un Concepto del catálogo, por
    # clave — igual que el resto de los importadores, nunca se pide el id
    # interno al usuario. AC puede seguir siendo agregado (sin concepto_clave,
    # ej. gastos generales/indirectos) o amarrado a un concepto específico
    # para poder comparar EV vs AC por concepto, no solo a nivel proyecto.
    concepto_clave: Optional[str] = None

    @field_validator("monto")
    @classmethod
    def _v_monto(cls, v):
        to_decimal(v)
        return v

    @field_validator("fecha")
    @classmethod
    def _v_fecha(cls, v):
        try:
            date.fromisoformat(v)
        except ValueError:
            raise ValueError(f"fecha inválida, se espera YYYY-MM-DD: {v!r}")
        return v


class GastoRealOut(BaseModel):
    id: str
    project_id: str
    fecha: str
    monto: str
    concepto_texto: str
    concepto_id: Optional[str] = None
    concepto_clave: Optional[str] = None
    capturado_por: str
    creado_en: datetime


@api.post("/projects/{pid}/gastos_reales", response_model=GastoRealOut)
async def create_gasto_real(pid: str, body: GastoRealIn, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """AC (Costo Real) del motor EVM: captura simple y manual — no intenta
    reconciliar facturas/nómina automáticamente, solo registra el monto que
    administración ya calculó fuera del sistema."""
    await ensure_project_access(user, pid)
    concepto_id = None
    concepto_clave = None
    if body.concepto_clave:
        clave = body.concepto_clave.strip()
        concepto = await db.conceptos.find_one({"project_id": pid, "clave": clave})
        if not concepto:
            raise HTTPException(404, f"No existe ningún concepto con clave '{clave}' en este proyecto")
        concepto_id = concepto["id"]
        concepto_clave = concepto["clave"]
    gid = str(uuid.uuid4())
    doc = {
        "id": gid, "project_id": pid, "fecha": body.fecha, "monto": body.monto,
        "concepto_texto": body.concepto_texto.strip(),
        "concepto_id": concepto_id, "concepto_clave": concepto_clave,
        "capturado_por": user["id"], "creado_en": datetime.now(timezone.utc),
    }
    await db.gastos_reales.insert_one(doc)
    return GastoRealOut(**doc)


@api.get("/projects/{pid}/gastos_reales", response_model=List[GastoRealOut])
async def list_gastos_reales(pid: str, desde: Optional[str] = None, hasta: Optional[str] = None, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    query: dict = {"project_id": pid}
    if desde or hasta:
        rango: dict = {}
        if desde:
            rango["$gte"] = desde
        if hasta:
            rango["$lte"] = hasta
        query["fecha"] = rango
    docs = await db.gastos_reales.find(query).sort("fecha", -1).to_list(length=100000)
    return [GastoRealOut(**d) for d in docs]


class GastoRealImportErrorOut(BaseModel):
    fila: int
    motivo: str


class GastoRealImportResultOut(BaseModel):
    total_filas: int
    creados: int
    errores: List[GastoRealImportErrorOut]
    errores_truncados: bool  # True si hubo más errores de los que se listan en `errores`


_GASTO_REAL_IMPORT_MAX_ERRORES = 200


@api.get("/gastos_reales/import/plantilla.xlsx")
async def gastos_reales_import_plantilla(user: dict = Depends(current_user)):
    """Plantilla descargable para el importador masivo de Gasto Real —
    columnas Clave/Fecha/Monto/Descripción, una fila de ejemplo y una hoja
    de instrucciones (mismo criterio que /conceptos/import_evm/plantilla.xlsx)."""
    from openpyxl import Workbook
    from openpyxl.styles import Font, PatternFill, Alignment
    from openpyxl.utils import get_column_letter

    wb = Workbook()
    ws = wb.active
    ws.title = "Gasto real"

    headers = ["Clave", "Fecha", "Monto", "Descripción"]
    for col, h in enumerate(headers, start=1):
        cell = ws.cell(row=1, column=col, value=h)
        cell.font = Font(bold=True, color="FFFFFF")
        cell.fill = PatternFill("solid", fgColor="1E3A8A")
        cell.alignment = Alignment(horizontal="center")

    ejemplo = ["C-001", date(2026, 2, 15), "200000.00", "Nómina semana 7"]
    for col, v in enumerate(ejemplo, start=1):
        cell = ws.cell(row=2, column=col, value=v)
        if col == 2:
            cell.number_format = "DD/MM/YYYY"

    for i, w in enumerate([14, 14, 14, 40], start=1):
        ws.column_dimensions[get_column_letter(i)].width = w
    ws.freeze_panes = "A2"

    ws2 = wb.create_sheet("Instrucciones")
    instrucciones = [
        "Cómo llenar esta plantilla para el importador masivo de Gasto Real (AC)",
        "",
        "1. Clave: la clave de un concepto que YA EXISTA en el catálogo de este proyecto (ej. C-001). "
        "Si la clave no existe, esa fila se reporta como error y no se importa — el resto del archivo sí se procesa.",
        "2. Fecha: fecha en que se realizó el gasto. DEBE ser una celda con formato de FECHA de Excel, "
        "como en la fila de ejemplo — si Excel la trae como texto no se va a leer.",
        "3. Monto: importe gastado ese día para ese concepto (número, hasta 2 decimales).",
        "4. Descripción (opcional): texto libre (ej. \"Nómina semana 7\", \"Factura #445\"). "
        "Si se deja vacía, se usa la descripción del concepto.",
        "",
        "No hay límite práctico de filas — está pensado para cargar de golpe meses o años de gasto histórico.",
        "No borres la fila de encabezado (fila 1). La fila 2 es solo un ejemplo — bórrala antes de importar.",
    ]
    for i, txt in enumerate(instrucciones, start=1):
        c = ws2.cell(row=i, column=1, value=txt)
        if i == 1:
            c.font = Font(bold=True, size=13, color="1E3A8A")
    ws2.column_dimensions["A"].width = 110

    buf = io.BytesIO()
    wb.save(buf)
    buf.seek(0)
    return StreamingResponse(
        buf,
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": 'attachment; filename="plantilla_gasto_real.xlsx"'},
    )


@api.post("/projects/{pid}/gastos_reales/import", response_model=GastoRealImportResultOut)
async def import_gastos_reales(
    pid: str, file: UploadFile = File(...), user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD)),
):
    """Importador masivo de Gasto Real (AC) — pensado para cargar de golpe
    meses/años de gasto histórico (miles de filas) en vez de captura manual
    una por una (ver create_gasto_real). A diferencia de los demás
    importadores del proyecto, NO usa el wizard de 4 pasos (subir → mapear →
    validar → comitear): la plantilla es FIJA (Clave/Fecha/Monto/
    Descripción, ver /gastos_reales/import/plantilla.xlsx), así que no hay
    mapeo de columnas que negociar; y un GastoReal no tiene noción de
    "duplicado" (dos facturas del mismo concepto el mismo día son
    perfectamente válidas), así que tampoco hace falta una sesión de
    staging con corrección interactiva. Se valida y comitea en un solo
    request — las filas con error simplemente no se insertan y se
    reportan para corregirlas en el Excel y volver a subir solo esas.

    A diferencia de la captura manual (donde concepto_clave es opcional),
    aquí CADA fila debe ligar a un concepto ya existente en el proyecto:
    si vas a importar miles de gastos históricos es para poder comparar
    EV vs AC por concepto, no para acumular un bulto agregado."""
    await ensure_project_access(user, pid)
    content = await file.read()
    sheets = _read_workbook_sheets(file.filename or "archivo.xlsx", content)
    if not sheets:
        raise HTTPException(400, "El archivo no tiene hojas legibles")
    rows = next(iter(sheets.values()))
    if len(rows) < 2:
        raise HTTPException(400, "El archivo no tiene filas de datos (solo encabezado, o está vacío)")

    headers = [str(c).strip() if c is not None else "" for c in rows[0]]
    normalized = [_normalize_text(h) for h in headers]

    def find_col(*keywords: str) -> Optional[int]:
        for idx, h in enumerate(normalized):
            if any(kw in h for kw in keywords):
                return idx
        return None

    idx_clave = find_col("clave", "concepto")
    idx_fecha = find_col("fecha")
    idx_monto = find_col("monto", "importe")
    idx_desc = find_col("descripcion", "descripción", "nota")
    if idx_clave is None or idx_fecha is None or idx_monto is None:
        raise HTTPException(
            400,
            "El archivo debe tener columnas Clave, Fecha y Monto (Descripción es opcional). "
            "Descarga la plantilla en /gastos_reales/import/plantilla.xlsx.",
        )

    data_rows = rows[1:]
    montos_raw = [r[idx_monto] if idx_monto < len(r) else None for r in data_rows]
    convencion = detectar_convencion(montos_raw)

    conceptos = await db.conceptos.find({"project_id": pid}).to_list(length=100000)
    conceptos_por_clave = {c["clave"]: c for c in conceptos}

    docs: List[dict] = []
    errores: List[dict] = []
    ahora = datetime.now(timezone.utc)
    for i, row in enumerate(data_rows):
        fila_num = i + 2  # +1 por encabezado (fila 1), +1 porque Excel es 1-based
        clave_raw = row[idx_clave] if idx_clave < len(row) else None
        if clave_raw in (None, ""):
            continue  # fila vacía/de relleno, se ignora silenciosamente

        clave = str(clave_raw).strip()
        concepto = conceptos_por_clave.get(clave)
        if not concepto:
            errores.append({"fila": fila_num, "motivo": f"No existe ningún concepto con clave '{clave}' en este proyecto"})
            continue

        fecha_raw = row[idx_fecha] if idx_fecha < len(row) else None
        fecha_iso = _fecha_excel_a_iso(fecha_raw)
        if fecha_iso is None:
            errores.append({"fila": fila_num, "motivo": f"Fecha inválida o no es una celda de fecha de Excel: {fecha_raw!r}"})
            continue

        monto_raw = row[idx_monto] if idx_monto < len(row) else None
        try:
            monto = _parse_celda_numerica(monto_raw, convencion)
        except (CeldaErrorExcelError, NumeroAmbiguoError, ValueError) as e:
            errores.append({"fila": fila_num, "motivo": str(e)})
            continue

        desc_raw = row[idx_desc] if idx_desc is not None and idx_desc < len(row) else None
        descripcion = (str(desc_raw).strip() if desc_raw is not None else "") or concepto["descripcion"]

        docs.append({
            "id": str(uuid.uuid4()), "project_id": pid, "fecha": fecha_iso, "monto": dec_to_str(monto),
            "concepto_texto": descripcion, "concepto_id": concepto["id"], "concepto_clave": concepto["clave"],
            "capturado_por": user["id"], "creado_en": ahora,
        })

    if docs:
        await db.gastos_reales.insert_many(docs)

    truncados = len(errores) > _GASTO_REAL_IMPORT_MAX_ERRORES
    return GastoRealImportResultOut(
        total_filas=len(data_rows), creados=len(docs),
        errores=[GastoRealImportErrorOut(**e) for e in errores[:_GASTO_REAL_IMPORT_MAX_ERRORES]],
        errores_truncados=truncados,
    )


@api.delete("/gastos_reales/{gasto_id}")
async def delete_gasto_real(gasto_id: str, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    gasto = await db.gastos_reales.find_one({"id": gasto_id})
    if not gasto:
        raise HTTPException(404, "Gasto no existe")
    await ensure_project_access(user, gasto["project_id"])
    await db.gastos_reales.delete_one({"id": gasto_id})
    return {"ok": True}


# === Exportar PDF ===============================================================
def _safe_filename_fragment(name: str) -> str:
    return re.sub(r"[^A-Za-z0-9_-]+", "_", (name or "").strip()).strip("_") or "catalogo"


@api.get("/projects/{pid}/export/catalogo.pdf")
async def export_catalogo_pdf(pid: str, user: dict = Depends(current_user)):
    """PDF del catálogo de conceptos: una tabla por partida (mismo orden de
    columnas que la vista tabla de la pantalla) + total del catálogo.
    Mismo criterio que export_reports_pdf: render bloqueante (reportlab) en
    thread aparte, 100% en memoria (BytesIO), sin escribir a disco."""
    await ensure_project_access(user, pid)
    proj = await db.projects.find_one({"id": pid})
    if not proj:
        raise HTTPException(404, "Proyecto no existe")

    partidas_docs = sort_by_clave(await db.partidas.find({"project_id": pid, "activo": True}).to_list(length=10000))
    partidas_out = [await _partida_out(d, partidas_docs) for d in partidas_docs]
    conceptos_por_partida = {}
    for d in partidas_docs:
        conceptos = sort_by_clave(await db.conceptos.find({"partida_id": d["id"], "activo": True}).to_list(length=100000))
        conceptos_por_partida[d["id"]] = [await _concepto_out(c) for c in conceptos]

    project_name = proj.get("name", "Proyecto")
    project_color = _sanitize_color_hex(proj.get("color_institucional") or proj.get("color_tema")) or "#003366"
    total_catalogo = sum_decimales([p.importe_contratado_partida for p in partidas_out])
    titulo_modulo_raw = (proj.get("titulo_modulo_catalogo") or "").strip()
    titulo_modulo = titulo_modulo_raw or "Catálogo de Conceptos"
    # Fragmento de archivo: si no hay título propio, se preserva LITERAL el
    # nombre de archivo histórico ("catalogo_conceptos_...") en vez de pasar
    # el fallback con acentos por el sanitizador — evita que el nombre del
    # PDF cambie para un proyecto que no configuró nada.
    titulo_modulo_fname = _safe_filename_fragment(titulo_modulo_raw) if titulo_modulo_raw else "catalogo_conceptos"

    def _build_pdf_blocking() -> bytes:
        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.lib.units import cm
        from reportlab.lib.colors import HexColor, white
        from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.enums import TA_RIGHT

        buf = io.BytesIO()
        doc = SimpleDocTemplate(
            buf, pagesize=landscape(A4),
            topMargin=1.2 * cm, bottomMargin=1.2 * cm, leftMargin=1.2 * cm, rightMargin=1.2 * cm,
        )
        styles = getSampleStyleSheet()
        title_style = ParagraphStyle("CatTitle", parent=styles["Heading1"], textColor=HexColor(project_color), fontSize=16)
        partida_style = ParagraphStyle("CatPartida", parent=styles["Heading2"], fontSize=12, spaceBefore=10)
        cell_style = ParagraphStyle("CatCell", parent=styles["BodyText"], fontSize=8, leading=10)
        money_style = ParagraphStyle("CatMoney", parent=styles["BodyText"], fontSize=8, leading=10, alignment=TA_RIGHT)

        story = [
            Paragraph(f"{titulo_modulo.upper()} — {project_name}", title_style),
            Spacer(1, 10),
        ]
        col_widths = [2.2 * cm, 9.5 * cm, 1.6 * cm, 2.2 * cm, 2.6 * cm, 2.8 * cm]
        header_row = [
            Paragraph("CLAVE", cell_style), Paragraph("DESCRIPCIÓN", cell_style),
            Paragraph("UNIDAD", cell_style), Paragraph("CANTIDAD", cell_style),
            Paragraph("PU", cell_style), Paragraph("IMPORTE", cell_style),
        ]
        for p in partidas_out:
            story.append(Paragraph(f"{p.clave} — {p.nombre}", partida_style))
            rows = [header_row]
            for c in conceptos_por_partida.get(p.id, []):
                rows.append([
                    Paragraph(c.clave, cell_style),
                    Paragraph(c.descripcion, cell_style),
                    Paragraph(c.unidad, cell_style),
                    Paragraph(dec_to_str(round_money(c.cantidad)), money_style),
                    Paragraph(dec_to_str(round_money(c.precio_unitario)), money_style),
                    Paragraph(dec_to_str(round_money(c.importe_contratado)), money_style),
                ])
            rows.append([
                "", "", "", "", Paragraph("SUBTOTAL", cell_style),
                Paragraph(dec_to_str(round_money(p.importe_contratado_partida)), money_style),
            ])
            table = Table(rows, colWidths=col_widths, repeatRows=1)
            table.setStyle(TableStyle([
                ("BACKGROUND", (0, 0), (-1, 0), HexColor(project_color)),
                ("TEXTCOLOR", (0, 0), (-1, 0), white),
                ("FONTSIZE", (0, 0), (-1, 0), 8),
                ("GRID", (0, 0), (-1, -2), 0.4, HexColor("#CBD5E1")),
                ("LINEABOVE", (0, -1), (-1, -1), 0.8, HexColor("#94A3B8")),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
                ("ROWBACKGROUNDS", (0, 1), (-1, -2), [white, HexColor("#F8FAFC")]),
            ]))
            story.append(table)

        story.append(Spacer(1, 14))
        story.append(Paragraph(
            f"TOTAL DEL CATÁLOGO: {dec_to_str(round_money(total_catalogo))}",
            ParagraphStyle("CatTotal", parent=styles["Heading2"], alignment=TA_RIGHT),
        ))
        doc.build(story)
        return buf.getvalue()

    pdf_bytes = await asyncio.to_thread(_build_pdf_blocking)
    fname = f"{titulo_modulo_fname}_{_safe_filename_fragment(project_name)}.pdf"
    return StreamingResponse(
        io.BytesIO(pdf_bytes),
        media_type="application/pdf",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


@api.get("/projects/{pid}/export/avance_periodo.pdf")
async def export_avance_periodo_pdf(
    pid: str,
    desde: Optional[str] = None,
    hasta: Optional[str] = None,
    partida_id: Optional[str] = None,
    user: dict = Depends(current_user),
):
    """PDF del avance del periodo (pantalla 'Visualizar avance'): filas =
    conceptos en los que se gastó dinero en el periodo, columnas = días con
    registros, celda = importe gastado ese día en ese concepto. Incluye fila
    de totales por día y total general del periodo. Mismos filtros que
    list_avances/avances_resumen. Mismo criterio que export_catalogo_pdf:
    render bloqueante (reportlab) en thread aparte, 100% en memoria."""
    await ensure_project_access(user, pid)
    proj = await db.projects.find_one({"id": pid})
    if not proj:
        raise HTTPException(404, "Proyecto no existe")

    query: dict = {"project_id": pid}
    if desde or hasta:
        rango: dict = {}
        if desde:
            rango["$gte"] = desde
        if hasta:
            rango["$lte"] = hasta
        query["fecha"] = rango
    if partida_id:
        partida_ids = await _partida_subtree_ids_en_proyecto(pid, partida_id)
        conceptos_filtro = await db.conceptos.find({"partida_id": {"$in": partida_ids}}).to_list(length=100000)
        query["concepto_id"] = {"$in": [c["id"] for c in conceptos_filtro]}
    docs = await db.registros_avance.find(query).to_list(length=100000)

    concepto_ids = list({d["concepto_id"] for d in docs})
    conceptos_por_id: dict = {}
    if concepto_ids:
        cs = await db.conceptos.find({"id": {"$in": concepto_ids}}).to_list(length=len(concepto_ids))
        conceptos_por_id = {c["id"]: c for c in cs}

    # Importe por (concepto_id, fecha) — suma si hay varios registros el
    # mismo día para el mismo concepto (nunca se sobreescriben entre sí).
    importes: dict = {}
    fechas_set: set = set()
    for d in docs:
        cid = d["concepto_id"]
        c = conceptos_por_id.get(cid)
        if not c:
            continue  # concepto ya no existe/no accesible — se omite del reporte
        importe = _registro_importe_efectivo(d, c)
        if importe == 0:
            continue
        fecha = d["fecha"]
        fechas_set.add(fecha)
        key = (cid, fecha)
        importes[key] = importes.get(key, Decimal("0")) + importe

    concepto_ids_con_gasto = sorted({cid for (cid, _f) in importes.keys()})
    conceptos_out = sort_by_clave([conceptos_por_id[cid] for cid in concepto_ids_con_gasto])
    fechas = sorted(fechas_set)

    project_name = proj.get("name", "Proyecto")
    project_color = _sanitize_color_hex(proj.get("color_institucional") or proj.get("color_tema")) or "#003366"

    if desde and hasta:
        periodo_label = f"DEL {desde} AL {hasta}"
    elif desde:
        periodo_label = f"DESDE {desde}"
    elif hasta:
        periodo_label = f"HASTA {hasta}"
    else:
        periodo_label = "TODO EL PROYECTO"

    def _build_pdf_blocking() -> bytes:
        from reportlab.lib.pagesizes import A4, landscape
        from reportlab.lib.units import cm
        from reportlab.lib.colors import HexColor, white
        from reportlab.platypus import SimpleDocTemplate, Table, TableStyle, Paragraph, Spacer, PageBreak
        from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
        from reportlab.lib.enums import TA_RIGHT, TA_CENTER

        buf = io.BytesIO()
        doc = SimpleDocTemplate(
            buf, pagesize=landscape(A4),
            topMargin=1.2 * cm, bottomMargin=1.2 * cm, leftMargin=1.2 * cm, rightMargin=1.2 * cm,
        )
        styles = getSampleStyleSheet()
        title_style = ParagraphStyle("AvTitle", parent=styles["Heading1"], textColor=HexColor(project_color), fontSize=15)
        subtitle_style = ParagraphStyle("AvSubtitle", parent=styles["Heading3"], fontSize=10, textColor=HexColor("#475569"), spaceAfter=8)
        cell_style = ParagraphStyle("AvCell", parent=styles["BodyText"], fontSize=7, leading=8)
        money_style = ParagraphStyle("AvMoney", parent=styles["BodyText"], fontSize=7, leading=8, alignment=TA_RIGHT)
        header_style = ParagraphStyle("AvHeader", parent=styles["BodyText"], fontSize=7, leading=8, textColor=white, alignment=TA_CENTER)

        story = [
            Paragraph(f"AVANCE POR PERIODO — {project_name}", title_style),
            Paragraph(periodo_label, subtitle_style),
        ]

        if not conceptos_out or not fechas:
            story.append(Paragraph("Sin registros de avance en este periodo.", styles["BodyText"]))
            doc.build(story)
            return buf.getvalue()

        CONCEPTO_COL = 6.5 * cm
        TOTAL_COL = 2.2 * cm
        DIA_COL = 1.7 * cm
        usable = landscape(A4)[0] - 2.4 * cm
        dias_por_pagina = max(1, int((usable - CONCEPTO_COL - TOTAL_COL) // DIA_COL))
        bloques = [fechas[i:i + dias_por_pagina] for i in range(0, len(fechas), dias_por_pagina)]

        total_general = Decimal("0")
        for bi, bloque in enumerate(bloques):
            col_widths = [CONCEPTO_COL] + [DIA_COL] * len(bloque) + [TOTAL_COL]
            header_row = [Paragraph("CONCEPTO", header_style)]
            header_row += [Paragraph(f"{f[8:10]}/{f[5:7]}", header_style) for f in bloque]
            header_row += [Paragraph("TOTAL", header_style)]
            rows = [header_row]

            totales_col = {f: Decimal("0") for f in bloque}
            for c in conceptos_out:
                fila = [Paragraph(f'{c["clave"]} — {c.get("descripcion", "")}', cell_style)]
                total_fila = Decimal("0")
                for f in bloque:
                    v = importes.get((c["id"], f), Decimal("0"))
                    totales_col[f] += v
                    total_fila += v
                    fila.append(Paragraph(dec_to_str(round_money(v)) if v else "-", money_style))
                fila.append(Paragraph(dec_to_str(round_money(total_fila)), money_style))
                rows.append(fila)

            fila_total = [Paragraph("TOTAL DEL DÍA", cell_style)]
            total_bloque = Decimal("0")
            for f in bloque:
                fila_total.append(Paragraph(dec_to_str(round_money(totales_col[f])), money_style))
                total_bloque += totales_col[f]
            fila_total.append(Paragraph(dec_to_str(round_money(total_bloque)), money_style))
            rows.append(fila_total)
            total_general += total_bloque

            table = Table(rows, colWidths=col_widths, repeatRows=1)
            table.setStyle(TableStyle([
                ("BACKGROUND", (0, 0), (-1, 0), HexColor(project_color)),
                ("TEXTCOLOR", (0, 0), (-1, 0), white),
                ("GRID", (0, 0), (-1, -2), 0.4, HexColor("#CBD5E1")),
                ("LINEABOVE", (0, -1), (-1, -1), 0.8, HexColor("#94A3B8")),
                ("FONTNAME", (0, -1), (-1, -1), "Helvetica-Bold"),
                ("VALIGN", (0, 0), (-1, -1), "TOP"),
                ("ROWBACKGROUNDS", (0, 1), (-1, -2), [white, HexColor("#F8FAFC")]),
            ]))
            story.append(table)
            if bi < len(bloques) - 1:
                story.append(PageBreak())

        story.append(Spacer(1, 14))
        story.append(Paragraph(
            f"TOTAL GASTADO EN EL PERIODO: {dec_to_str(round_money(total_general))}",
            ParagraphStyle("AvTotal", parent=styles["Heading2"], alignment=TA_RIGHT),
        ))
        doc.build(story)
        return buf.getvalue()

    pdf_bytes = await asyncio.to_thread(_build_pdf_blocking)
    frag_periodo = _safe_filename_fragment(f"{desde or 'inicio'}_{hasta or 'fin'}")
    fname = f"avance_periodo_{_safe_filename_fragment(project_name)}_{frag_periodo}.pdf"
    return StreamingResponse(
        io.BytesIO(pdf_bytes),
        media_type="application/pdf",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


@api.get("/projects/{pid}/export/avance_periodo.xlsx")
async def export_avance_periodo_xlsx(
    pid: str,
    desde: Optional[str] = None,
    hasta: Optional[str] = None,
    partida_id: Optional[str] = None,
    user: dict = Depends(current_user),
):
    """Excel del avance del periodo — misma matriz conceptos x días que
    export_avance_periodo_pdf (mismos filtros/criterio de agregación), en
    formato editable/exportable a hojas de cálculo. Es el formato que el
    usuario usa como principal; el PDF queda como alternativa de solo
    lectura."""
    await ensure_project_access(user, pid)
    proj = await db.projects.find_one({"id": pid})
    if not proj:
        raise HTTPException(404, "Proyecto no existe")

    query: dict = {"project_id": pid}
    if desde or hasta:
        rango: dict = {}
        if desde:
            rango["$gte"] = desde
        if hasta:
            rango["$lte"] = hasta
        query["fecha"] = rango
    if partida_id:
        partida_ids = await _partida_subtree_ids_en_proyecto(pid, partida_id)
        conceptos_filtro = await db.conceptos.find({"partida_id": {"$in": partida_ids}}).to_list(length=100000)
        query["concepto_id"] = {"$in": [c["id"] for c in conceptos_filtro]}
    docs = await db.registros_avance.find(query).to_list(length=100000)

    concepto_ids = list({d["concepto_id"] for d in docs})
    conceptos_por_id: dict = {}
    if concepto_ids:
        cs = await db.conceptos.find({"id": {"$in": concepto_ids}}).to_list(length=len(concepto_ids))
        conceptos_por_id = {c["id"]: c for c in cs}

    importes: dict = {}
    fechas_set: set = set()
    for d in docs:
        cid = d["concepto_id"]
        c = conceptos_por_id.get(cid)
        if not c:
            continue
        importe = _registro_importe_efectivo(d, c)
        if importe == 0:
            continue
        fecha = d["fecha"]
        fechas_set.add(fecha)
        key = (cid, fecha)
        importes[key] = importes.get(key, Decimal("0")) + importe

    concepto_ids_con_gasto = sorted({cid for (cid, _f) in importes.keys()})
    conceptos_out = sort_by_clave([conceptos_por_id[cid] for cid in concepto_ids_con_gasto])
    fechas = sorted(fechas_set)

    project_name = proj.get("name", "Proyecto")
    if desde and hasta:
        periodo_label = f"Del {desde} al {hasta}"
    elif desde:
        periodo_label = f"Desde {desde}"
    elif hasta:
        periodo_label = f"Hasta {hasta}"
    else:
        periodo_label = "Todo el proyecto"

    def _build_xlsx_blocking() -> bytes:
        from openpyxl import Workbook
        from openpyxl.styles import Font, PatternFill, Alignment
        from openpyxl.utils import get_column_letter

        wb = Workbook()
        ws = wb.active
        ws.title = "Avance del periodo"

        ws.cell(row=1, column=1, value=f"AVANCE POR PERIODO — {project_name}").font = Font(bold=True, size=13)
        ws.cell(row=2, column=1, value=periodo_label).font = Font(italic=True, color="475569")

        if not conceptos_out or not fechas:
            ws.cell(row=4, column=1, value="Sin registros de avance en este periodo.")
            buf = io.BytesIO()
            wb.save(buf)
            buf.seek(0)
            return buf.getvalue()

        header_row_idx = 4
        headers = ["Concepto"] + fechas + ["Total"]
        for col, h in enumerate(headers, start=1):
            cell = ws.cell(row=header_row_idx, column=col, value=h)
            cell.font = Font(bold=True, color="FFFFFF")
            cell.fill = PatternFill("solid", fgColor="1E3A8A")
            cell.alignment = Alignment(horizontal="center")

        totales_col = {f: Decimal("0") for f in fechas}
        r = header_row_idx + 1
        for c in conceptos_out:
            ws.cell(row=r, column=1, value=f'{c["clave"]} — {c.get("descripcion", "")}')
            total_fila = Decimal("0")
            for i, f in enumerate(fechas, start=2):
                v = importes.get((c["id"], f), Decimal("0"))
                totales_col[f] += v
                total_fila += v
                if v:
                    ws.cell(row=r, column=i, value=float(round_money(v)))
            ws.cell(row=r, column=len(headers), value=float(round_money(total_fila))).font = Font(bold=True)
            r += 1

        total_general = Decimal("0")
        ws.cell(row=r, column=1, value="TOTAL DEL DÍA").font = Font(bold=True)
        for i, f in enumerate(fechas, start=2):
            ws.cell(row=r, column=i, value=float(round_money(totales_col[f]))).font = Font(bold=True)
            total_general += totales_col[f]
        ws.cell(row=r, column=len(headers), value=float(round_money(total_general))).font = Font(bold=True)

        r += 2
        ws.cell(row=r, column=1, value=f"TOTAL GASTADO EN EL PERIODO: {dec_to_str(round_money(total_general))}").font = Font(bold=True, size=12)

        money_fmt = '#,##0.00'
        for col in range(2, len(headers) + 1):
            for row in range(header_row_idx + 1, r - 1):
                ws.cell(row=row, column=col).number_format = money_fmt
        ws.column_dimensions["A"].width = 50
        for i in range(2, len(headers) + 1):
            ws.column_dimensions[get_column_letter(i)].width = 14
        ws.freeze_panes = ws.cell(row=header_row_idx + 1, column=2).coordinate

        buf = io.BytesIO()
        wb.save(buf)
        buf.seek(0)
        return buf.getvalue()

    xlsx_bytes = await asyncio.to_thread(_build_xlsx_blocking)
    frag_periodo = _safe_filename_fragment(f"{desde or 'inicio'}_{hasta or 'fin'}")
    fname = f"avance_periodo_{_safe_filename_fragment(project_name)}_{frag_periodo}.xlsx"
    return StreamingResponse(
        io.BytesIO(xlsx_bytes),
        media_type="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet",
        headers={"Content-Disposition": f'attachment; filename="{fname}"'},
    )


# === PROGRAMA DESGLOSADO — wizard de importación y versionado ==============
# Segundo destino del MISMO wizard de importación (subir -> hoja -> mapear ->
# validar/preview -> commit) que ya existe para el catálogo. Sesión propia
# (`programa_import_sessions`) porque el resultado no crea/edita conceptos:
# adjunta una distribución mensual (ProgramaDistribucion) a conceptos que YA
# existen en el catálogo, agrupada en una ProgramaVersion versionada — los
# programas se reprograman, nunca se sobrescriben ni se borran avances.

class ProgramaImportMappingIn(BaseModel):
    codigo: Optional[str] = None
    importe: Optional[str] = None
    inicio: Optional[str] = None
    fin: Optional[str] = None
    # Nombre de columna de cada Mes N, EN ORDEN — no hay un patrón fijo de
    # nombre entre archivos, así que se mapean por nombre de encabezado como
    # el resto de los campos, no por índice fijo.
    meses: List[str] = Field(default_factory=list)


class ProgramaImportValidateIn(BaseModel):
    sheet: str
    header_row_index: int = 0
    mapping: ProgramaImportMappingIn
    convencion: Optional[ConvencionDecimal] = None
    etiqueta: str = ""


class ProgramaRowCorrectionIn(BaseModel):
    descartar: bool = True


class ProgramaVersionOut(BaseModel):
    id: str
    project_id: str
    etiqueta: str
    fecha_importacion: datetime
    vigente: bool
    creado_por: str
    filename: Optional[str] = None


class ProgramaDistribucionMesOut(BaseModel):
    fecha_inicio: Optional[str] = None
    fecha_fin: Optional[str] = None
    importe: str


class ProgramaDistribucionOut(BaseModel):
    id: str
    project_id: str
    programa_version_id: str
    concepto_id: str
    clave: str
    fecha_inicio_contractual: Optional[str] = None
    fecha_fin_contractual: Optional[str] = None
    importe_concepto: str
    meses: List[ProgramaDistribucionMesOut]


_MAPPING_KEYWORDS_PROGRAMA = {
    "codigo": ("codigo", "código", "clave"),
    "importe": ("importe",),
    "inicio": ("inicio",),
    "fin": ("fin", "termino", "término"),
}


def _propose_mapping_programa(headers: List[str]) -> dict:
    """Espejo de _propose_mapping (catálogo) para los campos fijos, más
    detección de columnas "Mes N" por patrón — esas SÍ pueden proponerse
    automáticamente porque su nombre es predecible, a diferencia de
    clave/descripción del catálogo que varían por archivo."""
    normalized = [_normalize_text(h) for h in headers]
    mapping: dict = {}
    used_idx: set = set()
    for target, keywords in _MAPPING_KEYWORDS_PROGRAMA.items():
        best_idx = None
        for idx, h in enumerate(normalized):
            if idx in used_idx or not h:
                continue
            if any(kw in h for kw in keywords):
                best_idx = idx
                break
        if best_idx is not None:
            mapping[target] = headers[best_idx]
            used_idx.add(best_idx)
    meses = [
        headers[idx] for idx, h in enumerate(normalized)
        if idx not in used_idx and re.match(r"^mes\s*\d+", h)
    ]
    mapping["meses"] = meses
    return mapping


def _validar_archivo_programa_completo(
    rows: List[list],
    header_row_index: int,
    mapping: "ProgramaImportMappingIn",
    convencion: Optional[ConvencionDecimal],
    conceptos_by_clave: dict,
) -> List[dict]:
    """Procesa TODO el archivo del programa desglosado UNA vez — puro, mismo
    criterio que _validar_archivo_completo del catálogo: el resultado es
    inmutable, las correcciones (solo "descartar" aquí — este importador no
    edita cantidad/PU/unidad, solo adjunta una distribución a un concepto
    que YA existe) viven aparte como overlay en _calcular_vista_programa.

    header_row_index es la fila de encabezados (Código/Descripción/.../
    Mes N); header_row_index+1 es la fila de RANGO DE FECHAS de cada Mes N
    (no de datos); los conceptos empiezan en header_row_index+2."""
    if len(rows) <= header_row_index + 1:
        raise HTTPException(400, "header_row_index fuera de rango (no hay fila de rangos de fecha ni datos después)")
    headers = [str(c) if c is not None else "" for c in rows[header_row_index]]

    def col(header_name: Optional[str]):
        if not header_name or header_name not in headers:
            return None
        return headers.index(header_name)

    idx_codigo = col(mapping.codigo)
    idx_importe = col(mapping.importe)
    idx_inicio = col(mapping.inicio)
    idx_fin = col(mapping.fin)
    idx_meses = [col(m) for m in mapping.meses]
    if idx_codigo is None or idx_importe is None:
        raise HTTPException(400, "El mapeo debe incluir al menos código e importe")
    if any(i is None for i in idx_meses):
        raise HTTPException(400, "Alguna columna de mes mapeada no existe en el encabezado elegido")

    fila_rangos = rows[header_row_index + 1]
    rangos_mes = [parse_rango_fechas_mes(fila_rangos[i] if i < len(fila_rangos) else None) for i in idx_meses]

    data_rows = rows[header_row_index + 2:]
    bloques = agrupar_bloques_programa(data_rows, idx_codigo)

    filas: List[dict] = []
    for bloque in bloques:
        fila_datos = bloque["fila_datos"]
        codigo_raw = fila_datos[idx_codigo] if idx_codigo < len(fila_datos) else None
        clave = str(codigo_raw).strip() if codigo_raw not in (None, "") else None
        if not clave:
            continue  # fila de relleno, se ignora silenciosamente (igual que el import de catálogo)

        problemas: List[dict] = []
        importe_raw = fila_datos[idx_importe] if idx_importe < len(fila_datos) else None
        try:
            importe_concepto = _parse_celda_numerica(importe_raw, convencion)
        except ValueError as e:
            importe_concepto = to_decimal("0")
            problemas.append({"tipo": "importe_ilegible", "campo": "importe", "motivo": str(e)})

        concepto_existente = conceptos_by_clave.get(clave)
        if not concepto_existente:
            problemas.append({
                "tipo": "concepto_no_encontrado", "campo": "codigo",
                "motivo": f"No existe ningún concepto con clave '{clave}' en el catálogo de este proyecto",
            })

        inicio = _fecha_excel_a_iso(fila_datos[idx_inicio]) if idx_inicio is not None and idx_inicio < len(fila_datos) else None
        fin = _fecha_excel_a_iso(fila_datos[idx_fin]) if idx_fin is not None and idx_fin < len(fila_datos) else None

        if inicio and fin and fin < inicio:
            problemas.append({
                "tipo": "rango_fecha_invalido", "campo": "fin",
                "motivo": f"La fecha de fin ({fin}) es anterior a la fecha de inicio ({inicio}).",
            })

        valores_mensuales, errores_mes = extraer_distribucion_mensual_bloque(bloque["fila_importes"], idx_meses, convencion)
        for err in errores_mes:
            problemas.append({"tipo": "celda_mes_ilegible", "campo": "meses", "motivo": err})

        # Un mes con importe pero sin rango de fechas legible (o con el fin antes del inicio)
        # no se puede ubicar en el tiempo: nunca se importa en silencio como si valiera 0.
        for i, nombre_mes in enumerate(mapping.meses):
            rango = rangos_mes[i]
            if valores_mensuales[i] == 0:
                continue
            if rango is None:
                problemas.append({
                    "tipo": "rango_mes_ilegible", "campo": "meses",
                    "motivo": f"La columna «{nombre_mes}» trae importe pero su rango de fechas no se pudo leer (esperado: «DEL 1/12/25 AL 31/12/25»).",
                })
            elif rango[1] < rango[0]:
                problemas.append({
                    "tipo": "rango_mes_ilegible", "campo": "meses",
                    "motivo": f"En la columna «{nombre_mes}» la fecha final ({rango[1]}) es anterior a la inicial ({rango[0]}).",
                })

        tiene_distribucion_propia = bloque["fila_importes"] is not None
        if tiene_distribucion_propia:
            problema_cuadre = validar_cuadre_distribucion(importe_concepto, valores_mensuales)
            if problema_cuadre:
                problemas.append(problema_cuadre)

        meses_out = [
            {
                "fecha_inicio": rangos_mes[i][0] if rangos_mes[i] else None,
                "fecha_fin": rangos_mes[i][1] if rangos_mes[i] else None,
                "importe": dec_to_str(valores_mensuales[i]),
            }
            for i in range(len(idx_meses))
        ]

        filas.append({
            "fila": header_row_index + 2 + bloque["fila_datos_idx"],
            "clave": clave,
            "concepto_id": concepto_existente["id"] if concepto_existente else None,
            "importe_concepto": dec_to_str(importe_concepto),
            "fecha_inicio_contractual": inicio,
            "fecha_fin_contractual": fin,
            "tiene_distribucion_propia": tiene_distribucion_propia,
            "meses": meses_out,
            "problemas": problemas,
        })
    return filas


_TIPOS_ERROR_PROGRAMA = {
    "importe_ilegible", "concepto_no_encontrado", "distribucion_no_cuadra", "celda_mes_ilegible",
    "rango_mes_ilegible", "rango_fecha_invalido",
}


def _calcular_vista_programa(filas: List[dict], correcciones: dict) -> List[dict]:
    """Overlay de correcciones sobre el resultado inmutable de
    _validar_archivo_programa_completo — recalculado en cada lectura, mismo
    criterio que _calcular_vista_filas del catálogo."""
    vista: List[dict] = []
    for row in filas:
        correccion = correcciones.get(str(row["fila"])) or {}
        descartado = bool(correccion.get("descartar"))
        if descartado:
            estado = "descartado"
        elif not row["tiene_distribucion_propia"]:
            # Renglón de nivel superior sin distribución propia: no es un
            # error (su curva se calcula sumando la de sus hijos, nunca se
            # importa) pero tampoco entra al commit como "ok".
            estado = "sin_distribucion"
        else:
            tipos = {p["tipo"] for p in row["problemas"]}
            estado = "error" if (tipos & _TIPOS_ERROR_PROGRAMA) else "ok"
        vista.append({**row, "correccion": correccion or None, "estado": estado})
    return vista


def _resumen_de_vista_programa(vista: List[dict]) -> dict:
    resumen = {"total": len(vista), "ok": 0, "error": 0, "descartado": 0, "sin_distribucion": 0}
    for row in vista:
        resumen[row["estado"]] = resumen.get(row["estado"], 0) + 1
    return resumen


async def _ejecutar_commit_programa_con_compensacion(
    versiones_col,
    distribucion_col,
    sessions_col,
    log_bitacora: Callable[..., Any],
    pid: str,
    import_id: str,
    etiqueta: str,
    vista: List[dict],
    versiones_vigentes_anteriores: List[dict],
    user: dict,
    filename: Optional[str],
) -> dict:
    """Crea una nueva ProgramaVersion (NUNCA sobrescribe ni borra una
    anterior — los programas se REPROGRAMAN) y un ProgramaDistribucion por
    cada fila 'ok' de la vista ya validada. Mismo patrón de compensación
    manual que _ejecutar_commit_con_compensacion del catálogo (no hay
    certeza de replica set en el Mongo de producción — ver ese docstring
    para el detalle completo del razonamiento)."""
    filas_importables = [f for f in vista if f["estado"] == "ok"]
    if not filas_importables:
        raise HTTPException(
            400,
            "Ningún concepto del archivo quedó en estado 'ok' para importar "
            "(revisa errores o filas sin distribución propia en la vista previa)",
        )

    version_id = str(uuid.uuid4())
    version_doc = {
        "id": version_id, "project_id": pid, "etiqueta": etiqueta,
        "fecha_importacion": datetime.now(timezone.utc), "vigente": True,
        "creado_por": user["id"], "filename": filename,
    }
    compensacion_log: List[dict] = []

    async def _compensar():
        for entry in reversed(compensacion_log):
            try:
                if entry["tipo"] == "version_creada":
                    await versiones_col.delete_one({"id": entry["id"]})
                elif entry["tipo"] == "version_desactivada":
                    await versiones_col.update_one({"id": entry["id"]}, {"$set": {"vigente": True}})
                elif entry["tipo"] == "distribucion_creada":
                    await distribucion_col.delete_one({"id": entry["id"]})
            except Exception as comp_err:
                log.error("[programa_import_commit] fallo compensando %s: %s", entry, comp_err)

    try:
        for v in versiones_vigentes_anteriores:
            compensacion_log.append({"tipo": "version_desactivada", "id": v["id"]})
            await sessions_col.update_one({"id": import_id}, {"$set": {"compensacion_log": compensacion_log}})
            await versiones_col.update_one({"id": v["id"]}, {"$set": {"vigente": False}})

        compensacion_log.append({"tipo": "version_creada", "id": version_id})
        await sessions_col.update_one({"id": import_id}, {"$set": {"compensacion_log": compensacion_log}})
        await versiones_col.insert_one(version_doc)

        creados = 0
        for fila in filas_importables:
            dist_id = str(uuid.uuid4())
            dist_doc = {
                "id": dist_id, "project_id": pid, "programa_version_id": version_id,
                "concepto_id": fila["concepto_id"], "clave": fila["clave"],
                "fecha_inicio_contractual": fila["fecha_inicio_contractual"],
                "fecha_fin_contractual": fila["fecha_fin_contractual"],
                "importe_concepto": fila["importe_concepto"], "meses": fila["meses"],
            }
            compensacion_log.append({"tipo": "distribucion_creada", "id": dist_id})
            await sessions_col.update_one({"id": import_id}, {"$set": {"compensacion_log": compensacion_log}})
            await distribucion_col.insert_one(dist_doc)
            creados += 1
    except Exception as e:
        log.error("[programa_import_commit] fallo a mitad del commit, compensando %d escrituras: %s", len(compensacion_log), e)
        await _compensar()
        raise HTTPException(500, f"La importación del programa falló a mitad de camino y se revirtió automáticamente (no se guardó nada): {e}")

    await log_bitacora(
        pid, "import_programa", "programa_version", version_id, None, None,
        f"versión '{etiqueta}' creada desde importación ({filename}), {creados} conceptos", user,
    )
    return {
        "version_id": version_id,
        "conceptos_importados": creados,
        "sin_distribucion": sum(1 for f in vista if f["estado"] == "sin_distribucion"),
    }


@api.post("/projects/{pid}/programa/import/sheets")
async def programa_import_upload_sheets(pid: str, file: UploadFile = File(...), user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Paso 1 — mismo criterio que el import de catálogo, sesión propia
    (`programa_import_sessions`, no comparte colección con el catálogo
    porque el destino final es distinto)."""
    await ensure_project_access(user, pid)
    content = await file.read()
    if len(content) > 15 * 1024 * 1024:
        raise HTTPException(400, "Archivo demasiado grande (máx. 15MB)")
    sheets = _read_workbook_sheets(file.filename or "archivo.xlsx", content)
    candidatos = [cell for rows in sheets.values() for row in rows for cell in row]
    convencion_detectada = detectar_convencion(candidatos)

    import_id = str(uuid.uuid4())
    await db.programa_import_sessions.insert_one({
        "id": import_id, "project_id": pid, "user_id": user["id"],
        "filename": file.filename, "sheets": {name: rows for name, rows in sheets.items()},
        "convencion_decimal": convencion_detectada, "created_at": datetime.now(timezone.utc),
    })
    return {
        "import_id": import_id, "sheet_names": list(sheets.keys()),
        "requiere_seleccion_hoja": len(sheets) > 1, "convencion_detectada": convencion_detectada,
    }


@api.get("/projects/{pid}/programa/import/pendiente")
async def programa_import_sesion_pendiente(pid: str, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Espejo de import_sesion_pendiente (catálogo) — sesión sin terminar
    más reciente de este usuario en este proyecto, si existe."""
    await ensure_project_access(user, pid)
    session = await db.programa_import_sessions.find_one(
        {"project_id": pid, "user_id": user["id"]},
        sort=[("created_at", -1)],
    )
    if not session:
        return None
    return {
        "import_id": session["id"], "filename": session.get("filename"),
        "created_at": session["created_at"], "sheet_names": list(session.get("sheets", {}).keys()),
        "validado": session.get("validated_rows") is not None,
        "validated_sheet": session.get("validated_sheet"),
        "validated_header_row_index": session.get("validated_header_row_index"),
        "validated_mapping": session.get("validated_mapping"),
        "convencion_usada": session.get("convencion_usada") or session.get("convencion_decimal"),
    }


@api.delete("/projects/{pid}/programa/import/{import_id}")
async def programa_import_descartar_sesion(pid: str, import_id: str, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    await ensure_project_access(user, pid)
    await db.programa_import_sessions.delete_one({"id": import_id, "project_id": pid})
    return {"ok": True}


@api.get("/programa/import/{import_id}/headers")
async def programa_import_headers(
    import_id: str,
    sheet: Optional[str] = None,
    header_row_index: Optional[int] = None,
    user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD)),
):
    """Paso 2 — igual que import_headers del catálogo, pero escanea una
    ventana más ancha buscando la fila de encabezado (el archivo real trae
    membrete/datos de proyecto arriba y el encabezado hasta la fila 19)."""
    session = await db.programa_import_sessions.find_one({"id": import_id})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    await ensure_project_access(user, session["project_id"])
    sheet_name = sheet or next(iter(session["sheets"].keys()))
    if sheet_name not in session["sheets"]:
        raise HTTPException(400, f"La hoja '{sheet_name}' no existe en este archivo")
    rows = session["sheets"][sheet_name]
    if not rows:
        raise HTTPException(400, "La hoja está vacía")

    if header_row_index is None:
        header_row_index = next((i for i, r in enumerate(rows[:30]) if _fila_parece_encabezado(r)), 0)
    if header_row_index >= len(rows):
        raise HTTPException(400, "header_row_index fuera de rango")

    headers = [str(c) if c is not None else "" for c in rows[header_row_index]]
    fila_rangos = rows[header_row_index + 1] if header_row_index + 1 < len(rows) else []
    return {
        "sheet": sheet_name,
        "header_row_index": header_row_index,
        "headers": headers,
        "suggested_mapping": _propose_mapping_programa(headers),
        "fila_rango_fechas": fila_rangos,
        "sample_rows": rows[header_row_index + 2: header_row_index + 7],
        "total_rows": max(len(rows) - header_row_index - 2, 0),
        "convencion_detectada": session.get("convencion_decimal"),
        "preview_rows": rows[: min(len(rows), 30)],
    }


@api.post("/projects/{pid}/programa/import/{import_id}/validate")
async def programa_import_validate(pid: str, import_id: str, body: ProgramaImportValidateIn, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Paso 3 — valida TODO el archivo una sola vez y guarda el resultado en
    la sesión de staging. Volver a llamarlo (cambiar convención, ajustar
    mapeo) recalcula `validated_rows` desde cero, pero nunca toca
    `correcciones` (mismo criterio que import_validate del catálogo)."""
    await ensure_project_access(user, pid)
    session = await db.programa_import_sessions.find_one({"id": import_id, "project_id": pid})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    if body.sheet not in session["sheets"]:
        raise HTTPException(400, f"La hoja '{body.sheet}' no existe en este archivo")

    conceptos_docs = await db.conceptos.find({"project_id": pid, "activo": True}).to_list(length=100000)
    conceptos_by_clave = {c["clave"]: c for c in conceptos_docs}
    convencion = body.convencion or session.get("convencion_decimal")

    filas = _validar_archivo_programa_completo(
        session["sheets"][body.sheet], body.header_row_index, body.mapping, convencion, conceptos_by_clave,
    )

    etiqueta = body.etiqueta.strip() or f"Programa importado {datetime.now(timezone.utc).strftime('%Y-%m-%d')}"
    await db.programa_import_sessions.update_one(
        {"id": import_id},
        {"$set": {
            "validated_rows": filas, "validated_sheet": body.sheet,
            "validated_header_row_index": body.header_row_index,
            "validated_mapping": body.mapping.model_dump(),
            "convencion_usada": convencion, "etiqueta": etiqueta,
            "correcciones": session.get("correcciones") or {},
        }},
    )
    vista = _calcular_vista_programa(filas, session.get("correcciones") or {})
    return {"resumen": _resumen_de_vista_programa(vista), "etiqueta": etiqueta}


@api.get("/programa/import/{import_id}/preview")
async def programa_import_preview(import_id: str, page: int = 1, page_size: int = 50, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    session = await db.programa_import_sessions.find_one({"id": import_id})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    await ensure_project_access(user, session["project_id"])
    validated_rows = session.get("validated_rows")
    if validated_rows is None:
        raise HTTPException(400, "Todavía no se valida esta importación. Llama primero a /validate.")

    correcciones = session.get("correcciones") or {}
    vista = _calcular_vista_programa(validated_rows, correcciones)
    resumen = _resumen_de_vista_programa(vista)

    page = max(page, 1)
    page_size = max(1, min(page_size, 200))
    start = (page - 1) * page_size
    pagina = vista[start:start + page_size]
    total_pages = max(1, (len(vista) + page_size - 1) // page_size)

    return {
        "resumen": resumen, "filas": pagina, "page": page, "page_size": page_size,
        "total_pages": total_pages, "total_rows": len(vista),
        "sheet": session.get("validated_sheet"), "etiqueta": session.get("etiqueta"),
        "convencion_usada": session.get("convencion_usada"),
    }


@api.put("/programa/import/{import_id}/rows/{fila}")
async def programa_import_correct_row(import_id: str, fila: int, body: ProgramaRowCorrectionIn, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Única corrección posible en este importador: descartar una fila (no
    edita cantidad/PU/unidad — este wizard no crea ni edita conceptos)."""
    session = await db.programa_import_sessions.find_one({"id": import_id})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    await ensure_project_access(user, session["project_id"])
    validated_rows = session.get("validated_rows") or []
    if not any(r["fila"] == fila for r in validated_rows):
        raise HTTPException(404, f"Fila {fila} no existe en esta validación")

    correcciones = session.get("correcciones") or {}
    if body.descartar:
        correcciones[str(fila)] = {"descartar": True}
    else:
        correcciones.pop(str(fila), None)
    await db.programa_import_sessions.update_one({"id": import_id}, {"$set": {"correcciones": correcciones}})

    vista = _calcular_vista_programa(validated_rows, correcciones)
    fila_actualizada = next((r for r in vista if r["fila"] == fila), None)
    return {"fila": fila_actualizada, "resumen": _resumen_de_vista_programa(vista)}


@api.post("/projects/{pid}/programa/import/{import_id}/commit")
async def programa_import_commit(pid: str, import_id: str, user: dict = Depends(require_role(ROLE_SUB, ROLE_COORD))):
    """Paso 4 — no recibe body, todo lo necesario ya quedó confirmado en la
    sesión de staging. Marca las versiones vigentes anteriores como no
    vigentes (nunca las borra) y crea la nueva versión + su distribución."""
    await ensure_project_access(user, pid)
    session = await db.programa_import_sessions.find_one({"id": import_id, "project_id": pid})
    if not session:
        raise HTTPException(404, "Sesión de importación no existe o expiró")
    validated_rows = session.get("validated_rows")
    if validated_rows is None:
        raise HTTPException(400, "Todavía no se valida esta importación. Llama primero a /validate.")

    correcciones = session.get("correcciones") or {}
    vista = _calcular_vista_programa(validated_rows, correcciones)
    etiqueta = session.get("etiqueta") or f"Programa importado {datetime.now(timezone.utc).strftime('%Y-%m-%d')}"
    versiones_vigentes = await db.programa_versiones.find({"project_id": pid, "vigente": True}).to_list(length=100)

    try:
        resultado = await _ejecutar_commit_programa_con_compensacion(
            db.programa_versiones, db.programa_distribucion, db.programa_import_sessions, _log_bitacora,
            pid, import_id, etiqueta, vista, versiones_vigentes, user, session.get("filename"),
        )
    finally:
        await db.programa_import_sessions.delete_one({"id": import_id})
    return resultado


@api.get("/projects/{pid}/programa/versiones", response_model=List[ProgramaVersionOut])
async def programa_list_versiones(pid: str, user: dict = Depends(current_user)):
    """Historial de versiones del programa — nunca se borra al reimportar,
    solo se desmarca `vigente`. Más reciente primero."""
    await ensure_project_access(user, pid)
    docs = await db.programa_versiones.find({"project_id": pid}).sort("fecha_importacion", -1).to_list(length=1000)
    return [ProgramaVersionOut(**d) for d in docs]


@api.get("/projects/{pid}/programa/versiones/{version_id}/distribucion", response_model=List[ProgramaDistribucionOut])
async def programa_get_distribucion(pid: str, version_id: str, user: dict = Depends(current_user)):
    await ensure_project_access(user, pid)
    version = await db.programa_versiones.find_one({"id": version_id, "project_id": pid})
    if not version:
        raise HTTPException(404, "Versión de programa no existe en este proyecto")
    docs = await db.programa_distribucion.find({"programa_version_id": version_id}).to_list(length=100000)
    return [ProgramaDistribucionOut(**d) for d in docs]


